const HSK2_DATA = {"lessons":[{"id":1,"title_cn":"她请我们吃了北京烤鸭","title_pinyin":"Tā qǐng wǒmen chīle Běijīng Kǎoyā","title_vn":"Chị ấy đã mời chúng em ăn vịt quay Bắc Kinh","goals":["Có thể nghe hiểu và sử dụng được \"请\", \"让\" và \"叫\" để bày tỏ yêu cầu hoặc thỉnh cầu.","Nắm vững cách dùng của trợ từ ngữ khí \"吧\" (2) để diễn đạt ngữ khí suy đoán hoặc ước tính.","Nắm vững câu \"是……的\" để nhấn mạnh các thông tin như thời gian, địa điểm và cách thức tiến hành của sự việc.","Hiểu về vịt quay Bắc Kinh và cách thưởng thức món ăn này."],"vocab":[{"hanzi":"就","pinyin":"jiù","pos":"phó.","vn":"chính (là), thì","examples":[{"cn":"我就是你说的那个人。","pinyin":"Wǒ jiù shì nǐ shuō de nàge rén.","vn":"Tôi chính là người mà bạn nói đó."},{"cn":"你明天来,我们就一起吃饭。","pinyin":"Nǐ míngtiān lái, wǒmen jiù yìqǐ chīfàn.","vn":"Mai bạn đến thì chúng ta cùng ăn cơm."},{"cn":"他说完就走了。","pinyin":"Tā shuōwán jiù zǒu le.","vn":"Anh ấy nói xong thì đi luôn."}]},{"hanzi":"给","pinyin":"gěi","pos":"giới.","vn":"cho","examples":[{"cn":"我给你买了一本书。","pinyin":"Wǒ gěi nǐ mǎi le yì běn shū.","vn":"Tôi mua cho bạn một quyển sách."},{"cn":"请给我一杯水。","pinyin":"Qǐng gěi wǒ yì bēi shuǐ.","vn":"Làm ơn cho tôi một cốc nước."},{"cn":"他给妈妈打电话了。","pinyin":"Tā gěi māma dǎ diànhuà le.","vn":"Anh ấy gọi điện cho mẹ rồi."}]},{"hanzi":"让","pinyin":"ràng","pos":"dgt.","vn":"bảo, để, cho phép, nhờ","examples":[{"cn":"妈妈让我早点儿回家。","pinyin":"Māma ràng wǒ zǎo diǎnr huí jiā.","vn":"Mẹ bảo tôi về nhà sớm chút."},{"cn":"老师让我们明天考试。","pinyin":"Lǎoshī ràng wǒmen míngtiān kǎoshì.","vn":"Thầy giáo bảo chúng tôi mai thi."},{"cn":"请让我想一想。","pinyin":"Qǐng ràng wǒ xiǎng yi xiǎng.","vn":"Xin hãy để tôi suy nghĩ một chút."}]},{"hanzi":"接","pinyin":"jiē","pos":"dgt.","vn":"đón","examples":[{"cn":"我去机场接你。","pinyin":"Wǒ qù jīchǎng jiē nǐ.","vn":"Tôi đi ra sân bay đón bạn."},{"cn":"爸爸每天去学校接我。","pinyin":"Bàba měitiān qù xuéxiào jiē wǒ.","vn":"Bố hàng ngày đến trường đón tôi."},{"cn":"你几点来接我?","pinyin":"Nǐ jǐ diǎn lái jiē wǒ?","vn":"Mấy giờ bạn đến đón tôi?"}]},{"hanzi":"次","pinyin":"cì","pos":"lượng.","vn":"lần","examples":[{"cn":"我去过两次北京。","pinyin":"Wǒ qùguo liǎng cì Běijīng.","vn":"Tôi đã đi Bắc Kinh hai lần."},{"cn":"这是我第一次吃北京烤鸭。","pinyin":"Zhè shì wǒ dì yī cì chī Běijīng Kǎoyā.","vn":"Đây là lần đầu tiên tôi ăn vịt quay Bắc Kinh."},{"cn":"下次我们再见面吧。","pinyin":"Xià cì wǒmen zài jiànmiàn ba.","vn":"Lần sau chúng ta gặp lại nhé."}]},{"hanzi":"旅游","pinyin":"lǚyóu","pos":"dgt.","vn":"du lịch","examples":[{"cn":"我很喜欢去国外旅游。","pinyin":"Wǒ hěn xǐhuan qù guówài lǚyóu.","vn":"Tôi rất thích đi du lịch nước ngoài."},{"cn":"暑假我们去上海旅游了。","pinyin":"Shǔjià wǒmen qù Shànghǎi lǚyóu le.","vn":"Kỳ nghỉ hè chúng tôi đã đi du lịch Thượng Hải."},{"cn":"你打算什么时候去旅游?","pinyin":"Nǐ dǎsuan shénme shíhou qù lǚyóu?","vn":"Bạn định khi nào đi du lịch?"}]},{"hanzi":"帮忙","pinyin":"bāngmáng","pos":"dgt.","vn":"giúp đỡ","examples":[{"cn":"你能帮我一个忙吗?","pinyin":"Nǐ néng bāng wǒ yí ge máng ma?","vn":"Bạn có thể giúp tôi một việc không?"},{"cn":"谢谢你的帮忙。","pinyin":"Xièxie nǐ de bāngmáng.","vn":"Cảm ơn sự giúp đỡ của bạn."},{"cn":"我可以来帮忙吗?","pinyin":"Wǒ kěyǐ lái bāngmáng ma?","vn":"Tôi có thể đến giúp không?"}]},{"hanzi":"不好意思","pinyin":"bù hǎoyìsi","pos":"","vn":"xin lỗi, áy náy, ngại","examples":[{"cn":"不好意思,我来晚了。","pinyin":"Bù hǎoyìsi, wǒ lái wǎn le.","vn":"Xin lỗi, tôi đến muộn rồi."},{"cn":"不好意思,请问洗手间在哪儿?","pinyin":"Bù hǎoyìsi, qǐngwèn xǐshǒujiān zài nǎr?","vn":"Xin lỗi, cho hỏi nhà vệ sinh ở đâu ạ?"},{"cn":"真不好意思,麻烦你了。","pinyin":"Zhēn bù hǎoyìsi, máfan nǐ le.","vn":"Thật ngại quá, làm phiền bạn rồi."}]},{"hanzi":"已经","pinyin":"yǐjīng","pos":"phó.","vn":"đã","examples":[{"cn":"我已经吃过饭了。","pinyin":"Wǒ yǐjīng chīguo fàn le.","vn":"Tôi đã ăn cơm rồi."},{"cn":"他已经走了。","pinyin":"Tā yǐjīng zǒu le.","vn":"Anh ấy đã đi rồi."},{"cn":"现在已经十点了。","pinyin":"Xiànzài yǐjīng shí diǎn le.","vn":"Bây giờ đã mười giờ rồi."}]},{"hanzi":"那","pinyin":"nà","pos":"liên.","vn":"vậy, vậy thì, thế thì","examples":[{"cn":"你不想去,那我们就别去了。","pinyin":"Nǐ bù xiǎng qù, nà wǒmen jiù bié qù le.","vn":"Bạn không muốn đi, vậy thì chúng ta đừng đi nữa."},{"cn":"那你觉得怎么样?","pinyin":"Nà nǐ juéde zěnmeyàng?","vn":"Vậy bạn thấy thế nào?"},{"cn":"那我先走了。","pinyin":"Nà wǒ xiān zǒu le.","vn":"Vậy thì tôi đi trước nhé."}]},{"hanzi":"介绍","pinyin":"jièshào","pos":"dgt.","vn":"giới thiệu","examples":[{"cn":"我来介绍一下我的朋友。","pinyin":"Wǒ lái jièshào yíxià wǒ de péngyou.","vn":"Để tôi giới thiệu một chút về bạn tôi."},{"cn":"你能给我介绍一个好老师吗?","pinyin":"Nǐ néng gěi wǒ jièshào yí ge hǎo lǎoshī ma?","vn":"Bạn có thể giới thiệu cho tôi một giáo viên tốt không?"},{"cn":"他给我们介绍了北京大学。","pinyin":"Tā gěi wǒmen jièshào le Běijīng Dàxué.","vn":"Anh ấy đã giới thiệu cho chúng tôi về Đại học Bắc Kinh."}]},{"hanzi":"有时","pinyin":"yǒushí","pos":"phó.","vn":"có lúc, có khi","examples":[{"cn":"我有时也会想家。","pinyin":"Wǒ yǒushí yě huì xiǎngjiā.","vn":"Tôi có lúc cũng nhớ nhà."},{"cn":"他有时很忙,有时很闲。","pinyin":"Tā yǒushí hěn máng, yǒushí hěn xián.","vn":"Anh ấy có lúc rất bận, có lúc rất rảnh."},{"cn":"有时我自己做饭,有时去饭馆吃。","pinyin":"Yǒushí wǒ zìjǐ zuò fàn, yǒushí qù fànguǎn chī.","vn":"Có lúc tôi tự nấu cơm, có lúc đi ăn quán."}]},{"hanzi":"懂","pinyin":"dǒng","pos":"dgt.","vn":"hiểu","examples":[{"cn":"你懂我的意思吗?","pinyin":"Nǐ dǒng wǒ de yìsi ma?","vn":"Bạn hiểu ý tôi không?"},{"cn":"这个汉字我不懂。","pinyin":"Zhège hànzì wǒ bù dǒng.","vn":"Chữ Hán này tôi không hiểu."},{"cn":"他听懂了老师的话。","pinyin":"Tā tīngdǒng le lǎoshī de huà.","vn":"Anh ấy nghe hiểu lời thầy giáo nói."}]},{"hanzi":"意思","pinyin":"yìsi","pos":"dt.","vn":"ý, ý nghĩa","examples":[{"cn":"这个词是什么意思?","pinyin":"Zhège cí shì shénme yìsi?","vn":"Từ này có nghĩa là gì?"},{"cn":"我明白你的意思了。","pinyin":"Wǒ míngbai nǐ de yìsi le.","vn":"Tôi hiểu ý của bạn rồi."},{"cn":"他说的话很有意思。","pinyin":"Tā shuō de huà hěn yǒu yìsi.","vn":"Lời anh ấy nói rất thú vị."}]},{"hanzi":"北京烤鸭","pinyin":"Běijīng Kǎoyā","pos":"danh từ riêng","vn":"vịt quay Bắc Kinh","examples":[{"cn":"我很想吃北京烤鸭。","pinyin":"Wǒ hěn xiǎng chī Běijīng Kǎoyā.","vn":"Tôi rất muốn ăn vịt quay Bắc Kinh."},{"cn":"北京烤鸭非常有名。","pinyin":"Běijīng Kǎoyā fēicháng yǒumíng.","vn":"Vịt quay Bắc Kinh rất nổi tiếng."},{"cn":"我们今天晚上去吃北京烤鸭吧。","pinyin":"Wǒmen jīntiān wǎnshang qù chī Běijīng Kǎoyā ba.","vn":"Tối nay chúng ta đi ăn vịt quay Bắc Kinh nhé."}]}],"grammar":[{"title":"语气助词“吧”(2)","explanation_vn":"Trợ từ ngữ khí \"吧\" đặt cuối câu nghi vấn để diễn đạt ngữ khí suy đoán hoặc ước tính.","examples":[{"cn":"你们就是她的学生吧？","pinyin":"Nǐmen jiù shì tā de xuésheng ba?","vn":""},{"cn":"她唱歌很好听吧？","pinyin":"Tā chànggē hěn hǎotīng ba?","vn":""},{"cn":"陈天中是泰国人吧？","pinyin":"Chén Tiānzhōng shì Tàiguó rén ba?","vn":""}]},{"title":"“是……的”句","explanation_vn":"Câu \"是……的\" dùng để nhấn mạnh thời gian, địa điểm, cách thức, người thực hiện động tác, mục đích... của sự việc. Trong câu khẳng định và câu nghi vấn có thể lược bỏ \"是\", trong câu phủ định không được lược bỏ \"是\".","examples":[{"cn":"我们是来旅游的。","pinyin":"Wǒmen shì lái lǚyóu de.","vn":""},{"cn":"苹果在哪儿买的？","pinyin":"Píngguǒ zài nǎr mǎi de?","vn":""},{"cn":"我们不是坐出租车去的。","pinyin":"Wǒmen bú shì zuò chūzūchē qù de.","vn":""}]},{"title":"兼语句","explanation_vn":"Vị ngữ của câu kiêm ngữ được tạo thành bởi hai cụm động từ, trong đó tân ngữ của động từ thứ nhất là chủ ngữ của động từ thứ hai. Khi động từ thứ nhất là \"请\", \"让\", \"叫\", dùng để biểu thị ý mời, phiền, nhờ, cho phép, yêu cầu, sai bảo... ai đó làm gì. Cấu trúc cơ bản: Chủ ngữ + 请/让/叫 + tân ngữ (→ chủ ngữ) + động từ hoặc cụm động từ.","examples":[{"cn":"我想请你帮个忙。","pinyin":"Wǒ xiǎng qǐng nǐ bāng ge máng.","vn":""},{"cn":"王老师让我们说中文。","pinyin":"Wáng lǎoshī ràng wǒmen shuō Zhōngwén.","vn":""},{"cn":"妈妈叫孩子们回家。","pinyin":"Māma jiào háizimen huí jiā.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"请问，您是王一飞老师的姐姐吗？","pinyin":"Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?"},{"speaker":"王一雪","cn":"是的，你们就是她的学生吧？","pinyin":"Shì de, nǐmen jiù shì tā de xuésheng ba?"},{"speaker":"白家月","cn":"对。我是白家月，她是安妮。","pinyin":"Duì. Wǒ shì Bái Jiāyuè, tā shì Ānní."},{"speaker":"王一雪","cn":"你们好，我叫王一雪。一飞给我打电话了，让我来接你们。","pinyin":"Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen."},{"speaker":"白家月/安妮","cn":"谢谢您。","pinyin":"Xièxie nín."},{"speaker":"王一雪","cn":"不客气。","pinyin":"Bù kèqi."}],"translation_vn":"Bạch Gia Nguyệt: Xin hỏi, chị là chị gái của cô Vương Nhất Phi phải không ạ?\nVương Nhất Tuyết: Đúng rồi, các em là học sinh của cô ấy phải không?\nBạch Gia Nguyệt: Vâng ạ, em là Bạch Gia Nguyệt, bạn ấy là Annie.\nVương Nhất Tuyết: Chào các em. Chị tên là Vương Nhất Tuyết. Nhất Phi đã gọi điện thoại cho chị, nhờ chị đến đón các em.\nBạch Gia Nguyệt, Annie: Chúng em cảm ơn chị ạ.\nVương Nhất Tuyết: Đừng khách sáo vậy.","audio_dialogue":"1-1.mp3","audio_vocab":"1-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"你们是第一次来北京吗？","pinyin":"Nǐmen shì dì-yī cì lái Běijīng ma?"},{"speaker":"白家月","cn":"是的，我们都是第一次来。","pinyin":"Shì de, wǒmen dōu shì dì-yī cì lái."},{"speaker":"王一雪","cn":"你们是来学中文的吗？","pinyin":"Nǐmen shì lái xué Zhōngwén de ma?"},{"speaker":"安妮","cn":"不是，我们是来旅游的。","pinyin":"Bú shì, wǒmen shì lái lǚyóu de."},{"speaker":"王一雪","cn":"我这几天都不忙，你们有事就找我。","pinyin":"Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ."},{"speaker":"白家月","cn":"好的，谢谢您。","pinyin":"Hǎo de, xièxie nín."}],"translation_vn":"Vương Nhất Tuyết: Đây là lần đầu các em đến Bắc Kinh phải không?\nBạch Gia Nguyệt: Vâng ạ, chúng em đều là lần đầu tiên đến đây ạ.\nVương Nhất Tuyết: Các em đến học tiếng Trung Quốc à?\nAnnie: Không phải, chúng em đến du lịch ạ.\nVương Nhất Tuyết: Mấy hôm nay chị đều không bận, các em có việc gì thì cứ tìm chị nhé.\nBạch Gia Nguyệt: Vâng ạ, cảm ơn chị.","audio_dialogue":"1-3.mp3","audio_vocab":"1-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"陈天中","cn":"喂，家月，你明天有时间吗？我想请你帮个忙。","pinyin":"Wéi, Jiāyuè, nǐ míngtiān yǒu shíjiān ma? Wǒ xiǎng qǐng nǐ bāng ge máng."},{"speaker":"白家月","cn":"不好意思，天中，我已经到北京了。","pinyin":"Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le."},{"speaker":"陈天中","cn":"你是什么时候到的？","pinyin":"Nǐ shì shénme shíhou dào de?"},{"speaker":"白家月","cn":"我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。","pinyin":"Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne."},{"speaker":"陈天中","cn":"好的，那我给他打个电话。","pinyin":"Hǎo de, nà wǒ gěi tā dǎ ge diànhuà."},{"speaker":"白家月","cn":"好，再见！","pinyin":"Hǎo, zàijiàn!"}],"translation_vn":"Trần Thiên Trung: Alô, Gia Nguyệt à, mai bạn có thời gian không? Mình muốn nhờ bạn giúp một việc.\nBạch Gia Nguyệt: Xin lỗi Thiên Trung nhé, mình đã đến Bắc Kinh rồi.\nTrần Thiên Trung: Bạn đến khi nào vậy?\nBạch Gia Nguyệt: Sáng hôm nay mình đến. Nếu bạn cần giúp đỡ gì thì có thể nhờ Lý Văn nhé, bạn ấy vẫn đang ở trường.\nTrần Thiên Trung: Được rồi, vậy mình sẽ gọi điện thoại cho bạn ấy.\nBạch Gia Nguyệt: Ừ, tạm biệt nhé.","audio_dialogue":"1-5 @xitoytili_luoluodafang.mp3","audio_vocab":"1-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"王老师，我们已经到北京了，是您姐姐来接的我们。她请我们吃了北京烤鸭，还给我们介绍了很多东西。我们的中文不太好，有时不太懂她的意思。","pinyin":"Wáng lǎoshī, wǒmen yǐjīng dào Běijīng le, shì nín jiějie lái jiē de wǒmen. Tā qǐng wǒmen chīle Běijīng Kǎoyā, hái gěi wǒmen jièshàole hěnduō dōngxi. Wǒmen de Zhōngwén bù tài hǎo, yǒushí bù tài dǒng tā de yìsi."}],"translation_vn":"Thưa cô Vương, chúng em đã tới Bắc Kinh rồi, chị gái của cô đã tới đón chúng em. Chị ấy đã mời chúng em ăn vịt quay Bắc Kinh, còn giới thiệu cho chúng em rất nhiều thứ. Tiếng Trung Quốc của chúng em không tốt lắm, đôi khi chưa hiểu hết ý của chị ấy.","audio_dialogue":"1-7 @xitoytili_luoluodafang.mp3","audio_vocab":"1-8 @xitoytili_luoluodafang.mp3"}]},{"id":2,"title_cn":"还是打车去北大吧","title_pinyin":"Háishi dǎchē qù Běidà ba","title_vn":"Chúng ta vẫn nên gọi taxi đi Đại học Bắc Kinh nhé","goals":["Có thể nghe hiểu và giới thiệu được thông tin cơ bản của một trường học.","Có thể nghe hiểu và sử dụng được \"多\" để diễn đạt số lượng ước lượng.","Nắm vững cách dùng của cấu trúc cố định \"还是……吧\" để diễn đạt sự lựa chọn.","Hiểu về Đại học Bắc Kinh – một trường đại học danh tiếng của Trung Quốc."],"vocab":[{"hanzi":"公交车","pinyin":"gōngjiāochē","pos":"dt.","vn":"xe buýt","examples":[{"cn":"我每天坐公交车上班。","pinyin":"Wǒ měitiān zuò gōngjiāochē shàngbān.","vn":"Tôi hàng ngày đi xe buýt đi làm."},{"cn":"公交车来了,快走吧。","pinyin":"Gōngjiāochē lái le, kuài zǒu ba.","vn":"Xe buýt đến rồi, đi nhanh thôi."},{"cn":"这儿附近有公交车站吗?","pinyin":"Zhèr fùjìn yǒu gōngjiāochē zhàn ma?","vn":"Gần đây có bến xe buýt không?"}]},{"hanzi":"但","pinyin":"dàn","pos":"liên.","vn":"nhưng, nhưng mà","examples":[{"cn":"这件衣服很好看,但太贵了。","pinyin":"Zhè jiàn yīfu hěn hǎokàn, dàn tài guì le.","vn":"Cái áo này rất đẹp, nhưng đắt quá."},{"cn":"我很想去,但是没有时间。","pinyin":"Wǒ hěn xiǎng qù, dàn shì méiyǒu shíjiān.","vn":"Tôi rất muốn đi, nhưng không có thời gian."},{"cn":"他很累,但还在工作。","pinyin":"Tā hěn lèi, dàn hái zài gōngzuò.","vn":"Anh ấy rất mệt, nhưng vẫn đang làm việc."}]},{"hanzi":"车站","pinyin":"chēzhàn","pos":"dt.","vn":"bến xe buýt","examples":[{"cn":"车站离这儿不远。","pinyin":"Chēzhàn lí zhèr bù yuǎn.","vn":"Bến xe cách đây không xa."},{"cn":"我在车站等你。","pinyin":"Wǒ zài chēzhàn děng nǐ.","vn":"Tôi đợi bạn ở bến xe."},{"cn":"前面就是车站。","pinyin":"Qiánmiàn jiù shì chēzhàn.","vn":"Phía trước chính là bến xe."}]},{"hanzi":"远","pinyin":"yuǎn","pos":"tt.","vn":"xa","examples":[{"cn":"你家离学校远吗?","pinyin":"Nǐ jiā lí xuéxiào yuǎn ma?","vn":"Nhà bạn cách trường có xa không?"},{"cn":"这儿离北京大学不远。","pinyin":"Zhèr lí Běijīng Dàxué bù yuǎn.","vn":"Chỗ này cách Đại học Bắc Kinh không xa."},{"cn":"太远了,我们打车去吧。","pinyin":"Tài yuǎn le, wǒmen dǎchē qù ba.","vn":"Xa quá, chúng ta bắt taxi đi thôi."}]},{"hanzi":"打车","pinyin":"dǎchē","pos":"dgt.","vn":"gọi xe, đi xe, bắt (taxi)","examples":[{"cn":"下雨了,我们打车去吧。","pinyin":"Xià yǔ le, wǒmen dǎchē qù ba.","vn":"Trời mưa rồi, chúng ta bắt taxi đi thôi."},{"cn":"我在网上打车。","pinyin":"Wǒ zài wǎngshang dǎchē.","vn":"Tôi gọi taxi trên mạng."},{"cn":"从这儿打车要多少钱?","pinyin":"Cóng zhèr dǎchē yào duōshao qián?","vn":"Từ đây bắt taxi hết bao nhiêu tiền?"}]},{"hanzi":"还是","pinyin":"háishi","pos":"phó.","vn":"vẫn, tốt hơn là...","examples":[{"cn":"我们还是坐公交车去吧。","pinyin":"Wǒmen háishi zuò gōngjiāochē qù ba.","vn":"Chúng ta tốt hơn là đi xe buýt đi."},{"cn":"他还是那么忙。","pinyin":"Tā háishi nàme máng.","vn":"Anh ấy vẫn bận như vậy."},{"cn":"你还是早点儿休息吧。","pinyin":"Nǐ háishi zǎo diǎnr xiūxi ba.","vn":"Bạn tốt hơn là nghỉ sớm chút đi."}]},{"hanzi":"北京大学","pinyin":"Běijīng Dàxué","pos":"danh từ riêng","vn":"Đại học Bắc Kinh","examples":[{"cn":"我哥哥在北京大学学习。","pinyin":"Wǒ gēge zài Běijīng Dàxué xuéxí.","vn":"Anh trai tôi học ở Đại học Bắc Kinh."},{"cn":"北京大学很有名。","pinyin":"Běijīng Dàxué hěn yǒumíng.","vn":"Đại học Bắc Kinh rất nổi tiếng."},{"cn":"我想考北京大学。","pinyin":"Wǒ xiǎng kǎo Běijīng Dàxué.","vn":"Tôi muốn thi vào Đại học Bắc Kinh."}]},{"hanzi":"啊","pinyin":"a","pos":"trợ.","vn":"trợ từ ngữ khí","examples":[{"cn":"你今天真漂亮啊!","pinyin":"Nǐ jīntiān zhēn piàoliang a!","vn":"Hôm nay bạn đẹp quá đi!"},{"cn":"这个菜真好吃啊!","pinyin":"Zhège cài zhēn hǎochī a!","vn":"Món này ngon quá đi!"},{"cn":"是啊,我也这么想。","pinyin":"Shì a, wǒ yě zhème xiǎng.","vn":"Đúng vậy, tôi cũng nghĩ như vậy."}]},{"hanzi":"万","pinyin":"wàn","pos":"số.","vn":"vạn, mười nghìn","examples":[{"cn":"这辆车要十万块钱。","pinyin":"Zhè liàng chē yào shí wàn kuài qián.","vn":"Chiếc xe này giá mười vạn tệ."},{"cn":"北京有两千多万人。","pinyin":"Běijīng yǒu liǎngqiān duō wàn rén.","vn":"Bắc Kinh có hơn hai nghìn vạn người."},{"cn":"这本书卖了一万多本。","pinyin":"Zhè běn shū mài le yí wàn duō běn.","vn":"Quyển sách này đã bán hơn một vạn cuốn."}]},{"hanzi":"名","pinyin":"míng","pos":"lượng./dt.","vn":"(lượng từ chỉ người); thứ hạng trong cuộc thi, tên","examples":[{"cn":"班里有三十名学生。","pinyin":"Bān li yǒu sānshí míng xuésheng.","vn":"Trong lớp có ba mươi học sinh."},{"cn":"他考试得了第一名。","pinyin":"Tā kǎoshì dé le dì yī míng.","vn":"Anh ấy thi được hạng nhất."},{"cn":"我们班有两名老师。","pinyin":"Wǒmen bān yǒu liǎng míng lǎoshī.","vn":"Lớp chúng tôi có hai giáo viên."}]},{"hanzi":"网上","pinyin":"wǎngshang","pos":"dt.","vn":"trên mạng","examples":[{"cn":"我喜欢在网上买东西。","pinyin":"Wǒ xǐhuan zài wǎngshang mǎi dōngxi.","vn":"Tôi thích mua đồ trên mạng."},{"cn":"网上的消息不一定都是真的。","pinyin":"Wǎngshang de xiāoxi bù yídìng dōu shì zhēn de.","vn":"Tin tức trên mạng không chắc đều là thật."},{"cn":"我在网上查了一下天气。","pinyin":"Wǒ zài wǎngshang chá le yíxià tiānqì.","vn":"Tôi đã tra thời tiết trên mạng."}]},{"hanzi":"外国","pinyin":"wàiguó","pos":"dt.","vn":"nước ngoài","examples":[{"cn":"我想去外国旅游。","pinyin":"Wǒ xiǎng qù wàiguó lǚyóu.","vn":"Tôi muốn đi du lịch nước ngoài."},{"cn":"他是外国人。","pinyin":"Tā shì wàiguó rén.","vn":"Anh ấy là người nước ngoài."},{"cn":"这是一本外国小说。","pinyin":"Zhè shì yì běn wàiguó xiǎoshuō.","vn":"Đây là một quyển tiểu thuyết nước ngoài."}]},{"hanzi":"间","pinyin":"jiān","pos":"lượng.","vn":"gian, căn (phòng)","examples":[{"cn":"这间教室很大。","pinyin":"Zhè jiān jiàoshì hěn dà.","vn":"Phòng học này rất rộng."},{"cn":"我家有三间房间。","pinyin":"Wǒ jiā yǒu sān jiān fángjiān.","vn":"Nhà tôi có ba căn phòng."},{"cn":"那间房子是我的。","pinyin":"Nà jiān fángzi shì wǒ de.","vn":"Căn nhà đó là của tôi."}]},{"hanzi":"教室","pinyin":"jiàoshì","pos":"dt.","vn":"phòng học","examples":[{"cn":"学生们都在教室里上课。","pinyin":"Xuéshengmen dōu zài jiàoshì li shàngkè.","vn":"Các học sinh đều đang học trong phòng học."},{"cn":"教室里没有人。","pinyin":"Jiàoshì li méiyǒu rén.","vn":"Trong phòng học không có ai."},{"cn":"我们的教室在二楼。","pinyin":"Wǒmen de jiàoshì zài èr lóu.","vn":"Phòng học của chúng tôi ở tầng hai."}]},{"hanzi":"票","pinyin":"piào","pos":"dt.","vn":"vé","examples":[{"cn":"我买了两张电影票。","pinyin":"Wǒ mǎi le liǎng zhāng diànyǐng piào.","vn":"Tôi đã mua hai vé xem phim."},{"cn":"火车票卖完了。","pinyin":"Huǒchē piào mài wán le.","vn":"Vé tàu bán hết rồi."},{"cn":"这张票多少钱?","pinyin":"Zhè zhāng piào duōshao qián?","vn":"Vé này giá bao nhiêu?"}]},{"hanzi":"别","pinyin":"bié","pos":"phó.","vn":"đừng","examples":[{"cn":"别担心,没事的。","pinyin":"Bié dānxīn, méishì de.","vn":"Đừng lo, không sao đâu."},{"cn":"别说话了,老师来了。","pinyin":"Bié shuōhuà le, lǎoshī lái le.","vn":"Đừng nói chuyện nữa, thầy giáo đến rồi."},{"cn":"你别走,等一下我。","pinyin":"Nǐ bié zǒu, děng yíxià wǒ.","vn":"Bạn đừng đi, đợi tôi một chút."}]},{"hanzi":"过来","pinyin":"guòlái","pos":"dgt.","vn":"đến, đến đây","examples":[{"cn":"你过来一下,我有事找你。","pinyin":"Nǐ guòlái yíxià, wǒ yǒu shì zhǎo nǐ.","vn":"Bạn đến đây một chút, tôi có việc tìm bạn."},{"cn":"他从那边走过来了。","pinyin":"Tā cóng nàbiān zǒu guòlái le.","vn":"Anh ấy từ bên đó đi đến đây."},{"cn":"快过来帮我一下。","pinyin":"Kuài guòlái bāng wǒ yíxià.","vn":"Nhanh đến đây giúp tôi một chút."}]}],"grammar":[{"title":"固定格式“还是……吧”","explanation_vn":"Cấu trúc cố định \"还是……吧\" dùng để chỉ lựa chọn thiên về một hướng nào đó, có ý \"làm vậy sẽ tốt hơn\".","examples":[{"cn":"我还是打车去吧。","pinyin":"Wǒ háishi dǎchē qù ba.","vn":""},{"cn":"那件衣服很好看，还是买那件吧。","pinyin":"Nà jiàn yīfu hěn hǎokàn, háishi mǎi nà jiàn ba.","vn":""},{"cn":"你第一次去北京，还是找个人接你吧。","pinyin":"Nǐ dì-yī cì qù Běijīng, háishi zhǎo ge rén jiē nǐ ba.","vn":""}]},{"title":"用“多”表达概数","explanation_vn":"\"多\" được đặt sau số từ hoặc số lượng từ để chỉ số lẻ (có dư). Khi con số là bội số của 10, \"多\" thường đặt sau số từ; khi con số không phải là bội số của 10, \"多\" thường đặt sau lượng từ.","examples":[{"cn":"北京大学有四万多名学生呢！","pinyin":"Běijīng Dàxué yǒu sìwàn duō míng xuésheng ne!","vn":""},{"cn":"教室里有二十多个学生。","pinyin":"Jiàoshì lǐ yǒu èrshí duō ge xuésheng.","vn":""},{"cn":"这两个苹果五块多钱。","pinyin":"Zhè liǎng ge píngguǒ wǔ kuài duō qián.","vn":""}]},{"title":"动词或动词性短语、主谓短语作定语","explanation_vn":"Động từ, cụm động từ, cụm chủ vị đặt trước danh từ, biểu thị đặc trưng hoặc trạng thái của danh từ.","examples":[{"cn":"他们卖的电影票也很便宜。","pinyin":"Tāmen mài de diànyǐngpiào yě hěn piányi.","vn":""},{"cn":"现在学中文的学生很多。","pinyin":"Xiànzài xué Zhōngwén de xuésheng hěn duō.","vn":""},{"cn":"这是朋友给我的杯子。","pinyin":"Zhè shì péngyou gěi wǒ de bēizi.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"请问，这儿有到北京大学的公交车吗？","pinyin":"Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?"},{"speaker":"服务员","cn":"有，但车站有点儿远。","pinyin":"Yǒu, dàn chēzhàn yǒudiǎn yuǎn."},{"speaker":"白家月","cn":"这儿好打车吗？","pinyin":"Zhèr hǎo dǎchē ma?"},{"speaker":"服务员","cn":"好打车。","pinyin":"Hǎo dǎchē."},{"speaker":"白家月","cn":"谢谢。安妮，我们还是打车去吧。","pinyin":"Xièxie. Ānní, wǒmen háishi dǎchē qù ba."},{"speaker":"安妮","cn":"好，没问题。","pinyin":"Hǎo, méi wèntí."}],"translation_vn":"Bạch Gia Nguyệt: Xin hỏi, ở đây có xe buýt đi đến Đại học Bắc Kinh không?\nNhân viên phục vụ: Có đấy, nhưng bến xe buýt hơi xa.\nBạch Gia Nguyệt: Ở đây gọi xe taxi có dễ không vậy?\nNhân viên phục vụ: Dễ gọi.\nBạch Gia Nguyệt: Cảm ơn! Annie, chúng ta vẫn nên gọi xe taxi đi thôi.\nAnnie: Được, không vấn đề gì cả.","audio_dialogue":"2-1 @xitoytili_luoluodafang.mp3","audio_vocab":"2-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"学校里人真多啊！","pinyin":"Xuéxiào lǐ rén zhēn duō a!"},{"speaker":"安妮","cn":"是啊，北京大学有四万多名学生呢！","pinyin":"Shì a, Běijīng Dàxué yǒu sìwàn duō míng xuésheng ne!"},{"speaker":"白家月","cn":"你是怎么知道的？","pinyin":"Nǐ shì zěnme zhīdào de?"},{"speaker":"安妮","cn":"是网上说的，网上还说北京大学有三千多名外国学生。","pinyin":"Shì wǎngshàng shuō de, wǎngshàng hái shuō Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuésheng."},{"speaker":"白家月","cn":"我也想来这儿学习。","pinyin":"Wǒ yě xiǎng lái zhèr xuéxí."},{"speaker":"安妮","cn":"那边就有一间教室，我们去看一下吧。","pinyin":"Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba."}],"translation_vn":"Bạch Gia Nguyệt: Trường học đông người quá!\nAnnie: Đúng vậy, Đại học Bắc Kinh có hơn 40 000 sinh viên.\nBạch Gia Nguyệt: Làm sao bạn biết được thế?\nAnnie: Là thông tin trên mạng nói vậy, trên mạng còn cho biết Đại học Bắc Kinh có hơn 3 000 sinh viên nước ngoài.\nBạch Gia Nguyệt: Mình cũng muốn đến đây học tập.\nAnnie: Đằng kia có một phòng học, chúng ta đến xem đi.","audio_dialogue":"2-3 @xitoytili_luoluodafang.mp3","audio_vocab":"2-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"安妮","cn":"家月，你看，学校里有家电影院！","pinyin":"Jiāyuè, nǐ kàn, xuéxiào lǐ yǒu jiā diànyǐngyuàn!"},{"speaker":"白家月","cn":"是啊，电影院还不小。","pinyin":"Shì a, diànyǐngyuàn hái bù xiǎo."},{"speaker":"安妮","cn":"他们卖的电影票也很便宜。","pinyin":"Tāmen mài de diànyǐngpiào yě hěn piányi."},{"speaker":"白家月","cn":"天啊！有的还不到二十块钱。","pinyin":"Tiān a! Yǒude hái bú dào èrshí kuài qián."},{"speaker":"安妮","cn":"那你想不想去看个电影？","pinyin":"Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?"},{"speaker":"白家月","cn":"还是别看电影了，北京大学就很好看！","pinyin":"Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!"}],"translation_vn":"Annie: Gia Nguyệt, bạn nhìn kìa, trong trường có rạp chiếu phim đấy!\nBạch Gia Nguyệt: Đúng rồi, rạp chiếu phim cũng không nhỏ.\nAnnie: Họ bán vé xem phim cũng rất rẻ nhé.\nBạch Gia Nguyệt: Trời, có loại vé còn không đến 20 đồng kia.\nAnnie: Thế bạn có muốn đi xem phim không?\nBạch Gia Nguyệt: Thôi đừng xem phim nữa, Đại học Bắc Kinh đã rất đẹp rồi.","audio_dialogue":"2-5 @xitoytili_luoluodafang.mp3","audio_vocab":"2-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"北京大学很大，有四万多名学生。学校很漂亮，里边还有家电影院，电影票也不贵。我们有时间还想再过来看个电影。","pinyin":"Běijīng Dàxué hěn dà, yǒu sìwàn duō míng xuésheng. Xuéxiào hěn piàoliang, lǐbian hái yǒu jiā diànyǐngyuàn, diànyǐngpiào yě bù guì. Wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng."}],"translation_vn":"Đại học Bắc Kinh rất lớn, có hơn 40 000 sinh viên. Trường rất đẹp, trong trường còn có rạp chiếu phim, vé xem phim cũng không đắt, chúng tôi vẫn muốn quay lại để xem phim nếu có thời gian.","audio_dialogue":"2-7.mp3","audio_vocab":"2-8 @xitoytili_luoluodafang.mp3"}]},{"id":3,"title_cn":"我想去西安旅游","title_pinyin":"Wǒ xiǎng qù Xī'ān lǚyóu","title_vn":"Em muốn đi Tây An du lịch","goals":["Có thể nghe hiểu và hỏi được nguyên nhân của sự việc.","Nắm vững cách dùng của bổ ngữ kết quả để miêu tả kết quả của hành động.","Nắm vững cách dùng của động từ lặp lại để diễn đạt thời gian ngắn của hành động, số lượng ít hoặc thử làm gì.","Hiểu về các điểm tham quan du lịch ở Tây An."],"vocab":[{"hanzi":"回来","pinyin":"huílái","pos":"dgt.","vn":"quay về, quay lại","examples":[{"cn":"你什么时候回来?","pinyin":"Nǐ shénme shíhou huílái?","vn":"Khi nào bạn quay về?"},{"cn":"他已经回来了。","pinyin":"Tā yǐjīng huílái le.","vn":"Anh ấy đã quay về rồi."},{"cn":"我明天就回来。","pinyin":"Wǒ míngtiān jiù huílái.","vn":"Ngày mai tôi sẽ quay về."}]},{"hanzi":"这么","pinyin":"zhème","pos":"đt.","vn":"như vậy","examples":[{"cn":"你怎么这么晚才来?","pinyin":"Nǐ zěnme zhème wǎn cái lái?","vn":"Sao bạn đến muộn như vậy?"},{"cn":"别这么说。","pinyin":"Bié zhème shuō.","vn":"Đừng nói như vậy."},{"cn":"这个菜这么好吃!","pinyin":"Zhège cài zhème hǎochī!","vn":"Món này ngon như vậy!"}]},{"hanzi":"完","pinyin":"wán","pos":"dgt.","vn":"xong","examples":[{"cn":"我做完作业了。","pinyin":"Wǒ zuòwán zuòyè le.","vn":"Tôi làm xong bài tập rồi."},{"cn":"你吃完饭了吗?","pinyin":"Nǐ chīwán fàn le ma?","vn":"Bạn ăn xong cơm chưa?"},{"cn":"电影看完了。","pinyin":"Diànyǐng kànwán le.","vn":"Phim xem xong rồi."}]},{"hanzi":"一起","pinyin":"yìqǐ","pos":"phó.","vn":"cùng, cùng nhau","examples":[{"cn":"我们一起去吃饭吧。","pinyin":"Wǒmen yìqǐ qù chīfàn ba.","vn":"Chúng ta cùng đi ăn cơm nhé."},{"cn":"他们俩一起长大的。","pinyin":"Tāmen liǎ yìqǐ zhǎngdà de.","vn":"Hai người họ cùng nhau lớn lên."},{"cn":"你跟我一起走吧。","pinyin":"Nǐ gēn wǒ yìqǐ zǒu ba.","vn":"Bạn đi cùng tôi nhé."}]},{"hanzi":"出去","pinyin":"chūqù","pos":"dgt.","vn":"đi ra, đi khỏi, đi","examples":[{"cn":"我想出去走走。","pinyin":"Wǒ xiǎng chūqù zǒuzou.","vn":"Tôi muốn ra ngoài đi dạo."},{"cn":"他出去了,还没回来。","pinyin":"Tā chūqù le, hái méi huílái.","vn":"Anh ấy ra ngoài rồi, vẫn chưa về."},{"cn":"外面下雨了,别出去了。","pinyin":"Wàimiàn xià yǔ le, bié chūqù le.","vn":"Ngoài trời mưa rồi, đừng ra ngoài nữa."}]},{"hanzi":"洗","pinyin":"xǐ","pos":"dgt.","vn":"rửa","examples":[{"cn":"吃饭以前要洗手。","pinyin":"Chīfàn yǐqián yào xǐ shǒu.","vn":"Trước khi ăn cơm phải rửa tay."},{"cn":"我每天晚上洗澡。","pinyin":"Wǒ měitiān wǎnshang xǐzǎo.","vn":"Tôi tối nào cũng tắm."},{"cn":"你帮我洗一下衣服吧。","pinyin":"Nǐ bāng wǒ xǐ yíxià yīfu ba.","vn":"Bạn giúp tôi giặt quần áo chút nhé."}]},{"hanzi":"自己","pinyin":"zìjǐ","pos":"đt.","vn":"tự, tự thân, bản thân","examples":[{"cn":"这是我自己做的菜。","pinyin":"Zhè shì wǒ zìjǐ zuò de cài.","vn":"Đây là món tôi tự nấu."},{"cn":"孩子应该学会自己照顾自己。","pinyin":"Háizi yīnggāi xuéhuì zìjǐ zhàogu zìjǐ.","vn":"Trẻ con nên học cách tự chăm sóc bản thân."},{"cn":"你自己去就行了。","pinyin":"Nǐ zìjǐ qù jiù xíng le.","vn":"Bạn tự đi là được rồi."}]},{"hanzi":"拿","pinyin":"ná","pos":"dgt.","vn":"cầm, nắm","examples":[{"cn":"请帮我拿一下这个包。","pinyin":"Qǐng bāng wǒ ná yíxià zhège bāo.","vn":"Làm ơn giúp tôi cầm cái túi này một chút."},{"cn":"他手里拿着一本书。","pinyin":"Tā shǒu li ná zhe yì běn shū.","vn":"Anh ấy tay đang cầm một quyển sách."},{"cn":"你去把雨伞拿过来。","pinyin":"Nǐ qù bǎ yǔsǎn ná guòlái.","vn":"Bạn đi cầm cái ô đến đây."}]},{"hanzi":"手","pinyin":"shǒu","pos":"dt.","vn":"tay","examples":[{"cn":"我的手很冷。","pinyin":"Wǒ de shǒu hěn lěng.","vn":"Tay tôi rất lạnh."},{"cn":"请举手回答问题。","pinyin":"Qǐng jǔshǒu huídá wèntí.","vn":"Mời giơ tay trả lời câu hỏi."},{"cn":"他的手很大。","pinyin":"Tā de shǒu hěn dà.","vn":"Tay anh ấy rất to."}]},{"hanzi":"为什么","pinyin":"wèi shénme","pos":"tr.","vn":"vì sao, tại sao","examples":[{"cn":"你为什么不去上课?","pinyin":"Nǐ wèi shénme bú qù shàngkè?","vn":"Tại sao bạn không đi học?"},{"cn":"他为什么这么高兴?","pinyin":"Tā wèi shénme zhème gāoxìng?","vn":"Tại sao anh ấy vui như vậy?"},{"cn":"我不知道为什么。","pinyin":"Wǒ bù zhīdào wèi shénme.","vn":"Tôi không biết tại sao."}]},{"hanzi":"不错","pinyin":"búcuò","pos":"tt.","vn":"không tồi, hay","examples":[{"cn":"这家饭馆的菜不错。","pinyin":"Zhè jiā fànguǎn de cài búcuò.","vn":"Món ăn của quán này khá ngon."},{"cn":"你的汉语说得不错。","pinyin":"Nǐ de Hànyǔ shuō de búcuò.","vn":"Bạn nói tiếng Trung khá tốt."},{"cn":"今天天气不错。","pinyin":"Jīntiān tiānqì búcuò.","vn":"Hôm nay thời tiết khá đẹp."}]},{"hanzi":"送","pinyin":"sòng","pos":"dgt.","vn":"đưa, tiễn, tặng","examples":[{"cn":"我送你回家吧。","pinyin":"Wǒ sòng nǐ huí jiā ba.","vn":"Tôi đưa bạn về nhà nhé."},{"cn":"朋友送了我一件生日礼物。","pinyin":"Péngyou sòng le wǒ yí jiàn shēngrì lǐwù.","vn":"Bạn tặng tôi một món quà sinh nhật."},{"cn":"我去车站送他。","pinyin":"Wǒ qù chēzhàn sòng tā.","vn":"Tôi đi ra bến xe tiễn anh ấy."}]},{"hanzi":"回去","pinyin":"huíqù","pos":"dgt.","vn":"quay về, về","examples":[{"cn":"天晚了,我们回去吧。","pinyin":"Tiān wǎn le, wǒmen huíqù ba.","vn":"Trời muộn rồi, chúng ta về thôi."},{"cn":"他已经回去了。","pinyin":"Tā yǐjīng huíqù le.","vn":"Anh ấy đã về rồi."},{"cn":"我想回去休息一下。","pinyin":"Wǒ xiǎng huíqù xiūxi yíxià.","vn":"Tôi muốn về nghỉ ngơi một chút."}]},{"hanzi":"每","pinyin":"měi","pos":"đt.","vn":"mỗi, hàng (ngày, năm...)","examples":[{"cn":"我每天六点起床。","pinyin":"Wǒ měitiān liù diǎn qǐchuáng.","vn":"Tôi mỗi ngày sáu giờ dậy."},{"cn":"每个人都有自己的想法。","pinyin":"Měi ge rén dōu yǒu zìjǐ de xiǎngfǎ.","vn":"Mỗi người đều có suy nghĩ riêng của mình."},{"cn":"他每年都去旅游。","pinyin":"Tā měi nián dōu qù lǚyóu.","vn":"Mỗi năm anh ấy đều đi du lịch."}]},{"hanzi":"累","pinyin":"lèi","pos":"tt.","vn":"mệt","examples":[{"cn":"我今天很累。","pinyin":"Wǒ jīntiān hěn lèi.","vn":"Hôm nay tôi rất mệt."},{"cn":"工作了一天,我累死了。","pinyin":"Gōngzuò le yì tiān, wǒ lèi sǐ le.","vn":"Làm việc cả ngày, tôi mệt chết đi được."},{"cn":"你累不累?","pinyin":"Nǐ lèi bu lèi?","vn":"Bạn có mệt không?"}]}],"grammar":[{"title":"结果补语","explanation_vn":"Có một số động từ hoặc tính từ có thể đặt sau động từ để biểu thị kết quả của hành động. Hình thức phủ định là thêm \"没（有）\" vào trước động từ và bỏ \"了\" ở cuối câu. Hình thức nghi vấn có 3 loại: (1) thêm \"了吗\" vào cuối câu; (2) thêm \"（了）没有\" vào cuối câu; (3) động từ + 没 + động từ + bổ ngữ kết quả.","examples":[{"cn":"菜都做好了。","pinyin":"Cài dōu zuòhǎo le.","vn":""},{"cn":"我吃完饭了。","pinyin":"Wǒ chī wán fàn le.","vn":""},{"cn":"小雪今天来晚了。","pinyin":"Xiǎoxuě jīntiān lái wǎn le.","vn":""},{"cn":"我没吃完饭。","pinyin":"Wǒ méi chī wán fàn.","vn":""},{"cn":"小雪没来晚。","pinyin":"Xiǎoxuě méi lái wǎn.","vn":""},{"cn":"你吃完饭了吗？","pinyin":"Nǐ chī wán fàn le ma?","vn":""},{"cn":"小雪来晚了没有？","pinyin":"Xiǎoxuě lái wǎn le méiyǒu?","vn":""},{"cn":"你学没学会？","pinyin":"Nǐ xué méi xuéhuì?","vn":""}]},{"title":"动词重叠（1）","explanation_vn":"Động từ có tính hành động mạnh, có thể lặp đi lặp lại hoặc duy trì thì đều có thể lặp lại. Động từ lặp lại thường dùng trong văn nói, mang ngữ khí nhẹ nhàng, tự nhiên, biểu thị thời gian ngắn, số lượng ít hoặc mang sắc thái thử nghiệm. Hình thức lặp lại của động từ đơn âm tiết là \"A（一）A\"; hình thức lặp lại của động từ song âm tiết là \"ABAB\"; hình thức lặp lại của từ ly hợp là \"AAB\".","examples":[{"cn":"那你再想一想，你想好了，我来买票。","pinyin":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎipiào.","vn":""},{"cn":"我有点儿累，现在想休息休息。","pinyin":"Wǒ yǒudiǎnr lèi, xiànzài xiǎng xiūxi xiūxi.","vn":""},{"cn":"你能过来帮帮忙吗？","pinyin":"Nǐ néng guòlái bāngbāngmáng ma?","vn":""}]},{"title":"动词重叠（2）","explanation_vn":"Khi diễn đạt tình huống đã xảy ra, hình thức lặp lại của động từ đơn âm tiết là \"A了A\"; động từ song âm tiết nói chung không dùng hình thức lặp lại, mà chỉ dùng cấu trúc \"AB了一下\"; hình thức lặp lại của từ ly hợp là \"A了AB\".","examples":[{"cn":"我看了看网上的介绍。","pinyin":"Wǒ kànle kàn wǎngshàng de jièshào.","vn":""},{"cn":"我休息了一下，现在觉得不累了。","pinyin":"Wǒ xiūxile yíxià, xiànzài juéde bú lèi le.","vn":""},{"cn":"他昨天来帮了帮忙。","pinyin":"Tā zuótiān lái bāngle bāngmáng.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"今天回来这么晚啊！","pinyin":"Jīntiān huílái zhème wǎn a!"},{"speaker":"刘明","cn":"工作太多了，下班的时候没做完。","pinyin":"Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán."},{"speaker":"王一雪","cn":"菜都做好了，过来吃饭吧。","pinyin":"Cài dōu zuòhǎo le, guòlái chī fàn ba."},{"speaker":"刘明","cn":"我想休息一下，喝杯水。","pinyin":"Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ."},{"speaker":"王一雪","cn":"好的。","pinyin":"Hǎo de."}],"translation_vn":"Vương Nhất Tuyết: Hôm nay anh về muộn thế!\nLưu Minh: Anh có nhiều việc quá, đến giờ tan làm mà vẫn chưa xong.\nVương Nhất Tuyết: Cơm nấu xong rồi. Anh ra ăn cơm nhé.\nLưu Minh: Anh muốn nghỉ ngơi một lát, uống cốc nước đã.\nVương Nhất Tuyết: Vâng ạ.","audio_dialogue":"3-1.mp3","audio_vocab":"3-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘明","cn":"我们找个时间去旅游，怎么样？","pinyin":"Wǒmen zhǎo ge shíjiān qù lǚyóu, zěnmeyàng?"},{"speaker":"王一雪","cn":"好啊，我也很想一起出去玩。","pinyin":"Hǎo a, wǒ yě hěn xiǎng yìqǐ chūqù wán."},{"speaker":"刘明","cn":"你想去哪儿？","pinyin":"Nǐ xiǎng qù nǎr?"},{"speaker":"王一雪","cn":"我还没想好呢。","pinyin":"Wǒ hái méi xiǎnghǎo ne."},{"speaker":"刘明","cn":"那你再想一想，你想好了，我来买票。","pinyin":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎipiào."}],"translation_vn":"Lưu Minh: Chúng ta sắp xếp thời gian đi du lịch, em thấy thế nào?\nVương Nhất Tuyết: Nhất trí! Em cũng rất muốn đi chơi cùng anh.\nLưu Minh: Em muốn đi đâu?\nVương Nhất Tuyết: Em vẫn chưa nghĩ ra.\nLưu Minh: Vậy em cứ nghĩ thêm nhé. Khi nào em nghĩ xong, anh sẽ mua vé.","audio_dialogue":"3-3.mp3","audio_vocab":"3-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明","cn":"吃个苹果吧，我都洗好了。","pinyin":"Chī ge píngguǒ ba, wǒ dōu xǐhǎo le."},{"speaker":"王一雪","cn":"好的。","pinyin":"Hǎo de."},{"speaker":"刘明","cn":"就在桌子上，你自己拿。","pinyin":"Jiù zài zhuōzi shang, nǐ zìjǐ ná."},{"speaker":"王一雪","cn":"我去洗洗手。对了，我们去西安旅游，怎么样？","pinyin":"Wǒ qù xǐxi shǒu. Duìle, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?"},{"speaker":"刘明","cn":"为什么想去西安？","pinyin":"Wèi shénme xiǎng qù Xī'ān?"},{"speaker":"王一雪","cn":"我看了看网上的介绍，这个时候去西安很不错！","pinyin":"Wǒ kànle kàn wǎngshàng de jièshào, zhège shíhou qù Xī'ān hěn búcuò!"}],"translation_vn":"Lưu Minh: Ăn quả táo đi, anh đã rửa sạch rồi.\nVương Nhất Tuyết: Vâng ạ.\nLưu Minh: Táo để trên bàn, em tự đi lấy nhé.\nVương Nhất Tuyết: Em đi rửa tay đã. À đúng rồi, mình đi Tây An du lịch, anh thấy thế nào?\nLưu Minh: Vì sao em muốn đi Tây An?\nVương Nhất Tuyết: Em có xem qua giới thiệu trên mạng. Thời điểm này đi Tây An rất tuyệt!","audio_dialogue":"3-5.mp3","audio_vocab":"3-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"早上，刘明开车送孩子去学校，送完孩子回家后，医院就来电话了，让他回去上班。我觉得他这个月每天都很累，真想让他休息休息。","pinyin":"Zǎoshang, Liú Míng kāichē sòng háizi qù xuéxiào, sòngwán háizi huí jiā hòu, yīyuàn jiù lái diànhuà le, ràng tā huíqù shàngbān. Wǒ juéde tā zhège yuè měitiān dōu hěn lèi, zhēn xiǎng ràng tā xiūxi xiūxi."}],"translation_vn":"Buổi sáng, Lưu Minh lái xe đưa con đi đến trường, sau khi đưa con xong quay về nhà thì bệnh viện gọi điện đến, yêu cầu anh ấy quay về bệnh viện làm việc. Tôi cảm thấy tháng này ngày nào Lưu Minh cũng đều rất bận, thật muốn anh ấy được nghỉ ngơi một chút.","audio_dialogue":"3-7.mp3","audio_vocab":"3-8.mp3"}]},{"id":4,"title_cn":"你穿红色的很好看","title_pinyin":"Nǐ chuān hóngsè de hěn hǎokàn","title_vn":"Con mặc đồ màu đỏ rất đẹp","goals":["Có thể nghe hiểu và hỏi về những trải nghiệm trong quá khứ.","Có thể nghe hiểu và sử dụng được cách thức miêu tả đối tượng được đề cập đến.","Nắm vững cách dùng của câu ghép nhân quả \"因为……，所以……\", để diễn đạt nguyên nhân và kết quả của sự việc."],"vocab":[{"hanzi":"过","pinyin":"guo","pos":"trợ.","vn":"đã từng","examples":[{"cn":"我去过中国。","pinyin":"Wǒ qùguo Zhōngguó.","vn":"Tôi đã từng đến Trung Quốc."},{"cn":"你吃过中国菜吗？","pinyin":"Nǐ chīguo Zhōngguó cài ma?","vn":"Bạn đã từng ăn món Trung Quốc chưa?"},{"cn":"她看过这部电影。","pinyin":"Tā kànguo zhè bù diànyǐng.","vn":"Cô ấy đã từng xem bộ phim này."}]},{"hanzi":"商场","pinyin":"shāngchǎng","pos":"dt.","vn":"trung tâm thương mại, khu mua sắm","examples":[{"cn":"我们周末去商场买东西吧。","pinyin":"Wǒmen zhōumò qù shāngchǎng mǎi dōngxi ba.","vn":"Cuối tuần chúng ta đi trung tâm thương mại mua đồ nhé."},{"cn":"这个商场很大，东西也很多。","pinyin":"Zhège shāngchǎng hěn dà, dōngxi yě hěn duō.","vn":"Trung tâm thương mại này rất lớn, đồ cũng rất nhiều."},{"cn":"商场里有很多卖衣服的地方。","pinyin":"Shāngchǎng lǐ yǒu hěn duō mài yīfu de dìfang.","vn":"Trong trung tâm thương mại có nhiều chỗ bán quần áo."}]},{"hanzi":"进去","pinyin":"jìnqù","pos":"đgt.","vn":"đi vào","examples":[{"cn":"门开着，我们进去吧。","pinyin":"Mén kāizhe, wǒmen jìnqù ba.","vn":"Cửa đang mở, chúng ta vào đi."},{"cn":"他走进去看了看。","pinyin":"Tā zǒu jìnqù kànle kàn.","vn":"Anh ấy đi vào xem thử."},{"cn":"里面太挤了，我不想进去。","pinyin":"Lǐmiàn tài jǐ le, wǒ bù xiǎng jìnqù.","vn":"Bên trong chật quá, tôi không muốn vào."}]},{"hanzi":"条","pinyin":"tiáo","pos":"lượng.","vn":"cái, chiếc (quần, váy...)","examples":[{"cn":"我想买一条裤子。","pinyin":"Wǒ xiǎng mǎi yì tiáo kùzi.","vn":"Tôi muốn mua một cái quần."},{"cn":"这条裙子真漂亮。","pinyin":"Zhè tiáo qúnzi zhēn piàoliang.","vn":"Cái váy này thật đẹp."},{"cn":"她有很多条裤子。","pinyin":"Tā yǒu hěn duō tiáo kùzi.","vn":"Cô ấy có rất nhiều cái quần."}]},{"hanzi":"裤子","pinyin":"kùzi","pos":"dt.","vn":"quần","examples":[{"cn":"这条裤子有点儿小。","pinyin":"Zhè tiáo kùzi yǒudiǎnr xiǎo.","vn":"Cái quần này hơi nhỏ."},{"cn":"我想试试这条裤子。","pinyin":"Wǒ xiǎng shìshi zhè tiáo kùzi.","vn":"Tôi muốn thử cái quần này."},{"cn":"他穿了一条黑色的裤子。","pinyin":"Tā chuānle yì tiáo hēisè de kùzi.","vn":"Anh ấy mặc một cái quần màu đen."}]},{"hanzi":"白色","pinyin":"báisè","pos":"dt.","vn":"màu trắng","examples":[{"cn":"我喜欢白色的衣服。","pinyin":"Wǒ xǐhuan báisè de yīfu.","vn":"Tôi thích quần áo màu trắng."},{"cn":"这件衣服是白色的。","pinyin":"Zhè jiàn yīfu shì báisè de.","vn":"Cái áo này màu trắng."},{"cn":"白色很好看，也很好搭配。","pinyin":"Báisè hěn hǎokàn, yě hěn hǎo dāpèi.","vn":"Màu trắng rất đẹp và cũng dễ phối đồ."}]},{"hanzi":"因为","pinyin":"yīnwèi","pos":"liên.","vn":"bởi vì, vì","examples":[{"cn":"因为下雨，我们没去公园。","pinyin":"Yīnwèi xiàyǔ, wǒmen méi qù gōngyuán.","vn":"Vì trời mưa nên chúng tôi không đi công viên."},{"cn":"我没来，因为我生病了。","pinyin":"Wǒ méi lái, yīnwèi wǒ shēngbìng le.","vn":"Tôi không đến, vì tôi bị ốm."},{"cn":"因为太贵了，我没买。","pinyin":"Yīnwèi tài guì le, wǒ méi mǎi.","vn":"Vì quá đắt nên tôi đã không mua."}]},{"hanzi":"试","pinyin":"shì","pos":"đgt.","vn":"thử","examples":[{"cn":"我可以试试这条裤子吗？","pinyin":"Wǒ kěyǐ shìshi zhè tiáo kùzi ma?","vn":"Tôi có thể thử cái quần này không?"},{"cn":"你试一下这个菜，很好吃。","pinyin":"Nǐ shì yíxià zhège cài, hěn hǎochī.","vn":"Bạn thử món này xem, rất ngon."},{"cn":"我试了很多次都没成功。","pinyin":"Wǒ shìle hěn duō cì dōu méi chénggōng.","vn":"Tôi đã thử nhiều lần nhưng đều không thành công."}]},{"hanzi":"红色","pinyin":"hóngsè","pos":"dt.","vn":"màu đỏ","examples":[{"cn":"我想买一件红色的衣服。","pinyin":"Wǒ xiǎng mǎi yí jiàn hóngsè de yīfu.","vn":"Tôi muốn mua một cái áo màu đỏ."},{"cn":"她的书包是红色的。","pinyin":"Tā de shūbāo shì hóngsè de.","vn":"Cặp sách của cô ấy màu đỏ."},{"cn":"过年的时候大家喜欢穿红色。","pinyin":"Guònián de shíhou dàjiā xǐhuan chuān hóngsè.","vn":"Vào dịp Tết mọi người thích mặc màu đỏ."}]},{"hanzi":"所以","pinyin":"suǒyǐ","pos":"liên.","vn":"cho nên, nên","examples":[{"cn":"外面下雨了，所以我没出去。","pinyin":"Wàimiàn xiàyǔ le, suǒyǐ wǒ méi chūqù.","vn":"Bên ngoài trời mưa nên tôi đã không ra ngoài."},{"cn":"他很忙，所以不能来。","pinyin":"Tā hěn máng, suǒyǐ bù néng lái.","vn":"Anh ấy rất bận nên không thể đến."},{"cn":"这件衣服太小了，所以我没买。","pinyin":"Zhè jiàn yīfu tài xiǎo le, suǒyǐ wǒ méi mǎi.","vn":"Cái áo này quá nhỏ nên tôi đã không mua."}]},{"hanzi":"书包","pinyin":"shūbāo","pos":"dt.","vn":"cặp sách","examples":[{"cn":"我的书包里有很多书。","pinyin":"Wǒ de shūbāo lǐ yǒu hěn duō shū.","vn":"Trong cặp sách của tôi có nhiều sách."},{"cn":"这个书包是新买的。","pinyin":"Zhège shūbāo shì xīn mǎi de.","vn":"Cái cặp sách này mới mua."},{"cn":"他每天背着书包去上学。","pinyin":"Tā měitiān bēizhe shūbāo qù shàngxué.","vn":"Mỗi ngày cậu ấy đeo cặp sách đi học."}]},{"hanzi":"过去","pinyin":"guòqù","pos":"đgt.","vn":"sang, đi sang","examples":[{"cn":"你过去帮他一下吧。","pinyin":"Nǐ guòqù bāng tā yíxià ba.","vn":"Bạn sang giúp cậu ấy một chút đi."},{"cn":"我现在过去找你。","pinyin":"Wǒ xiànzài guòqù zhǎo nǐ.","vn":"Bây giờ tôi sang tìm bạn."},{"cn":"他走过去跟老师说话。","pinyin":"Tā zǒu guòqù gēn lǎoshī shuōhuà.","vn":"Anh ấy đi sang nói chuyện với giáo viên."}]},{"hanzi":"绿色","pinyin":"lǜsè","pos":"dt.","vn":"màu xanh lá cây","examples":[{"cn":"我喜欢绿色，因为它让人很舒服。","pinyin":"Wǒ xǐhuan lǜsè, yīnwèi tā ràng rén hěn shūfu.","vn":"Tôi thích màu xanh lá vì nó khiến người ta thấy dễ chịu."},{"cn":"这条裙子是绿色的。","pinyin":"Zhè tiáo qúnzi shì lǜsè de.","vn":"Cái váy này màu xanh lá."},{"cn":"公园里的树都是绿色的。","pinyin":"Gōngyuán lǐ de shù dōu shì lǜsè de.","vn":"Cây cối trong công viên đều màu xanh lá."}]},{"hanzi":"黑色","pinyin":"hēisè","pos":"dt.","vn":"màu đen","examples":[{"cn":"他喜欢穿黑色的衣服。","pinyin":"Tā xǐhuan chuān hēisè de yīfu.","vn":"Anh ấy thích mặc quần áo màu đen."},{"cn":"这辆车是黑色的。","pinyin":"Zhè liàng chē shì hēisè de.","vn":"Chiếc xe này màu đen."},{"cn":"我想买一条黑色的裤子。","pinyin":"Wǒ xiǎng mǎi yì tiáo hēisè de kùzi.","vn":"Tôi muốn mua một cái quần màu đen."}]},{"hanzi":"更","pinyin":"gèng","pos":"phó.","vn":"càng, hơn","examples":[{"cn":"今天比昨天更冷。","pinyin":"Jīntiān bǐ zuótiān gèng lěng.","vn":"Hôm nay lạnh hơn hôm qua."},{"cn":"这个比那个更好。","pinyin":"Zhège bǐ nàge gèng hǎo.","vn":"Cái này tốt hơn cái kia."},{"cn":"她比以前更漂亮了。","pinyin":"Tā bǐ yǐqián gèng piàoliang le.","vn":"Cô ấy xinh hơn trước đây."}]},{"hanzi":"颜色","pinyin":"yánsè","pos":"dt.","vn":"màu sắc","examples":[{"cn":"你喜欢什么颜色？","pinyin":"Nǐ xǐhuan shénme yánsè?","vn":"Bạn thích màu gì?"},{"cn":"这件衣服的颜色很好看。","pinyin":"Zhè jiàn yīfu de yánsè hěn hǎokàn.","vn":"Màu của chiếc áo này rất đẹp."},{"cn":"这里有很多种颜色可以选。","pinyin":"Zhèlǐ yǒu hěn duō zhǒng yánsè kěyǐ xuǎn.","vn":"Ở đây có nhiều màu để lựa chọn."}]}],"grammar":[{"title":"动态助词\"过\" - Trợ từ động thái \"过\"","explanation_vn":"Trợ từ động thái \"过\" đặt sau động từ, biểu thị động tác đã từng xảy ra trong quá khứ, không kéo dài đến hiện tại. Cấu trúc cơ bản: Chủ ngữ + động từ + 过 + tân ngữ. Hình thức phủ định là thêm \"没（有）\" trước động từ. Hình thức nghi vấn có 3 dạng: (1) cuối câu thêm \"吗\"; (2) cuối câu thêm \"没有\"; (3) động từ + 没 + động từ + 过.","examples":[{"cn":"她去过中国。","pinyin":"Tā qùguo Zhōngguó.","vn":""},{"cn":"我吃过饺子，很好吃。","pinyin":"Wǒ chīguo jiǎozi, hěn hǎochī.","vn":""},{"cn":"她没去过中国。","pinyin":"Tā méi qùguo Zhōngguó.","vn":""},{"cn":"我们来过这家商场吗？","pinyin":"Wǒmen láiguo zhè jiā shāngchǎng ma?","vn":""},{"cn":"陈天中吃过饺子没有？","pinyin":"Chén Tiānzhōng chīguo jiǎozi méiyǒu?","vn":""},{"cn":"你看没看过那个电影？","pinyin":"Nǐ kàn méi kànguo nàge diànyǐng?","vn":""}]},{"title":"因果复句\"因为……，所以……\" - Câu ghép nhân quả \"因为……，所以……\"","explanation_vn":"Câu ghép nguyên nhân kết quả được tạo thành bởi cấu trúc \"因为……所以……\". \"因为\" và \"所以\" có thể sử dụng thành đôi, cũng có thể chỉ dùng một trong hai từ này.","examples":[{"cn":"就是因为没穿过，所以要试试啊！","pinyin":"Jiùshì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","vn":""},{"cn":"因为我生病了，今天没去上班。","pinyin":"Yīnwèi wǒ shēngbìng le, jīntiān méi qù shàngbān.","vn":""},{"cn":"我没去过他家，所以让他来车站接我。","pinyin":"Wǒ méi qùguo tā jiā, suǒyǐ ràng tā lái chēzhàn jiē wǒ.","vn":""}]},{"title":"\"的\"字短语 - Cụm từ chứa \"的\"","explanation_vn":"Trợ từ kết cấu \"的\" đặt sau danh từ, đại từ, động từ, tính từ... tạo thành cụm từ chứa \"的\", cụm từ này sẽ tương đương với một cụm danh từ.","examples":[{"cn":"红色的、绿色的、黑色的，你想买哪个？（=红色的书包、绿色的书包、黑色的书包）","pinyin":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge? (= Hóngsè de shūbāo, lǜsè de shūbāo, hēisè de shūbāo)","vn":""},{"cn":"这个面包是爸爸买的，妈妈买的在那儿。（=买的面包）","pinyin":"Zhège miànbāo shì bàba mǎi de, māma mǎi de zài nàr. (= mǎi de miànbāo)","vn":""},{"cn":"这件衣服太贵了，还是那件便宜的吧。（=便宜的衣服）","pinyin":"Zhè jiàn yīfu tài guì le, háishi nà jiàn piányi de ba. (= piányi de yīfu)","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"妈妈，我们来过这家商场吗？","pinyin":"Māma, wǒmen láiguo zhè jiā shāngchǎng ma?"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"没来过，这是新开的。","pinyin":"Méi láiguo, zhè shì xīn kāi de."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"我们进去看看吧。","pinyin":"Wǒmen jìnqù kànkan ba."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"好啊！你想买点儿什么？","pinyin":"Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?"},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"我想买条裤子。","pinyin":"Wǒ xiǎng mǎi tiáo kùzi."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"没问题。","pinyin":"Méi wèntí."}],"translation_vn":"Lưu Tiểu Tuyết: Mẹ ơi, chúng ta đã từng đến trung tâm mua sắm này chưa?\nVương Nhất Tuyết: Chưa con ạ, đây là trung tâm mua sắm mới mở.\nLưu Tiểu Tuyết: Chúng ta đi vào xem một chút nhé.\nVương Nhất Tuyết: Được thôi. Con muốn mua chút gì không?\nLưu Tiểu Tuyết: Con muốn mua chiếc quần.\nVương Nhất Tuyết: Được nhé.","audio_dialogue":"4-1 @xitoytili_luoluodafang.mp3","audio_vocab":"4-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"妈妈，我想买这条白色的裤子。","pinyin":"Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"你有很多白色的衣服，为什么还买白色的？","pinyin":"Nǐ yǒu hěn duō báisè de yīfu, wèishénme hái mǎi báisè de?"},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"因为我喜欢白色啊！","pinyin":"Yīnwèi wǒ xǐhuan báisè a!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"我觉得这条白色的不太好看，你试试那条红色的吧。","pinyin":"Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"我没穿过红色的，红色的好看吗？","pinyin":"Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"就是因为没穿过，所以要试试啊！","pinyin":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!"}],"translation_vn":"Lưu Tiểu Tuyết: Mẹ ơi, con muốn mua chiếc quần màu trắng này.\nVương Nhất Tuyết: Con đã có rất nhiều quần áo màu trắng rồi, sao vẫn còn mua màu trắng nữa?\nLưu Tiểu Tuyết: Vì con thích màu trắng ạ.\nVương Nhất Tuyết: Mẹ thấy chiếc quần màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem sao.\nLưu Tiểu Tuyết: Con chưa từng mặc quần màu đỏ, quần màu đỏ có đẹp không mẹ?\nVương Nhất Tuyết: Chính là vì chưa từng mặc nên cần phải thử xem.","audio_dialogue":"4-3.mp3","audio_vocab":"4-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"妈妈，我想买个新书包。","pinyin":"Māma, wǒ xiǎng mǎi gè xīn shūbāo."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"好，那边卖书包，我们过去看看吧。","pinyin":"Hǎo, nàbian mài shūbāo, wǒmen guòqù kànkan ba."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"这么多漂亮的书包！","pinyin":"Zhème duō piàoliang de shūbāo!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"红色的、绿色的、黑色的，你想要哪个？","pinyin":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng yào nǎge?"},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"绿色的吧。","pinyin":"Lǜsè de ba."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"不错，我也觉得绿色的更好看。","pinyin":"Búcuò, wǒ yě juéde lǜsè de gèng hǎokàn."}],"translation_vn":"Lưu Tiểu Tuyết: Mẹ ơi, con muốn mua cặp sách mới ạ.\nVương Nhất Tuyết: Được, đằng kia có bán cặp sách, chúng ta sang đó xem thử nhé.\nLưu Tiểu Tuyết: Bao nhiêu là cặp sách đẹp!\nVương Nhất Tuyết: Cái màu đỏ, cái màu xanh lá cây, cái màu đen, con muốn cái nào?\nLưu Tiểu Tuyết: Cái màu xanh lá cây ạ.\nVương Nhất Tuyết: Đẹp đấy, mẹ cũng thấy cặp sách màu xanh lá cây đẹp hơn.","audio_dialogue":"4-5 @xitoytili_luoluodafang.mp3","audio_vocab":"4-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我和妈妈去了一家商场。因为是新开的，所以这几天东西很便宜。商场里的衣服颜色很多。我没穿过红色的裤子，妈妈让我试了试，我觉得我穿红色的也很好看。","pinyin":"Wǒ hé māma qùle yì jiā shāngchǎng. Yīnwèi shì xīn kāi de, suǒyǐ zhè jǐ tiān dōngxi hěn piányi. Shāngchǎng lǐ de yīfu yánsè hěn duō. Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn."}],"translation_vn":"Mình đã đi đến một trung tâm thương mại với mẹ. Vì trung tâm thương mại vừa mới khai trương, nên mấy hôm nay đồ rất rẻ. Quần áo trong trung tâm thương mại có rất nhiều màu sắc. Mình chưa từng mặc quần màu đỏ, mẹ đã bảo mình thử xem, mình nghĩ mình mặc quần màu đỏ cũng rất đẹp.","audio_dialogue":"4-7 @xitoytili_luoluodafang.mp3","audio_vocab":"4-8 @xitoytili_luoluodafang.mp3"}]},{"id":5,"title_cn":"第一次去中国朋友家","title_pinyin":"Dì-yī cì qù Zhōngguó péngyou jiā","title_vn":"Lần đầu đến thăm nhà bạn người Trung Quốc","goals":["Có thể nghe hiểu và sử dụng được bổ ngữ xu hướng để diễn đạt phương hướng của động tác.","Nắm được cấu trúc cố định \"都……了\" để diễn đạt được ý đã làm gì hoặc đạt được điều gì.","Hiểu về cách chào hỏi của người Trung Quốc khi gặp mặt."],"vocab":[{"hanzi":"快","pinyin":"kuài","pos":"phó./tt.","vn":"mau, nhanh","examples":[{"cn":"你快点儿，我们要迟到了。","pinyin":"Nǐ kuài diǎnr, wǒmen yào chídào le.","vn":"Bạn nhanh lên, chúng ta sắp trễ rồi."},{"cn":"他跑得很快。","pinyin":"Tā pǎo de hěn kuài.","vn":"Anh ấy chạy rất nhanh."},{"cn":"快走吧，火车要开了。","pinyin":"Kuài zǒu ba, huǒchē yào kāi le.","vn":"Đi nhanh thôi, tàu sắp chạy rồi."}]},{"hanzi":"下来","pinyin":"xiàlái","pos":"đgt.","vn":"xuống, xuống dưới, xuống đây","examples":[{"cn":"你快下来吧，饭做好了。","pinyin":"Nǐ kuài xiàlái ba, fàn zuòhǎo le.","vn":"Bạn xuống nhanh đi, cơm nấu xong rồi."},{"cn":"他从楼上走下来了。","pinyin":"Tā cóng lóushàng zǒu xiàlái le.","vn":"Anh ấy từ trên lầu đi xuống rồi."},{"cn":"猫从树上跳了下来。","pinyin":"Māo cóng shùshàng tiàole xiàlái.","vn":"Con mèo từ trên cây nhảy xuống."}]},{"hanzi":"上来","pinyin":"shànglái","pos":"đgt.","vn":"lên, lên trên, lên đây","examples":[{"cn":"你上来吧，这里风景很好。","pinyin":"Nǐ shànglái ba, zhèlǐ fēngjǐng hěn hǎo.","vn":"Bạn lên đây đi, ở đây phong cảnh rất đẹp."},{"cn":"他慢慢地爬上来了。","pinyin":"Tā mànmàn de pá shànglái le.","vn":"Anh ấy từ từ bò lên."},{"cn":"请大家上来坐吧。","pinyin":"Qǐng dàjiā shànglái zuò ba.","vn":"Mời mọi người lên ngồi."}]},{"hanzi":"上去","pinyin":"shàngqù","pos":"đgt.","vn":"lên, lên trên, lên đi","examples":[{"cn":"你们先上去，我马上就来。","pinyin":"Nǐmen xiān shàngqù, wǒ mǎshàng jiù lái.","vn":"Các bạn lên trước đi, tôi sẽ đến ngay."},{"cn":"他走上去跟她说话了。","pinyin":"Tā zǒu shàngqù gēn tā shuōhuà le.","vn":"Anh ấy đi lên nói chuyện với cô ấy."},{"cn":"山不高，我们走上去吧。","pinyin":"Shān bù gāo, wǒmen zǒu shàngqù ba.","vn":"Núi không cao, chúng ta đi lên nhé."}]},{"hanzi":"下面","pinyin":"xiàmiàn","pos":"dt.","vn":"dưới, phía dưới","examples":[{"cn":"书在桌子下面。","pinyin":"Shū zài zhuōzi xiàmiàn.","vn":"Sách ở dưới bàn."},{"cn":"猫躲在床下面。","pinyin":"Māo duǒ zài chuáng xiàmiàn.","vn":"Con mèo trốn dưới giường."},{"cn":"我们下面该做什么？","pinyin":"Wǒmen xiàmiàn gāi zuò shénme?","vn":"Tiếp theo chúng ta nên làm gì?"}]},{"hanzi":"面","pinyin":"miàn","pos":"htố.","vn":"phía","examples":[{"cn":"桌子上面有一本书。","pinyin":"Zhuōzi shàngmiàn yǒu yì běn shū.","vn":"Trên bàn có một quyển sách."},{"cn":"房子里面很干净。","pinyin":"Fángzi lǐmiàn hěn gānjìng.","vn":"Bên trong nhà rất sạch sẽ."},{"cn":"公园外面有很多车。","pinyin":"Gōngyuán wàimiàn yǒu hěn duō chē.","vn":"Bên ngoài công viên có nhiều xe."}]},{"hanzi":"等","pinyin":"děng","pos":"đgt.","vn":"đợi","examples":[{"cn":"你在这儿等我一下。","pinyin":"Nǐ zài zhèr děng wǒ yíxià.","vn":"Bạn đợi tôi ở đây một chút."},{"cn":"我等了半个小时了。","pinyin":"Wǒ děngle bàn gè xiǎoshí le.","vn":"Tôi đã đợi nửa tiếng rồi."},{"cn":"别着急，再等一会儿。","pinyin":"Bié zháojí, zài děng yíhuìr.","vn":"Đừng vội, đợi thêm một lát nữa."}]},{"hanzi":"一会儿","pinyin":"yíhuìr","pos":"sl.","vn":"một lát","examples":[{"cn":"你等一会儿，我马上回来。","pinyin":"Nǐ děng yíhuìr, wǒ mǎshàng huílái.","vn":"Bạn đợi một lát, tôi sẽ quay lại ngay."},{"cn":"我们休息一会儿吧。","pinyin":"Wǒmen xiūxi yíhuìr ba.","vn":"Chúng ta nghỉ một lát nhé."},{"cn":"他一会儿就到了。","pinyin":"Tā yíhuìr jiù dào le.","vn":"Một lát nữa anh ấy sẽ đến."}]},{"hanzi":"下去","pinyin":"xiàqù","pos":"đgt.","vn":"xuống, đi xuống, xuống kia","examples":[{"cn":"你慢慢走下去，小心点儿。","pinyin":"Nǐ mànmàn zǒu xiàqù, xiǎoxīn diǎnr.","vn":"Bạn từ từ đi xuống, cẩn thận nhé."},{"cn":"他从楼梯走下去了。","pinyin":"Tā cóng lóutī zǒu xiàqù le.","vn":"Anh ấy đi xuống từ cầu thang."},{"cn":"太晚了，我们该下去了。","pinyin":"Tài wǎn le, wǒmen gāi xiàqù le.","vn":"Muộn rồi, chúng ta nên xuống thôi."}]},{"hanzi":"进来","pinyin":"jìnlái","pos":"đgt.","vn":"vào, đi vào, vào đây","examples":[{"cn":"请进来坐吧。","pinyin":"Qǐng jìnlái zuò ba.","vn":"Mời vào ngồi."},{"cn":"外面冷，快进来吧。","pinyin":"Wàimiàn lěng, kuài jìnlái ba.","vn":"Bên ngoài lạnh, vào nhanh đi."},{"cn":"他敲了敲门就走进来了。","pinyin":"Tā qiāole qiāo mén jiù zǒu jìnlái le.","vn":"Anh ấy gõ cửa rồi đi vào."}]},{"hanzi":"爷爷","pinyin":"yéye","pos":"dt.","vn":"ông nội","examples":[{"cn":"我爷爷今年七十岁了。","pinyin":"Wǒ yéye jīnnián qīshí suì le.","vn":"Ông nội tôi năm nay bảy mươi tuổi."},{"cn":"爷爷喜欢喝茶。","pinyin":"Yéye xǐhuan hē chá.","vn":"Ông nội thích uống trà."},{"cn":"周末我要去看爷爷。","pinyin":"Zhōumò wǒ yào qù kàn yéye.","vn":"Cuối tuần tôi sẽ đi thăm ông nội."}]},{"hanzi":"奶奶","pinyin":"nǎinai","pos":"dt.","vn":"bà nội","examples":[{"cn":"我奶奶做的菜很好吃。","pinyin":"Wǒ nǎinai zuò de cài hěn hǎochī.","vn":"Món ăn bà nội tôi nấu rất ngon."},{"cn":"奶奶每天早上去散步。","pinyin":"Nǎinai měitiān zǎoshang qù sànbù.","vn":"Mỗi sáng bà nội đi dạo bộ."},{"cn":"我很想念奶奶。","pinyin":"Wǒ hěn xiǎngniàn nǎinai.","vn":"Tôi rất nhớ bà nội."}]},{"hanzi":"礼物","pinyin":"lǐwù","pos":"dt.","vn":"quà, quà tặng","examples":[{"cn":"这是我给你的生日礼物。","pinyin":"Zhè shì wǒ gěi nǐ de shēngrì lǐwù.","vn":"Đây là quà sinh nhật tôi tặng bạn."},{"cn":"谢谢你的礼物，我很喜欢。","pinyin":"Xièxie nǐ de lǐwù, wǒ hěn xǐhuan.","vn":"Cảm ơn món quà của bạn, tôi rất thích."},{"cn":"我不知道该送她什么礼物。","pinyin":"Wǒ bù zhīdào gāi sòng tā shénme lǐwù.","vn":"Tôi không biết nên tặng cô ấy quà gì."}]},{"hanzi":"准备","pinyin":"zhǔnbèi","pos":"đgt.","vn":"chuẩn bị","examples":[{"cn":"我在准备明天的考试。","pinyin":"Wǒ zài zhǔnbèi míngtiān de kǎoshì.","vn":"Tôi đang chuẩn bị cho kỳ thi ngày mai."},{"cn":"妈妈正在准备晚饭。","pinyin":"Māma zhèngzài zhǔnbèi wǎnfàn.","vn":"Mẹ đang chuẩn bị bữa tối."},{"cn":"你准备好了吗？","pinyin":"Nǐ zhǔnbèi hǎo le ma?","vn":"Bạn chuẩn bị xong chưa?"}]},{"hanzi":"奶茶","pinyin":"nǎichá","pos":"dt.","vn":"trà sữa","examples":[{"cn":"我想喝一杯奶茶。","pinyin":"Wǒ xiǎng hē yì bēi nǎichá.","vn":"Tôi muốn uống một ly trà sữa."},{"cn":"这家店的奶茶很有名。","pinyin":"Zhè jiā diàn de nǎichá hěn yǒumíng.","vn":"Trà sữa của cửa hàng này rất nổi tiếng."},{"cn":"我们去买奶茶吧。","pinyin":"Wǒmen qù mǎi nǎichá ba.","vn":"Chúng ta đi mua trà sữa đi."}]},{"hanzi":"跟","pinyin":"gēn","pos":"giới./liên.","vn":"với, và","examples":[{"cn":"我跟你一起去吧。","pinyin":"Wǒ gēn nǐ yìqǐ qù ba.","vn":"Tôi đi cùng với bạn nhé."},{"cn":"我喜欢跟朋友聊天。","pinyin":"Wǒ xǐhuan gēn péngyou liáotiān.","vn":"Tôi thích trò chuyện với bạn bè."},{"cn":"桌子上有书跟本子。","pinyin":"Zhuōzi shàng yǒu shū gēn běnzi.","vn":"Trên bàn có sách và vở."}]},{"hanzi":"走","pinyin":"zǒu","pos":"đgt.","vn":"đi bộ, đi","examples":[{"cn":"我们走路去学校吧。","pinyin":"Wǒmen zǒulù qù xuéxiào ba.","vn":"Chúng ta đi bộ đến trường nhé."},{"cn":"他每天走路上班。","pinyin":"Tā měitiān zǒulù shàngbān.","vn":"Mỗi ngày anh ấy đi bộ đi làm."},{"cn":"时间不早了，我们走吧。","pinyin":"Shíjiān bù zǎo le, wǒmen zǒu ba.","vn":"Không còn sớm nữa, chúng ta đi thôi."}]},{"hanzi":"酒店","pinyin":"jiǔdiàn","pos":"dt.","vn":"khách sạn","examples":[{"cn":"我们住在这家酒店。","pinyin":"Wǒmen zhù zài zhè jiā jiǔdiàn.","vn":"Chúng tôi ở khách sạn này."},{"cn":"这个酒店很干净，也很舒服。","pinyin":"Zhège jiǔdiàn hěn gānjìng, yě hěn shūfu.","vn":"Khách sạn này rất sạch sẽ và thoải mái."},{"cn":"你们在哪个酒店见面？","pinyin":"Nǐmen zài nǎge jiǔdiàn jiànmiàn?","vn":"Các bạn gặp nhau ở khách sạn nào?"}]}],"grammar":[{"title":"简单趋向补语(1) - Bổ ngữ xu hướng đơn (1)","explanation_vn":"Cấu trúc cơ bản của bổ ngữ xu hướng đơn là \"động từ + lai/khứ\". Trong đó, \"来\" biểu thị hành động di chuyển hướng về phía người nói, \"去\" biểu thị hành động di chuyển xa phía người nói, các động từ được sử dụng phổ biến nhất bao gồm \"上\", \"下\", \"进\", \"出\", \"回\" và \"过\". Ngoài ra, các động từ như \"叫、开、买、拿、请、送、要、找、走\" cũng có thể dùng trong cấu trúc này.","examples":[{"cn":"我不上去了，就在下面等你。","pinyin":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","vn":"(người nói ở dưới, người nghe ở trên)"},{"cn":"家月到下边了，你下去接她吧。","pinyin":"Jiāyuè dào xiàbian le, nǐ xiàqù jiē tā ba.","vn":"(người nói ở trên, người nghe ở dưới)"},{"cn":"我在外边呢，你出来吧。","pinyin":"Wǒ zài wàibian ne, nǐ chūlái ba.","vn":"(người nói ở ngoài, người nghe ở trong)"}]},{"title":"简单趋向补语(2) - Bổ ngữ xu hướng đơn (2)","explanation_vn":"Khi một động từ vừa mang bổ ngữ xu hướng vừa mang tân ngữ, nếu tân ngữ là danh từ chỉ địa điểm thì đặt trước \"来/去\"; nếu tân ngữ là danh từ chỉ sự vật thì có thể đặt trước hoặc sau \"来/去\". Ngoài ra, các động từ như \"开\", \"买\", \"拿\", \"请\", \"送\", \"要\", \"找\", \"走\"... cũng có thể kết hợp với các bổ ngữ xu hướng như \"上\", \"下\", \"进\", \"出\", \"回\", \"过\". Trong trường hợp này, động từ thường mang tân ngữ và đặt sau \"上, 下, 进, 出, 回, 过\".","examples":[{"cn":"你们太客气了，还拿这么多礼物来！","pinyin":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","vn":""},{"cn":"家月给我送来了一本书。","pinyin":"Jiāyuè gěi wǒ sònglái le yì běn shū.","vn":""},{"cn":"上课了，你们快进教室吧。","pinyin":"Shàngkè le, nǐmen kuài jìn jiàoshì ba.","vn":""},{"cn":"爸爸今天买回了很多水果。","pinyin":"Bàba jīntiān mǎihuí le hěn duō shuǐguǒ.","vn":""},{"cn":"妈妈拿出二十块钱，让小雪自己去买点儿吃的。","pinyin":"Māma náchū èrshí kuài qián, ràng Xiǎoxuě zìjǐ qù mǎi diǎnr chī de.","vn":""}]},{"title":"固定格式\"都……了\" - Cấu trúc cố định \"都……了\"","explanation_vn":"Cấu trúc cố định \"都……了\" biểu thị ý đã làm gì hoặc đạt được điều gì, thường mang sắc thái nhấn mạnh hoặc không hài lòng.","examples":[{"cn":"都12点了，我们吃饭吧。","pinyin":"Dōu shí'èr diǎn le, wǒmen chī fàn ba.","vn":""},{"cn":"都8点半了，您还不起床吗？","pinyin":"Dōu bā diǎn bàn le, nín hái bù qǐchuáng ma?","vn":""},{"cn":"我都去过北京了，不想再去了。","pinyin":"Wǒ dōu qùguo Běijīng le, bù xiǎng zài qù le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"安妮 (Annie)","cn":"家月，快下来吧，第一次去中国朋友家，别晚了。","pinyin":"Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"还有时间，你上来吧。","pinyin":"Hái yǒu shíjiān, nǐ shànglái ba."},{"speaker":"安妮 (Annie)","cn":"我不上去了，就在下面等你。","pinyin":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"那我一会儿就下去。","pinyin":"Nà wǒ yíhuìr jiù xiàqù."},{"speaker":"安妮 (Annie)","cn":"你快点儿吧。","pinyin":"Nǐ kuài diǎnr ba."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"没事，一雪姐说11点前到就可以。","pinyin":"Méishì, Yīxuě jiě shuō shíyī diǎn qián dào jiù kěyǐ."}],"translation_vn":"Annie: Gia Nguyệt, mau xuống nhé, lần đầu đến thăm nhà bạn người Trung Quốc, đừng đến muộn nhé.\nBạch Gia Nguyệt: Vẫn còn thời gian, bạn lên đây đi.\nAnnie: Mình không lên nữa, đợi bạn ở dưới này thôi.\nBạch Gia Nguyệt: Vậy thì một lát nữa mình sẽ xuống.\nAnnie: Bạn nhanh lên một chút nhé.\nBạch Gia Nguyệt: Không sao đâu, chị Nhất Tuyết bảo chúng ta đến trước 11 giờ là được.","audio_dialogue":"5-1 @xitoytili_luoluodafang.mp3","audio_vocab":"5-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。","pinyin":"Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai."},{"speaker":"白家月、安妮 (Bạch Gia Nguyệt, Annie)","cn":"你们好！","pinyin":"Nǐmen hǎo!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"爸、妈，这是白家月，这是安妮。她们都是一飞的学生。","pinyin":"Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuésheng."},{"speaker":"刘爷爷 (Ông Lưu)","cn":"家月、安妮，你们好！","pinyin":"Jiāyuè, Ānnī, nǐmen hǎo!"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"这是送你们的礼物。","pinyin":"Zhè shì sòng nǐmen de lǐwù."},{"speaker":"刘爷爷 (Ông Lưu)","cn":"你们太客气了，还拿这么多礼物来！","pinyin":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"一雪姐，这是给孩子们准备的礼物。","pinyin":"Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"谢谢！你们别客气，快坐吧！","pinyin":"Xièxie! Nǐmen bié kèqi, kuài zuò ba!"}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, Annie, mau vào đi! Để chị giới thiệu một chút nhé, đây là ông nội và bà nội của các con chị.\nBạch Gia Nguyệt và Annie: Chúng cháu chào hai bác!\nVương Nhất Tuyết: Bố mẹ ơi, đây là Bạch Gia Nguyệt, còn đây là Annie. Các em ấy đều là học sinh của Nhất Phi.\nÔng Lưu: Chào Gia Nguyệt! Chào Annie!\nBạch Gia Nguyệt: Đây là chút quà chúng cháu biếu hai bác ạ.\nÔng Lưu: Các cháu thật chu đáo, còn mang nhiều quà đến như vậy.\nBạch Gia Nguyệt: Chị Nhất Tuyết, đây là quà mà chúng em chuẩn bị cho các em nhỏ.\nVương Nhất Tuyết: Cảm ơn rất nhiều! Các em đừng khách sáo, mau ngồi xuống đi!","audio_dialogue":"5-3.mp3","audio_vocab":"5-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"都12点了，我们吃饭吧。","pinyin":"Dōu shí'èr diǎn le, wǒmen chī fàn ba."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"这么多好吃的，您太客气了！","pinyin":"Zhème duō hǎochī de, nín tài kèqi le!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"都是我自己做的，你们多吃点儿。","pinyin":"Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"奶茶也很好喝，是您自己做的吗？","pinyin":"Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"不是，奶茶是爷爷买的。","pinyin":"Bú shì, nǎichá shì yéye mǎi de."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"在哪儿买的？我还没喝过这么好喝的奶茶。","pinyin":"Zài nǎr mǎi de? Wǒ hái méi hēguo zhème hǎohē de nǎichá."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"就在前边的商场，吃完饭你们可以跟我去看看。","pinyin":"Jiù zài qiánbian de shāngchǎng, chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan."}],"translation_vn":"Vương Nhất Tuyết: Đã 12 giờ rồi, chúng ta ăn cơm thôi.\nBạch Gia Nguyệt: Nhiều món ngon quá ạ. Chị chu đáo quá!\nVương Nhất Tuyết: Tất cả những món này đều là chị tự tay làm đấy, em ăn nhiều một chút nhé.\nBạch Gia Nguyệt: Trà sữa cũng rất ngon. Chị tự làm à?\nVương Nhất Tuyết: Không, trà sữa là ông nội bọn em mua đấy.\nBạch Gia Nguyệt: Ông mua ở đâu vậy ạ? Em chưa từng uống trà sữa ngon như thế này.\nVương Nhất Tuyết: Ở trung tâm thương mại phía trước. Ăn xong các em có thể cùng chị đi xem.","audio_dialogue":"5-5 @xitoytili_luoluodafang.mp3","audio_vocab":"5-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"回国前一天，我们去一雪姐家了。到她家的时候，饭菜都做好了。刘爷爷还准备了奶茶。因为吃了太多东西，我们吃完饭是走回酒店的。","pinyin":"Huí guó qián yì tiān, wǒmen qù Yīxuě jiě jiā le. Dào tā jiā de shíhou, fàncài dōu zuòhǎo le. Liú yéye hái zhǔnbèi le nǎichá. Yīnwèi chīle tài duō dōngxi, wǒmen chīwán fàn shì zǒu huí jiǔdiàn de."}],"translation_vn":"Một ngày trước khi về nước, chúng tôi đã đi thăm nhà chị Nhất Tuyết. Khi chúng tôi đến nơi, đồ ăn đã sẵn sàng. Bác Lưu còn chuẩn bị cả trà sữa nữa. Vì ăn quá nhiều món, nên sau bữa ăn chúng tôi đã đi bộ về khách sạn.","audio_dialogue":"5-7.mp3","audio_vocab":"5-8.mp3"}]},{"id":6,"title_cn":"小雪，生日快乐！","title_pinyin":"Xiǎoxuě, shēngrì kuàilè!","title_vn":"Chúc mừng sinh nhật Tiểu Tuyết!","goals":["Có thể nghe hiểu và sử dụng được tính từ lặp lại để miêu tả tính chất hoặc trạng thái.","Nắm vững cách dùng của cụm từ cố định \"什么的\" để diễn đạt ý liệt kê chưa đầy đủ.","Nắm vững cách dùng của trợ từ kết cấu \"地\" để miêu tả cách thức hoặc trạng thái của hành động.","Hiểu về cách người Trung Quốc tổ chức sinh nhật."],"vocab":[{"hanzi":"生日","pinyin":"shēngrì","pos":"dt.","vn":"sinh nhật","examples":[{"cn":"今天是我的生日。","pinyin":"Jīntiān shì wǒ de shēngrì.","vn":"Hôm nay là sinh nhật của tôi."},{"cn":"祝你生日快乐！","pinyin":"Zhù nǐ shēngrì kuàilè!","vn":"Chúc bạn sinh nhật vui vẻ!"},{"cn":"我们一起过生日吧。","pinyin":"Wǒmen yìqǐ guò shēngrì ba.","vn":"Chúng ta cùng đón sinh nhật nhé."}]},{"hanzi":"忘","pinyin":"wàng","pos":"đgt.","vn":"quên","examples":[{"cn":"我忘了带手机。","pinyin":"Wǒ wàngle dài shǒujī.","vn":"Tôi quên mang điện thoại."},{"cn":"别忘了关门。","pinyin":"Bié wàngle guān mén.","vn":"Đừng quên đóng cửa."},{"cn":"我差点儿忘了你的生日。","pinyin":"Wǒ chàdiǎnr wàngle nǐ de shēngrì.","vn":"Tôi suýt nữa quên mất sinh nhật của bạn."}]},{"hanzi":"画","pinyin":"huà","pos":"đgt./dt.","vn":"vẽ, tranh","examples":[{"cn":"妹妹喜欢画画儿。","pinyin":"Mèimei xǐhuan huà huàr.","vn":"Em gái thích vẽ tranh."},{"cn":"这幅画真好看。","pinyin":"Zhè fú huà zhēn hǎokàn.","vn":"Bức tranh này thật đẹp."},{"cn":"他给我画了一张画。","pinyin":"Tā gěi wǒ huàle yì zhāng huà.","vn":"Anh ấy đã vẽ cho tôi một bức tranh."}]},{"hanzi":"画笔","pinyin":"huàbǐ","pos":"dt.","vn":"bút màu, bút vẽ","examples":[{"cn":"这是我的画笔。","pinyin":"Zhè shì wǒ de huàbǐ.","vn":"Đây là bút vẽ của tôi."},{"cn":"她送了我一盒画笔。","pinyin":"Tā sòngle wǒ yì hé huàbǐ.","vn":"Cô ấy tặng tôi một hộp bút vẽ."},{"cn":"我用画笔画了一只小鸟。","pinyin":"Wǒ yòng huàbǐ huàle yì zhī xiǎoniǎo.","vn":"Tôi dùng bút vẽ vẽ một con chim nhỏ."}]},{"hanzi":"蛋糕","pinyin":"dàngāo","pos":"dt.","vn":"bánh kem, bánh ga tô","examples":[{"cn":"妈妈给我买了一个生日蛋糕。","pinyin":"Māma gěi wǒ mǎile yí gè shēngrì dàngāo.","vn":"Mẹ mua cho tôi một cái bánh kem sinh nhật."},{"cn":"这个蛋糕很甜，很好吃。","pinyin":"Zhège dàngāo hěn tián, hěn hǎochī.","vn":"Cái bánh kem này rất ngọt và ngon."},{"cn":"我们一起吃蛋糕吧。","pinyin":"Wǒmen yìqǐ chī dàngāo ba.","vn":"Chúng ta cùng ăn bánh kem nhé."}]},{"hanzi":"快乐","pinyin":"kuàilè","pos":"tt.","vn":"vui vẻ","examples":[{"cn":"祝你每天都快乐。","pinyin":"Zhù nǐ měitiān dōu kuàilè.","vn":"Chúc bạn ngày nào cũng vui vẻ."},{"cn":"今天我很快乐。","pinyin":"Jīntiān wǒ hěn kuàilè.","vn":"Hôm nay tôi rất vui."},{"cn":"他看起来很快乐。","pinyin":"Tā kànqǐlái hěn kuàilè.","vn":"Trông anh ấy có vẻ rất vui vẻ."}]},{"hanzi":"打开","pinyin":"dǎkāi","pos":"đgt.","vn":"mở ra, bóc ra","examples":[{"cn":"请打开窗户。","pinyin":"Qǐng dǎkāi chuānghu.","vn":"Làm ơn mở cửa sổ."},{"cn":"我打开礼物看了看。","pinyin":"Wǒ dǎkāi lǐwù kànle kàn.","vn":"Tôi mở quà ra xem thử."},{"cn":"你能帮我打开这个瓶子吗？","pinyin":"Nǐ néng bāng wǒ dǎkāi zhège píngzi ma?","vn":"Bạn có thể giúp tôi mở cái chai này không?"}]},{"hanzi":"长","pinyin":"cháng","pos":"tt.","vn":"dài","examples":[{"cn":"她的头发很长。","pinyin":"Tā de tóufa hěn cháng.","vn":"Tóc của cô ấy rất dài."},{"cn":"这条路很长。","pinyin":"Zhè tiáo lù hěn cháng.","vn":"Con đường này rất dài."},{"cn":"这件衣服太长了。","pinyin":"Zhè jiàn yīfu tài cháng le.","vn":"Cái áo này dài quá."}]},{"hanzi":"鱼","pinyin":"yú","pos":"dt.","vn":"cá","examples":[{"cn":"我喜欢吃鱼。","pinyin":"Wǒ xǐhuan chī yú.","vn":"Tôi thích ăn cá."},{"cn":"河里有很多鱼。","pinyin":"Hé lǐ yǒu hěn duō yú.","vn":"Dưới sông có nhiều cá."},{"cn":"爸爸周末喜欢去钓鱼。","pinyin":"Bàba zhōumò xǐhuan qù diàoyú.","vn":"Cuối tuần bố thích đi câu cá."}]},{"hanzi":"肉","pinyin":"ròu","pos":"dt.","vn":"thịt","examples":[{"cn":"我不喜欢吃肉。","pinyin":"Wǒ bù xǐhuan chī ròu.","vn":"Tôi không thích ăn thịt."},{"cn":"这个菜里有很多肉。","pinyin":"Zhège cài lǐ yǒu hěn duō ròu.","vn":"Món này có nhiều thịt."},{"cn":"妈妈买了一些牛肉。","pinyin":"Māma mǎile yìxiē niúròu.","vn":"Mẹ đã mua một ít thịt bò."}]},{"hanzi":"过","pinyin":"guò","pos":"đgt.","vn":"trải qua, đón (sinh nhật)","examples":[{"cn":"我们在家过生日。","pinyin":"Wǒmen zài jiā guò shēngrì.","vn":"Chúng tôi đón sinh nhật ở nhà."},{"cn":"你今年怎么过年？","pinyin":"Nǐ jīnnián zěnme guònián?","vn":"Năm nay bạn đón Tết thế nào?"},{"cn":"他每天过得很开心。","pinyin":"Tā měitiān guò de hěn kāixīn.","vn":"Mỗi ngày anh ấy sống rất vui vẻ."}]},{"hanzi":"地","pinyin":"de","pos":"trợ.","vn":"dùng để nối trạng ngữ với động từ","examples":[{"cn":"他高兴地笑了。","pinyin":"Tā gāoxìng de xiào le.","vn":"Anh ấy cười một cách vui vẻ."},{"cn":"孩子们快乐地玩儿。","pinyin":"Háizimen kuàilè de wánr.","vn":"Bọn trẻ vui vẻ chơi đùa."},{"cn":"她慢慢地走进来了。","pinyin":"Tā mànmàn de zǒu jìnlái le.","vn":"Cô ấy từ từ đi vào."}]},{"hanzi":"床","pinyin":"chuáng","pos":"dt.","vn":"giường","examples":[{"cn":"我的床很舒服。","pinyin":"Wǒ de chuáng hěn shūfu.","vn":"Giường của tôi rất thoải mái."},{"cn":"他坐在床上看书。","pinyin":"Tā zuò zài chuáng shàng kàn shū.","vn":"Anh ấy ngồi trên giường đọc sách."},{"cn":"猫在床下面睡觉。","pinyin":"Māo zài chuáng xiàmiàn shuìjiào.","vn":"Con mèo ngủ dưới giường."}]},{"hanzi":"舒服","pinyin":"shūfu","pos":"tt.","vn":"thoải mái, dễ chịu","examples":[{"cn":"这张床很舒服。","pinyin":"Zhè zhāng chuáng hěn shūfu.","vn":"Cái giường này rất thoải mái."},{"cn":"我今天不太舒服。","pinyin":"Wǒ jīntiān bú tài shūfu.","vn":"Hôm nay tôi thấy không khỏe lắm."},{"cn":"穿这双鞋很舒服。","pinyin":"Chuān zhè shuāng xié hěn shūfu.","vn":"Đi đôi giày này rất thoải mái."}]}],"grammar":[{"title":"形容词重叠 - Tính từ lặp lại","explanation_vn":"Hình thức lặp lại của tính từ đơn âm tiết \"A\" là \"AA\", hình thức lặp lại của tính từ song âm tiết \"AB\" là \"AABB\". Tính từ lặp lại dùng để biểu thị mức độ cao hoặc tình cảm yêu thích, thân mật.","examples":[{"cn":"我再给她买个大大的生日蛋糕。","pinyin":"Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.","vn":""},{"cn":"这只猫小小的，真让人喜欢。","pinyin":"Zhè zhī māo xiǎoxiǎo de, zhēn ràng rén xǐhuan.","vn":""},{"cn":"一雪的女儿每天都漂漂亮亮的。","pinyin":"Yīxuě de nǚ'ér měitiān dōu piàopiàoliàngliàng de.","vn":""}]},{"title":"固定短语\"什么的\" - Cụm từ cố định \"什么的\"","explanation_vn":"Cụm từ cố định \"什么的\" có ý nghĩa là \"vân vân (...)\". Cấu trúc cơ bản: ……什么的.","examples":[{"cn":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗，白色的猫什么的。","pinyin":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","vn":""},{"cn":"桌子上有电脑、杯子、书和画笔什么的。","pinyin":"Zhuōzi shang yǒu diànnǎo, bēizi, shū hé huàbǐ shénmede.","vn":""},{"cn":"她拿来了一些水、面包和苹果什么的。","pinyin":"Tā nálái le yìxiē shuǐ, miànbāo hé píngguǒ shénmede.","vn":""}]},{"title":"结构助词\"地\" - Trợ từ kết cấu \"地\"","explanation_vn":"Trợ từ kết cấu \"地\" thường đặt giữa tính từ và động từ để biểu thị cách thức hoặc trạng thái của hành động.","examples":[{"cn":"过生日就要吃好吃的，还要高高兴兴地玩。","pinyin":"Guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","vn":""},{"cn":"老师早早地到了教室。","pinyin":"Lǎoshī zǎozǎo de dàole jiàoshì.","vn":""},{"cn":"爸爸很快地吃完早饭，就去上班了。","pinyin":"Bàba hěn kuài de chīwán zǎofàn, jiù qù shàngbān le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"明天就是女儿的生日了。","pinyin":"Míngtiān jiù shì nǚ'ér de shēngrì le."},{"speaker":"刘明 (Lưu Minh)","cn":"你不说，我还真忘了。我们给她准备个什么礼物呢？","pinyin":"Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi ge shénme lǐwù ne?"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"她喜欢画画，你觉得画笔怎么样？","pinyin":"Tā xǐhuan huàhuà, nǐ juéde huàbǐ zěnmeyàng?"},{"speaker":"刘明 (Lưu Minh)","cn":"就送画笔吧！","pinyin":"Jiù sòng huàbǐ ba!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"那我明天上午就去买。","pinyin":"Nà wǒ míngtiān shàngwǔ jiù qù mǎi."},{"speaker":"刘明 (Lưu Minh)","cn":"好的！我再给她买个大大的生日蛋糕。","pinyin":"Hǎo de! Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo."}],"translation_vn":"Vương Nhất Tuyết: Ngày mai là sinh nhật con gái rồi.\nLưu Minh: Nếu em không nhắc thì anh đã quên mất rồi. Chúng ta nên chuẩn bị quà gì cho con nhỉ?\nVương Nhất Tuyết: Con thích vẽ tranh. Anh thấy tặng con bút vẽ màu có được không?\nLưu Minh: Thế thì tặng bút màu nhé!\nVương Nhất Tuyết: Vậy thì sáng mai em sẽ đi mua.\nLưu Minh: Được! Anh cũng sẽ mua thêm cho con một chiếc bánh sinh nhật to.","audio_dialogue":"6-1.mp3","audio_vocab":"6-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘明 (Lưu Minh)","cn":"小雪，生日快乐！","pinyin":"Xiǎoxuě, shēngrì kuàilè!"},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"姐姐，生日快乐！","pinyin":"Jiějie, shēngrì kuàilè!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"小雪，这是爸爸、妈妈送你的礼物。","pinyin":"Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù."},{"speaker":"刘明 (Lưu Minh)","cn":"你打开看看喜欢不喜欢。","pinyin":"Nǐ dǎkāi kànkan xǐhuan bu xǐhuan."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"画笔！我很喜欢！","pinyin":"Huàbǐ! Wǒ hěn xǐhuan!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"那你想画点儿什么？","pinyin":"Nà nǐ xiǎng huà diǎnr shénme?"},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗，白色的猫什么的。","pinyin":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede."},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"那我要画一个穿白色衣服的姐姐。","pinyin":"Nà wǒ yào huà yí ge chuān báisè yīfu de jiějie."}],"translation_vn":"Lưu Minh: Chúc mừng sinh nhật Tiểu Tuyết!\nLưu Tiểu Minh: Chúc mừng sinh nhật chị!\nVương Nhất Tuyết: Tiểu Tuyết, đây là quà bố mẹ tặng con.\nLưu Minh: Con mở ra xem có thích không.\nLưu Tiểu Tuyết: Bút vẽ à, con rất thích ạ!\nVương Nhất Tuyết: Thế con muốn vẽ gì đây?\nLưu Tiểu Tuyết: Vẽ cả gia đình mình. Có bố, mẹ, em trai, có thêm con chó màu đen, con mèo trắng...\nLưu Tiểu Minh: Vậy em muốn vẽ một chị gái mặc quần áo màu trắng.","audio_dialogue":"6-3.mp3","audio_vocab":"6-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘明 (Lưu Minh)","cn":"小雪，看看今天有什么好吃的。","pinyin":"Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"长长的面条儿，大大的蛋糕。","pinyin":"Chángcháng de miàntiáor, dàdà de dàngāo."},{"speaker":"刘明 (Lưu Minh)","cn":"你看，还有鱼啊肉啊什么的，都是你喜欢吃的。","pinyin":"Nǐ kàn, hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"谢谢爸爸、妈妈！","pinyin":"Xièxie bàba, māma!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","pinyin":"Kuài qù jiào dìdi guòlái chī fàn ba, chīwán fàn wǒmen hái yào chūqù wán ne."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"过生日真好啊！","pinyin":"Guò shēngrì zhēn hǎo a!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"是的，过生日就要吃好吃的，还要高高兴兴地玩。","pinyin":"Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán."}],"translation_vn":"Lưu Minh: Tiểu Tuyết, con nhìn xem hôm nay có những món gì ngon nào.\nLưu Tiểu Tuyết: Mì sợi dài và chiếc bánh ga tô lớn.\nLưu Minh: Con nhìn xem, còn có cá, thịt và những món khác nữa. Tất cả đều là những món con thích ăn.\nLưu Tiểu Tuyết: Cảm ơn bố mẹ ạ!\nVương Nhất Tuyết: Mau gọi em trai con ra ăn cơm đi. Ăn xong chúng ta sẽ đi chơi nhé.\nLưu Tiểu Tuyết: Sinh nhật thật tuyệt!\nVương Nhất Tuyết: Đúng vậy, sinh nhật thì phải ăn món ngon, còn phải chơi vui nữa.","audio_dialogue":"6-5.mp3","audio_vocab":"6-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天是女儿的生日。我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。吃完晚饭，一家人去看了个电影。回家后，孩子们早早地就上床了。明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。这是很忙，很累，但很快乐的一天。","pinyin":"Jīntiān shì nǚ'ér de shēngrì. Wǒmen mǎile dàngāo, zuòle miàntiáor, hái zuòle yú a ròu a shénmede. Chīwán wǎnfàn, yì jiā rén qù kànle gè diànyǐng. Huí jiā hòu, háizimen zǎozǎo de jiù shàng chuáng le. Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng. Zhè shì hěn máng, hěn lèi, dàn hěn kuàilè de yì tiān."}],"translation_vn":"Hôm nay là sinh nhật con gái. Chúng tôi đã mua một chiếc bánh ga tô, nấu mì sợi, còn làm các món như cá, thịt... Sau khi ăn tối xong, cả gia đình chúng tôi đã đi xem phim. Sau khi về nhà, bọn trẻ đi ngủ sớm. Ngày mai không phải đi học, chúng nói muốn ngủ một giấc thật thoải mái, bảo chúng tôi gọi chúng dậy muộn hơn một chút. Hôm nay là một ngày rất bận rộn và rất mệt, nhưng cũng là một ngày rất vui.","audio_dialogue":"6-7.mp3","audio_vocab":"6-8.mp3"}]},{"id":7,"title_cn":"他篮球打得很好","title_pinyin":"Tā lánqiú dǎ de hěn hǎo","title_vn":"Bạn ấy chơi bóng rổ rất hay","goals":["能听懂并描述动作进行的状态。Có thể nghe hiểu và miêu tả được trạng thái của hành động đang diễn ra.","掌握紧缩复句 \"一……就……\" 的用法，能表达动作接连发生的意思。Nắm vững cách dùng của câu ghép rút gọn \"一……就……\" để diễn đạt các hành động xảy ra liên tiếp.","能谈论常做的运动。Có thể nói về những môn thể thao thường tập luyện."],"vocab":[{"hanzi":"从","pinyin":"cóng","pos":"giới.","vn":"từ","examples":[{"cn":"我从中国来。","pinyin":"Wǒ cóng Zhōngguó lái.","vn":"Tôi đến từ Trung Quốc."},{"cn":"从这儿到学校很近。","pinyin":"Cóng zhèr dào xuéxiào hěn jìn.","vn":"Từ đây đến trường rất gần."},{"cn":"他从早上到晚上都在工作。","pinyin":"Tā cóng zǎoshang dào wǎnshang dōu zài gōngzuò.","vn":"Anh ấy làm việc từ sáng đến tối."}]},{"hanzi":"往","pinyin":"wǎng","pos":"giới./dgt.","vn":"hướng tới, đi đến, về phía","examples":[{"cn":"往前走就是医院。","pinyin":"Wǎng qián zǒu jiù shì yīyuàn.","vn":"Đi thẳng về phía trước là bệnh viện."},{"cn":"这辆车往北京开。","pinyin":"Zhè liàng chē wǎng Běijīng kāi.","vn":"Chiếc xe này chạy về hướng Bắc Kinh."},{"cn":"请往右边看。","pinyin":"Qǐng wǎng yòubian kàn.","vn":"Xin hãy nhìn về bên phải."}]},{"hanzi":"跑","pinyin":"pǎo","pos":"dgt.","vn":"chạy","examples":[{"cn":"他跑得很快。","pinyin":"Tā pǎo de hěn kuài.","vn":"Anh ấy chạy rất nhanh."},{"cn":"小狗在公园里跑。","pinyin":"Xiǎogǒu zài gōngyuán lǐ pǎo.","vn":"Con chó con chạy trong công viên."},{"cn":"别跑,慢慢走。","pinyin":"Bié pǎo, mànmàn zǒu.","vn":"Đừng chạy, đi từ từ thôi."}]},{"hanzi":"打","pinyin":"dǎ","pos":"dgt.","vn":"đánh, chơi (thể thao)","examples":[{"cn":"他喜欢打篮球。","pinyin":"Tā xǐhuan dǎ lánqiú.","vn":"Anh ấy thích chơi bóng rổ."},{"cn":"别打人!","pinyin":"Bié dǎ rén!","vn":"Đừng đánh người!"},{"cn":"我想给你打电话。","pinyin":"Wǒ xiǎng gěi nǐ dǎ diànhuà.","vn":"Tôi muốn gọi điện cho bạn."}]},{"hanzi":"篮球","pinyin":"lánqiú","pos":"dt.","vn":"bóng rổ","examples":[{"cn":"我们下午打篮球,好吗?","pinyin":"Wǒmen xiàwǔ dǎ lánqiú, hǎo ma?","vn":"Chiều nay chúng ta chơi bóng rổ nhé?"},{"cn":"他的篮球打得很好。","pinyin":"Tā de lánqiú dǎ de hěn hǎo.","vn":"Anh ấy chơi bóng rổ rất giỏi."},{"cn":"这个篮球是新买的。","pinyin":"Zhège lánqiú shì xīn mǎi de.","vn":"Quả bóng rổ này mới mua."}]},{"hanzi":"运动","pinyin":"yùndòng","pos":"dt./dgt.","vn":"thể thao, môn thể thao, vận động, tập thể dục...","examples":[{"cn":"游泳是一种很好的运动。","pinyin":"Yóuyǒng shì yì zhǒng hěn hǎo de yùndòng.","vn":"Bơi lội là một môn thể thao rất tốt."},{"cn":"你每天运动吗?","pinyin":"Nǐ měitiān yùndòng ma?","vn":"Bạn có vận động mỗi ngày không?"},{"cn":"医生让我多运动。","pinyin":"Yīshēng ràng wǒ duō yùndòng.","vn":"Bác sĩ bảo tôi vận động nhiều hơn."}]},{"hanzi":"踢","pinyin":"tī","pos":"dgt.","vn":"đá","examples":[{"cn":"他喜欢踢足球。","pinyin":"Tā xǐhuan tī zúqiú.","vn":"Anh ấy thích đá bóng."},{"cn":"别踢我的椅子。","pinyin":"Bié tī wǒ de yǐzi.","vn":"Đừng đá ghế của tôi."},{"cn":"小孩儿在踢球。","pinyin":"Xiǎoháir zài tī qiú.","vn":"Đứa trẻ đang đá bóng."}]},{"hanzi":"足球","pinyin":"zúqiú","pos":"dt.","vn":"bóng đá","examples":[{"cn":"他是我们学校的足球明星。","pinyin":"Tā shì wǒmen xuéxiào de zúqiú míngxīng.","vn":"Anh ấy là ngôi sao bóng đá của trường chúng tôi."},{"cn":"我们周末一起看足球比赛吧。","pinyin":"Wǒmen zhōumò yìqǐ kàn zúqiú bǐsài ba.","vn":"Cuối tuần chúng ta cùng xem trận bóng đá nhé."},{"cn":"弟弟每天都踢足球。","pinyin":"Dìdi měitiān dōu tī zúqiú.","vn":"Em trai hàng ngày đều đá bóng."}]},{"hanzi":"球","pinyin":"qiú","pos":"dt.","vn":"quả bóng","examples":[{"cn":"这个球是谁的?","pinyin":"Zhège qiú shì shéi de?","vn":"Quả bóng này là của ai?"},{"cn":"小狗把球叼回来了。","pinyin":"Xiǎogǒu bǎ qiú diāo huílái le.","vn":"Con chó con ngậm quả bóng mang về."},{"cn":"球掉到河里了。","pinyin":"Qiú diào dào hé lǐ le.","vn":"Quả bóng rơi xuống sông rồi."}]},{"hanzi":"得","pinyin":"de","pos":"trợ.","vn":"dùng giữa động từ/tính từ và bổ ngữ kết quả/trình độ","examples":[{"cn":"他说得很好。","pinyin":"Tā shuō de hěn hǎo.","vn":"Anh ấy nói rất hay."},{"cn":"你今天来得早。","pinyin":"Nǐ jīntiān lái de zǎo.","vn":"Hôm nay bạn đến sớm."},{"cn":"她高兴得跳了起来。","pinyin":"Tā gāoxìng de tiào le qǐlái.","vn":"Cô ấy vui đến mức nhảy cẫng lên."}]},{"hanzi":"跑步","pinyin":"pǎobù","pos":"dgt.","vn":"chạy bộ","examples":[{"cn":"我每天早上跑步。","pinyin":"Wǒ měitiān zǎoshang pǎobù.","vn":"Mỗi sáng tôi đều chạy bộ."},{"cn":"跑步对身体很好。","pinyin":"Pǎobù duì shēntǐ hěn hǎo.","vn":"Chạy bộ rất tốt cho sức khỏe."},{"cn":"他喜欢在公园跑步。","pinyin":"Tā xǐhuan zài gōngyuán pǎobù.","vn":"Anh ấy thích chạy bộ trong công viên."}]},{"hanzi":"游泳","pinyin":"yóuyǒng","pos":"dgt.","vn":"bơi, bơi lội","examples":[{"cn":"夏天我们常常去游泳。","pinyin":"Xiàtiān wǒmen chángcháng qù yóuyǒng.","vn":"Mùa hè chúng tôi thường đi bơi."},{"cn":"我不会游泳。","pinyin":"Wǒ bú huì yóuyǒng.","vn":"Tôi không biết bơi."},{"cn":"她游泳游得很快。","pinyin":"Tā yóuyǒng yóu de hěn kuài.","vn":"Cô ấy bơi rất nhanh."}]},{"hanzi":"游","pinyin":"yóu","pos":"dgt.","vn":"bơi, bơi lội","examples":[{"cn":"他游得比我快。","pinyin":"Tā yóu de bǐ wǒ kuài.","vn":"Anh ấy bơi nhanh hơn tôi."},{"cn":"鱼在水里游来游去。","pinyin":"Yú zài shuǐ lǐ yóu lái yóu qù.","vn":"Con cá bơi qua bơi lại trong nước."},{"cn":"我们一起游到那边去吧。","pinyin":"Wǒmen yìqǐ yóu dào nàbiān qù ba.","vn":"Chúng ta cùng bơi qua bên đó đi."}]},{"hanzi":"爱好","pinyin":"àihào","pos":"dt./dgt.","vn":"sở thích, thích","examples":[{"cn":"你的爱好是什么?","pinyin":"Nǐ de àihào shì shénme?","vn":"Sở thích của bạn là gì?"},{"cn":"我的爱好是看书。","pinyin":"Wǒ de àihào shì kàn shū.","vn":"Sở thích của tôi là đọc sách."},{"cn":"他爱好运动。","pinyin":"Tā àihào yùndòng.","vn":"Anh ấy thích thể thao."}]},{"hanzi":"开始","pinyin":"kāishǐ","pos":"dgt./dt.","vn":"bắt đầu, lúc đầu","examples":[{"cn":"电影几点开始?","pinyin":"Diànyǐng jǐ diǎn kāishǐ?","vn":"Mấy giờ phim bắt đầu?"},{"cn":"我们开始上课吧。","pinyin":"Wǒmen kāishǐ shàngkè ba.","vn":"Chúng ta bắt đầu học thôi."},{"cn":"一开始我不懂,后来就明白了。","pinyin":"Yì kāishǐ wǒ bù dǒng, hòulái jiù míngbai le.","vn":"Lúc đầu tôi không hiểu, sau đó thì hiểu rồi."}]}],"grammar":[{"title":"紧缩复句 \"一……就……\" (Câu ghép rút gọn \"一……就……\")","explanation_vn":"Câu ghép rút gọn \"一……就……\" biểu thị hành động thứ hai xảy ra ngay sau hành động thứ nhất; đồng thời cũng thể hiện hành động thứ nhất là điều kiện hoặc nguyên nhân, còn hành động thứ hai là kết quả. Khi chủ ngữ giống nhau, chủ ngữ được đặt trước \"一\" hoặc \"就\"; khi chủ ngữ khác nhau, hai chủ ngữ lần lượt đứng trước \"一\" và \"就\".","examples":[{"cn":"你怎么一下课就往外跑？","pinyin":"Nǐ zěnme yī xiàkè jiù wǎng wài pǎo?","vn":""},{"cn":"我一到家，妈妈就打电话了。","pinyin":"Wǒ yī dào jiā, māma jiù dǎ diànhuà le.","vn":""},{"cn":"一到星期六，陈天中就跟同学去打篮球。","pinyin":"Yī dào xīngqīliù, Chén Tiānzhōng jiù gēn tóngxué qù dǎ lánqiú.","vn":""}]},{"title":"状态补语 (1) (Bổ ngữ trạng thái (1))","explanation_vn":"Bổ ngữ trạng thái dùng sau động từ, để nói rõ thêm trạng thái của hành động. Cấu trúc cơ bản: động từ + 得 + cụm tính từ. Hình thức phủ định là thêm \"不\" trước tính từ. Hình thức nghi vấn có ba cách: (1) thêm \"吗\" ở cuối câu; (2) động từ + 得 + tính từ + 不 + tính từ; (3) động từ + 得 + 怎么样.","examples":[{"cn":"我踢得还可以。","pinyin":"Wǒ tī de hái kěyǐ.","vn":""},{"cn":"他们打得很高兴。","pinyin":"Tāmen dǎ de hěn gāoxìng.","vn":""},{"cn":"白家月跑得不快。","pinyin":"Bái Jiāyuè pǎo de bú kuài.","vn":""},{"cn":"你跑得快吗？","pinyin":"Nǐ pǎo de kuài ma?","vn":""},{"cn":"他跑得早不早？","pinyin":"Tā pǎo de zǎo bu zǎo?","vn":""},{"cn":"他们跑得怎么样？","pinyin":"Tāmen pǎo de zěnmeyàng?","vn":""}]},{"title":"状态补语 (2) (Bổ ngữ trạng thái (2))","explanation_vn":"Trong câu có bổ ngữ trạng thái, nếu động từ là từ li hợp, cần lặp lại từ tố có tính chất động từ. Nếu động từ có tân ngữ, có thể đảo tân ngữ lên trước động từ hoặc lặp lại động từ.","examples":[{"cn":"我游泳游得不快。","pinyin":"Wǒ yóuyǒng yóu de bú kuài.","vn":""},{"cn":"你篮球打得怎么样？","pinyin":"Nǐ lánqiú dǎ de zěnmeyàng?","vn":""},{"cn":"白家月写汉字写得很好看。","pinyin":"Bái Jiāyuè xiě Hànzì xiě de hěn hǎokàn.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"Chén Tiānzhōng (陈天中)","cn":"安妮，你是什么时候从北京回来的？","pinyin":"Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?"},{"speaker":"Annie (安妮)","cn":"昨天下午。天中，你怎么一下课就往外跑？","pinyin":"Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yī xiàkè jiù wǎng wài pǎo?"},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"我跟同学说好了，一起去打篮球。","pinyin":"Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú."},{"speaker":"Annie (安妮)","cn":"我也想跟你们一起玩。","pinyin":"Wǒ yě xiǎng gēn nǐmen yìqǐ wán."},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"没问题，走吧。","pinyin":"Méi wèntí, zǒu ba."}],"translation_vn":"Trần Thiên Trung: Annie, bạn từ Bắc Kinh về khi nào vậy?\nAnnie: Chiều hôm qua. Thiên Trung, sao vừa mới tan học là bạn chạy ra ngoài ngay vậy?\nTrần Thiên Trung: Mình đã hẹn với các bạn cùng đi chơi bóng rổ.\nAnnie: Mình cũng muốn chơi cùng các bạn.\nTrần Thiên Trung: Không vấn đề gì, đi thôi!","audio_dialogue":"7-1.mp3","audio_vocab":"7-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"Annie (安妮)","cn":"天中，你是不是很喜欢打篮球？","pinyin":"Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?"},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"没错。","pinyin":"Méi cuò."},{"speaker":"Annie (安妮)","cn":"你还喜欢什么运动？","pinyin":"Nǐ hái xǐhuan shénme yùndòng?"},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"我还喜欢踢足球，一到星期天就跟朋友们去踢球。","pinyin":"Wǒ hái xǐhuan tī zúqiú, yī dào xīngqītiān jiù gēn péngyoumen qù tī qiú."},{"speaker":"Annie (安妮)","cn":"你踢得怎么样？","pinyin":"Nǐ tī de zěnmeyàng?"},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"我踢得还可以。","pinyin":"Wǒ tī de hái kěyǐ."}],"translation_vn":"Annie: Thiên Trung, có phải bạn rất thích chơi bóng rổ không?\nTrần Thiên Trung: Đúng vậy.\nAnnie: Bạn còn thích môn thể thao nào khác?\nTrần Thiên Trung: Mình còn thích chơi bóng đá nữa, cứ đến Chủ nhật mình lại đi đá bóng cùng bạn bè.\nAnnie: Bạn chơi có tốt không?\nTrần Thiên Trung: Mình chơi cũng tàm tạm.","audio_dialogue":"7-3 @xitoytili_luoluodafang.mp3","audio_vocab":"7-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"Chén Tiānzhōng (陈天中)","cn":"你篮球打得怎么样？","pinyin":"Nǐ lánqiú dǎ de zěnmeyàng?"},{"speaker":"Annie (安妮)","cn":"打得还可以！","pinyin":"Dǎ de hái kěyǐ!"},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"跑步呢？你跑步快不快？","pinyin":"Pǎobù ne? Nǐ pǎobù kuài bu kuài?"},{"speaker":"Annie (安妮)","cn":"我跑得不快，也不太喜欢跑步。","pinyin":"Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù."},{"speaker":"Chén Tiānzhōng (陈天中)","cn":"那你喜欢游泳吗？","pinyin":"Nà nǐ xǐhuan yóuyǒng ma?"},{"speaker":"Annie (安妮)","cn":"喜欢，但我游泳游得不快。","pinyin":"Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài."}],"translation_vn":"Trần Thiên Trung: Bạn chơi bóng rổ thế nào?\nAnnie: Chơi cũng tàm tạm.\nTrần Thiên Trung: Còn chạy bộ thì sao? Bạn chạy có nhanh không?\nAnnie: Mình chạy không nhanh, mình cũng không thích chạy bộ lắm.\nTrần Thiên Trung: Vậy bạn có thích bơi không?\nAnnie: Có, nhưng mình bơi không nhanh lắm.","audio_dialogue":"7-5 @xitoytili_luoluodafang.mp3","audio_vocab":"7-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我的爱好是运动。从上小学开始，我每天都跟爸爸去运动。现在我篮球打得很好，足球踢得不错，游泳游得也很快。我一有时间就去运动。","pinyin":"Wǒ de àihào shì yùndòng. Cóng shàng xiǎoxué kāishǐ, wǒ měitiān dōu gēn bàba qù yùndòng. Xiànzài wǒ lánqiú dǎ de hěn hǎo, zúqiú tī de búcuò, yóuyǒng yóu de yě hěn kuài. Wǒ yī yǒu shíjiān jiù qù yùndòng."}],"translation_vn":"Sở thích của tôi là thể thao. Bắt đầu từ khi học tiểu học, ngày nào tôi cũng tập thể dục cùng bố. Bây giờ tôi chơi bóng rổ rất giỏi, chơi bóng đá khá tốt, bơi cũng rất nhanh. Hễ có thời gian là tôi đi chơi thể thao.","audio_dialogue":"7-7 @xitoytili_luoluodafang.mp3","audio_vocab":"7-8 @xitoytili_luoluodafang.mp3"}]},{"id":8,"title_cn":"虽然你忘了，但是我记得","title_pinyin":"Suīrán nǐ wàng le, dànshì wǒ jìde","title_vn":"Mặc dù em quên, nhưng anh vẫn nhớ","goals":["能听懂并谈论生日的庆祝活动。Có thể nghe hiểu và nói được các hoạt động chúc mừng sinh nhật.","能听懂并使用\"比\"描述事物之间的差别。Có thể nghe hiểu và sử dụng được \"比\" để miêu tả sự khác biệt giữa các sự vật.","掌握转折复句 \"虽然……，但是……\" 的用法，能表达语义的转折。Nắm vững cách dùng của câu ghép chuyển ý \"虽然……，但是……\" để diễn đạt quan hệ ý nghĩa chuyển ý.","了解中国人对一些数字的喜好。Hiểu về sở thích của người Trung Quốc với một số con số nhất định."],"vocab":[{"hanzi":"手表","pinyin":"shǒubiǎo","pos":"dt.","vn":"đồng hồ đeo tay","examples":[{"cn":"这块手表很漂亮。","pinyin":"Zhè kuài shǒubiǎo hěn piàoliang.","vn":"Chiếc đồng hồ đeo tay này rất đẹp."},{"cn":"我的手表坏了。","pinyin":"Wǒ de shǒubiǎo huài le.","vn":"Đồng hồ của tôi bị hỏng rồi."},{"cn":"这是爸爸送我的手表。","pinyin":"Zhè shì bàba sòng wǒ de shǒubiǎo.","vn":"Đây là chiếc đồng hồ bố tặng tôi."}]},{"hanzi":"左边","pinyin":"zuǒbian","pos":"dt.","vn":"bên trái","examples":[{"cn":"银行在超市的左边。","pinyin":"Yínháng zài chāoshì de zuǒbian.","vn":"Ngân hàng ở bên trái siêu thị."},{"cn":"请坐在我的左边。","pinyin":"Qǐng zuò zài wǒ de zuǒbian.","vn":"Xin ngồi bên trái tôi."},{"cn":"往左边走就到了。","pinyin":"Wǎng zuǒbian zǒu jiù dào le.","vn":"Đi về bên trái là tới."}]},{"hanzi":"左","pinyin":"zuǒ","pos":"dt.","vn":"trái","examples":[{"cn":"请举起左手。","pinyin":"Qǐng jǔqǐ zuǒ shǒu.","vn":"Xin giơ tay trái lên."},{"cn":"我的左脚有点疼。","pinyin":"Wǒ de zuǒ jiǎo yǒudiǎn téng.","vn":"Chân trái tôi hơi đau."},{"cn":"他往左转了。","pinyin":"Tā wǎng zuǒ zhuǎn le.","vn":"Anh ấy rẽ trái."}]},{"hanzi":"比","pinyin":"bǐ","pos":"giới./dgt.","vn":"so, so với, hơn (so sánh)","examples":[{"cn":"今天比昨天冷。","pinyin":"Jīntiān bǐ zuótiān lěng.","vn":"Hôm nay lạnh hơn hôm qua."},{"cn":"他比我高。","pinyin":"Tā bǐ wǒ gāo.","vn":"Anh ấy cao hơn tôi."},{"cn":"我的中文比以前好多了。","pinyin":"Wǒ de Zhōngwén bǐ yǐqián hǎo duō le.","vn":"Tiếng Trung của tôi tốt hơn trước nhiều."}]},{"hanzi":"右边","pinyin":"yòubian","pos":"dt.","vn":"bên phải","examples":[{"cn":"请看右边的那张桌子。","pinyin":"Qǐng kàn yòubian de nà zhāng zhuōzi.","vn":"Xin nhìn cái bàn ở bên phải."},{"cn":"洗手间在右边。","pinyin":"Xǐshǒujiān zài yòubian.","vn":"Nhà vệ sinh ở bên phải."},{"cn":"他坐在我右边。","pinyin":"Tā zuò zài wǒ yòubian.","vn":"Anh ấy ngồi bên phải tôi."}]},{"hanzi":"右","pinyin":"yòu","pos":"dt.","vn":"phải","examples":[{"cn":"请用右手写字。","pinyin":"Qǐng yòng yòu shǒu xiě zì.","vn":"Xin dùng tay phải viết chữ."},{"cn":"前面右转就是公司。","pinyin":"Qiánmiàn yòu zhuǎn jiù shì gōngsī.","vn":"Phía trước rẽ phải là công ty."},{"cn":"他的右眼有点红。","pinyin":"Tā de yòu yǎn yǒudiǎn hóng.","vn":"Mắt phải của anh ấy hơi đỏ."}]},{"hanzi":"记得","pinyin":"jìde","pos":"dgt.","vn":"nhớ, nhớ ra","examples":[{"cn":"我记得他的名字。","pinyin":"Wǒ jìde tā de míngzi.","vn":"Tôi nhớ tên anh ấy."},{"cn":"你还记得我吗?","pinyin":"Nǐ hái jìde wǒ ma?","vn":"Bạn còn nhớ tôi không?"},{"cn":"我不记得把钥匙放在哪儿了。","pinyin":"Wǒ bú jìde bǎ yàoshi fàng zài nǎr le.","vn":"Tôi không nhớ đã để chìa khóa ở đâu."}]},{"hanzi":"爱情片","pinyin":"àiqíngpiàn","pos":"dt.","vn":"phim tình cảm","examples":[{"cn":"我喜欢看爱情片。","pinyin":"Wǒ xǐhuan kàn àiqíngpiàn.","vn":"Tôi thích xem phim tình cảm."},{"cn":"这部爱情片很感人。","pinyin":"Zhè bù àiqíngpiàn hěn gǎnrén.","vn":"Bộ phim tình cảm này rất cảm động."},{"cn":"她不喜欢爱情片,喜欢看喜剧。","pinyin":"Tā bù xǐhuan àiqíngpiàn, xǐhuan kàn xǐjù.","vn":"Cô ấy không thích phim tình cảm, thích xem phim hài."}]},{"hanzi":"有意思","pinyin":"yǒuyìsi","pos":"","vn":"hay, thú vị","examples":[{"cn":"这本书很有意思。","pinyin":"Zhè běn shū hěn yǒuyìsi.","vn":"Cuốn sách này rất thú vị."},{"cn":"他讲的笑话真有意思。","pinyin":"Tā jiǎng de xiàohua zhēn yǒuyìsi.","vn":"Câu chuyện cười anh ấy kể thật thú vị."},{"cn":"这个电影没有意思。","pinyin":"Zhège diànyǐng méiyǒu yìsi.","vn":"Bộ phim này không hay."}]},{"hanzi":"点","pinyin":"diǎn","pos":"dgt.","vn":"gọi, chọn (món)","examples":[{"cn":"你想点什么菜?","pinyin":"Nǐ xiǎng diǎn shénme cài?","vn":"Bạn muốn gọi món gì?"},{"cn":"我们点了三个菜。","pinyin":"Wǒmen diǎn le sān ge cài.","vn":"Chúng tôi gọi ba món."},{"cn":"服务员,我可以点菜了。","pinyin":"Fúwùyuán, wǒ kěyǐ diǎn cài le.","vn":"Phục vụ ơi, tôi có thể gọi món rồi."}]},{"hanzi":"虽然","pinyin":"suīrán","pos":"liên.","vn":"mặc dù, tuy","examples":[{"cn":"虽然下雨,但是我们还是去了。","pinyin":"Suīrán xiàyǔ, dànshì wǒmen háishi qù le.","vn":"Mặc dù trời mưa nhưng chúng tôi vẫn đi."},{"cn":"虽然他很忙,但是还来看我。","pinyin":"Suīrán tā hěn máng, dànshì hái lái kàn wǒ.","vn":"Mặc dù anh ấy rất bận nhưng vẫn đến thăm tôi."},{"cn":"虽然这个菜很贵,但是很好吃。","pinyin":"Suīrán zhège cài hěn guì, dànshì hěn hǎochī.","vn":"Mặc dù món này đắt nhưng rất ngon."}]},{"hanzi":"但是","pinyin":"dànshì","pos":"liên.","vn":"nhưng","examples":[{"cn":"我很想去,但是没有时间。","pinyin":"Wǒ hěn xiǎng qù, dànshì méiyǒu shíjiān.","vn":"Tôi rất muốn đi nhưng không có thời gian."},{"cn":"他个子不高,但是跑得很快。","pinyin":"Tā gèzi bù gāo, dànshì pǎo de hěn kuài.","vn":"Anh ấy không cao nhưng chạy rất nhanh."},{"cn":"东西很便宜,但是质量不好。","pinyin":"Dōngxi hěn piányi, dànshì zhìliàng bù hǎo.","vn":"Đồ rất rẻ nhưng chất lượng không tốt."}]},{"hanzi":"花","pinyin":"huā","pos":"dgt.","vn":"tiêu, chi tiêu","examples":[{"cn":"我今天花了很多钱。","pinyin":"Wǒ jīntiān huā le hěn duō qián.","vn":"Hôm nay tôi tiêu rất nhiều tiền."},{"cn":"买这个手表花了多少钱?","pinyin":"Mǎi zhège shǒubiǎo huā le duōshao qián?","vn":"Mua cái đồng hồ này tốn bao nhiêu tiền?"},{"cn":"他花了两个小时做作业。","pinyin":"Tā huā le liǎng ge xiǎoshí zuò zuòyè.","vn":"Anh ấy mất hai tiếng để làm bài tập."}]},{"hanzi":"妻子","pinyin":"qīzi","pos":"dt.","vn":"vợ","examples":[{"cn":"这是我的妻子。","pinyin":"Zhè shì wǒ de qīzi.","vn":"Đây là vợ tôi."},{"cn":"他的妻子是老师。","pinyin":"Tā de qīzi shì lǎoshī.","vn":"Vợ anh ấy là giáo viên."},{"cn":"我妻子做饭做得很好吃。","pinyin":"Wǒ qīzi zuòfàn zuò de hěn hǎochī.","vn":"Vợ tôi nấu ăn rất ngon."}]},{"hanzi":"丈夫","pinyin":"zhàngfū","pos":"dt.","vn":"chồng","examples":[{"cn":"她的丈夫在北京工作。","pinyin":"Tā de zhàngfū zài Běijīng gōngzuò.","vn":"Chồng cô ấy làm việc ở Bắc Kinh."},{"cn":"我丈夫很喜欢运动。","pinyin":"Wǒ zhàngfū hěn xǐhuan yùndòng.","vn":"Chồng tôi rất thích thể thao."},{"cn":"她和丈夫一起去旅游。","pinyin":"Tā hé zhàngfū yìqǐ qù lǚyóu.","vn":"Cô ấy cùng chồng đi du lịch."}]},{"hanzi":"饭馆","pinyin":"fànguǎn","pos":"dt.","vn":"nhà hàng, quán ăn","examples":[{"cn":"我们去饭馆吃饭吧。","pinyin":"Wǒmen qù fànguǎn chīfàn ba.","vn":"Chúng ta đi nhà hàng ăn cơm nhé."},{"cn":"这家饭馆的菜很好吃。","pinyin":"Zhè jiā fànguǎn de cài hěn hǎochī.","vn":"Món ăn ở nhà hàng này rất ngon."},{"cn":"附近有一家新饭馆。","pinyin":"Fùjìn yǒu yì jiā xīn fànguǎn.","vn":"Gần đây có một nhà hàng mới."}]}],"grammar":[{"title":"比较句 (1) (Câu so sánh (1))","explanation_vn":"Trong bài này, chúng ta học cách dùng giới từ \"比\" để so sánh sự khác biệt về tính chất và trạng thái của sự vật. Cấu trúc cơ bản: A 比 B + tính từ/cụm tính từ.","examples":[{"cn":"我也觉得左边的比右边的好看。","pinyin":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","vn":""},{"cn":"今天比昨天冷。","pinyin":"Jīntiān bǐ zuótiān lěng.","vn":""},{"cn":"他觉得篮球比足球有意思。","pinyin":"Tā juéde lánqiú bǐ zúqiú yǒu yìsi.","vn":""}]},{"title":"比较句 (2) (Câu so sánh (2))","explanation_vn":"Trong câu so sánh dùng \"比\", không thể thêm phó từ chỉ mức độ như \"很\", \"非常\" vào trước tính từ, có thể thêm \"还\" và \"更\" để chỉ mức độ cao hơn.","examples":[{"cn":"我看网上说这个电影比那个爱情片更有意思。（爱情片很有意思，这个电影更有意思）","pinyin":"Wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi. (Àiqíngpiàn hěn yǒu yìsi, zhège diànyǐng gèng yǒu yìsi.)","vn":""},{"cn":"今天比昨天更热。（昨天很热，今天更热）","pinyin":"Jīntiān bǐ zuótiān gèng rè. (Zuótiān hěn rè, jīntiān gèng rè.)","vn":""},{"cn":"我觉得奶茶比牛奶还好喝。（我觉得牛奶很好喝，奶茶更好喝）","pinyin":"Wǒ juéde nǎichá bǐ niúnǎi hái hǎohē. (Wǒ juéde niúnǎi hěn hǎohē, nǎichá gèng hǎohē.)","vn":""}]},{"title":"转折复句 \"虽然……，但是……\" (Câu ghép chuyển ý \"虽然……，但是……\")","explanation_vn":"Câu ghép chuyển ý được tạo bởi cấu trúc \"虽然……，但是……\". \"虽然\" và \"但是\" có thể sử dụng thành cặp, cũng có thể lược bớt một trong hai từ này.","examples":[{"cn":"虽然你忘了，但是我记得。","pinyin":"Suīrán nǐ wàng le, dànshì wǒ jìde.","vn":""},{"cn":"外边下雪了，但是不太冷。","pinyin":"Wàibian xiàxuě le, dànshì bú tài lěng.","vn":""},{"cn":"虽然觉得有点儿累，我还是走回家了。","pinyin":"Suīrán juéde yǒudiǎnr lèi, wǒ háishi zǒu huí jiā le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"Wáng Yīxuě (王一雪)","cn":"你看，这两块手表怎么样？","pinyin":"Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?"},{"speaker":"Liú Míng (刘明)","cn":"都不错！","pinyin":"Dōu búcuò!"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"我喜欢左边的这个。","pinyin":"Wǒ xǐhuan zuǒbian de zhège."},{"speaker":"Liú Míng (刘明)","cn":"我也觉得左边的比右边的好看。","pinyin":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"你知道要多少钱？","pinyin":"Nǐ zhīdào yào duōshao qián?"},{"speaker":"Liú Míng (刘明)","cn":"真不便宜！八千八！","pinyin":"Zhēn bù piányi! Bāqiān bā!"}],"translation_vn":"Vương Nhất Tuyết: Anh nhìn này, hai chiếc đồng hồ này thế nào?\nLưu Minh: Đều rất đẹp!\nVương Nhất Tuyết: Em thích chiếc bên trái.\nLưu Minh: Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải.\nVương Nhất Tuyết: Anh nhìn xem bao nhiêu tiền!\nLưu Minh: Thật không rẻ! 8800 đồng!","audio_dialogue":"8-1 @xitoytili_luoluodafang.mp3","audio_vocab":"8-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"Liú Míng (刘明)","cn":"今天有不少电影，我们看个电影吧。","pinyin":"Jīntiān yǒu bù shǎo diànyǐng, wǒmen kàn gè diànyǐng ba."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"好啊！我们看哪个？","pinyin":"Hǎo a! Wǒmen kàn nǎge?"},{"speaker":"Liú Míng (刘明)","cn":"我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","pinyin":"Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","pinyin":"Háishì kàn zhège ba, wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi."},{"speaker":"Liú Míng (刘明)","cn":"好。我去买票。","pinyin":"Hǎo. Wǒ qù mǎi piào."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"到网上买吧，网上买比在这里买便宜。","pinyin":"Dào wǎngshang mǎi ba, wǎngshang mǎi bǐ zài zhèlǐ mǎi piányi."}],"translation_vn":"Lưu Minh: Hôm nay có rất nhiều phim, chúng ta đi xem phim nhé.\nVương Nhất Tuyết: Hay quá! Chúng ta xem phim nào?\nLưu Minh: Anh nhớ là em thích xem phim tình cảm, hay chúng ta xem bộ phim tình cảm kia, được không?\nVương Nhất Tuyết: Xem bộ phim này đi, em thấy trên mạng nói bộ phim này hay hơn bộ phim tình cảm đó.\nLưu Minh: Được, anh đi mua vé.\nVương Nhất Tuyết: Mua trên mạng đi à, mua trên mạng rẻ hơn mua ở đây.","audio_dialogue":"8-3 @xitoytili_luoluodafang.mp3","audio_vocab":"8-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"Liú Míng (刘明)","cn":"您好！就要这几个菜吧，谢谢！","pinyin":"Nínhǎo! Jiù yào zhè jǐ gè cài ba, xièxiè!"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"怎么点这么多菜？","pinyin":"Zěnme diǎn zhème duō cài?"},{"speaker":"Liú Míng (刘明)","cn":"你想想，今天是几月几号？","pinyin":"Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"8月27号。啊！我的生日！","pinyin":"Bā yuè èrshíqī hào. À! Wǒ de shēngrì!"},{"speaker":"Liú Míng (刘明)","cn":"生日快乐！虽然你忘了，但是我记得。看看这是什么？","pinyin":"Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"手表！吃饭、看电影、买手表，今天花了不少钱吧？","pinyin":"Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huāle bù shǎo qián ba?"},{"speaker":"Liú Míng (刘明)","cn":"虽然花了一些钱，但是我们过了一个快乐的生日。","pinyin":"Suīrán huāle yìxiē qián, dànshì wǒmen guòle yí gè kuàilè de shēngrì."}],"translation_vn":"Lưu Minh: Chào chị! Chúng tôi sẽ gọi những món này thôi, cảm ơn!\nVương Nhất Tuyết: Sao anh gọi nhiều thế?\nLưu Minh: Em nghĩ xem, hôm nay là ngày mấy tháng mấy?\nVương Nhất Tuyết: Ngày 27 tháng 8. À! Là ngày sinh nhật của em!\nLưu Minh: Chúc mừng sinh nhật! Mặc dù em quên, nhưng anh vẫn nhớ. Em nhìn xem, đây là cái gì nào?\nVương Nhất Tuyết: Đồng hồ đeo tay! Ăn cơm, xem phim, rồi còn mua đồng hồ nữa. Hôm nay anh đã tiêu tốn không ít tiền nhỉ?\nLưu Minh: Mặc dù đã tiêu một ít tiền, nhưng chúng ta đã đón một sinh nhật vui vẻ.","audio_dialogue":"8-5 @xitoytili_luoluodafang.mp3","audio_vocab":"8-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"虽然妻子忘了今天是自己的生日，但是丈夫记得。丈夫请妻子去饭馆吃饭，去电影院看电影，还给妻子买了一块非常漂亮的手表。妻子觉得今天很快乐。","pinyin":"Suīrán qīzi wàngle jīntiān shì zìjǐ de shēngrì, dànshì zhàngfū jìde. Zhàngfū qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng, hái gěi qīzi mǎile yí kuài fēicháng piàoliang de shǒubiǎo. Qīzi juéde jīntiān hěn kuàilè."}],"translation_vn":"Mặc dù người vợ quên mất hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ. Anh ấy mời vợ đi ăn ở nhà hàng, đi xem phim ở rạp chiếu phim, còn mua cho cô ấy một chiếc đồng hồ rất đẹp. Vợ cảm thấy hôm nay rất vui vẻ.","audio_dialogue":"8-7 @xitoytili_luoluodafang.mp3","audio_vocab":"8-8 @xitoytili_luoluodafang.mp3"}]},{"id":9,"title_cn":"我去买杯奶茶","title_pinyin":"Wǒ qù mǎi bēi nǎichá","title_vn":"Em đi mua một cốc trà sữa","goals":["能听懂并使用\"没有\"描述事物之间的差别。Có thể nghe hiểu và sử dụng được \"没有\" để miêu tả sự khác biệt giữa các sự vật.","掌握动词\"离\"的用法，能表达处所或时间的距离。Nắm vững cách dùng của động từ \"离\" để diễn đạt khoảng cách không gian hoặc thời gian.","掌握时量补语(1)的用法，能描述动作持续的时间。Nắm vững cách dùng của bổ ngữ thời lượng (1) để miêu tả một hành động kéo dài trong bao lâu."],"vocab":[{"hanzi":"坏","pinyin":"huài","pos":"tt.","vn":"xấu, hỏng","examples":[{"cn":"我的电脑坏了。","pinyin":"Wǒ de diànnǎo huài le.","vn":"Máy tính của tôi bị hỏng rồi."},{"cn":"他不是坏人。","pinyin":"Tā bú shì huài rén.","vn":"Anh ấy không phải người xấu."},{"cn":"这个苹果坏了。","pinyin":"Zhège píngguǒ huài le.","vn":"Quả táo này bị hỏng rồi."}]},{"hanzi":"旁边","pinyin":"pángbiān","pos":"dt.","vn":"bên cạnh","examples":[{"cn":"我家旁边有一个公园。","pinyin":"Wǒ jiā pángbiān yǒu yí ge gōngyuán.","vn":"Bên cạnh nhà tôi có một công viên."},{"cn":"请坐在我旁边。","pinyin":"Qǐng zuò zài wǒ pángbiān.","vn":"Xin ngồi bên cạnh tôi."},{"cn":"商店旁边是银行。","pinyin":"Shāngdiàn pángbiān shì yínháng.","vn":"Bên cạnh cửa hàng là ngân hàng."}]},{"hanzi":"男孩儿","pinyin":"nánháir","pos":"dt.","vn":"con trai, cậu bé","examples":[{"cn":"那个男孩儿是我弟弟。","pinyin":"Nàge nánháir shì wǒ dìdi.","vn":"Cậu bé đó là em trai tôi."},{"cn":"这个男孩儿很聪明。","pinyin":"Zhège nánháir hěn cōngming.","vn":"Cậu bé này rất thông minh."},{"cn":"男孩儿们在外面踢足球。","pinyin":"Nánháirmen zài wàimiàn tī zúqiú.","vn":"Các cậu bé đang đá bóng bên ngoài."}]},{"hanzi":"这样","pinyin":"zhèyàng","pos":"dt.","vn":"như thế này","examples":[{"cn":"你不应该这样做。","pinyin":"Nǐ bù yīnggāi zhèyàng zuò.","vn":"Bạn không nên làm như thế này."},{"cn":"这样写对吗?","pinyin":"Zhèyàng xiě duì ma?","vn":"Viết như thế này có đúng không?"},{"cn":"别这样说话。","pinyin":"Bié zhèyàng shuōhuà.","vn":"Đừng nói chuyện như thế này."}]},{"hanzi":"个子","pinyin":"gèzi","pos":"dt.","vn":"chiều cao","examples":[{"cn":"他的个子很高。","pinyin":"Tā de gèzi hěn gāo.","vn":"Anh ấy cao."},{"cn":"我哥哥个子比我高。","pinyin":"Wǒ gēge gèzi bǐ wǒ gāo.","vn":"Anh trai tôi cao hơn tôi."},{"cn":"这个男孩儿个子不高。","pinyin":"Zhège nánháir gèzi bù gāo.","vn":"Cậu bé này không cao."}]},{"hanzi":"那么","pinyin":"nàme","pos":"dt.","vn":"như thế, vậy","examples":[{"cn":"你为什么那么高兴?","pinyin":"Nǐ wèishénme nàme gāoxìng?","vn":"Sao bạn vui vậy?"},{"cn":"这个菜那么好吃。","pinyin":"Zhège cài nàme hǎochī.","vn":"Món này ngon như thế."},{"cn":"别那么说。","pinyin":"Bié nàme shuō.","vn":"Đừng nói như vậy."}]},{"hanzi":"高","pinyin":"gāo","pos":"tt.","vn":"cao","examples":[{"cn":"他个子很高。","pinyin":"Tā gèzi hěn gāo.","vn":"Anh ấy rất cao."},{"cn":"这座楼很高。","pinyin":"Zhè zuò lóu hěn gāo.","vn":"Tòa nhà này rất cao."},{"cn":"这个价钱太高了。","pinyin":"Zhège jiàqián tài gāo le.","vn":"Giá này quá cao."}]},{"hanzi":"门口","pinyin":"ménkǒu","pos":"dt.","vn":"cửa ra vào, cổng","examples":[{"cn":"我在门口等你。","pinyin":"Wǒ zài ménkǒu děng nǐ.","vn":"Tôi đợi bạn ở cửa."},{"cn":"他站在门口。","pinyin":"Tā zhàn zài ménkǒu.","vn":"Anh ấy đứng ở cửa."},{"cn":"门口有一辆自行车。","pinyin":"Ménkǒu yǒu yí liàng zìxíngchē.","vn":"Trước cửa có một chiếc xe đạp."}]},{"hanzi":"咖啡","pinyin":"kāfēi","pos":"dt.","vn":"cà phê","examples":[{"cn":"我每天早上喝一杯咖啡。","pinyin":"Wǒ měitiān zǎoshang hē yì bēi kāfēi.","vn":"Mỗi sáng tôi uống một tách cà phê."},{"cn":"你想喝咖啡还是茶?","pinyin":"Nǐ xiǎng hē kāfēi háishi chá?","vn":"Bạn muốn uống cà phê hay trà?"},{"cn":"这家店的咖啡很好喝。","pinyin":"Zhè jiā diàn de kāfēi hěn hǎohē.","vn":"Cà phê của quán này rất ngon."}]},{"hanzi":"离","pinyin":"lí","pos":"dgt.","vn":"cách, cách xa","examples":[{"cn":"我家离学校很近。","pinyin":"Wǒ jiā lí xuéxiào hěn jìn.","vn":"Nhà tôi cách trường rất gần."},{"cn":"这儿离公司远吗?","pinyin":"Zhèr lí gōngsī yuǎn ma?","vn":"Từ đây đến công ty có xa không?"},{"cn":"现在离上课还有十分钟。","pinyin":"Xiànzài lí shàngkè hái yǒu shí fēnzhōng.","vn":"Bây giờ còn mười phút nữa là đến giờ học."}]},{"hanzi":"近","pinyin":"jìn","pos":"tt.","vn":"gần","examples":[{"cn":"超市离这儿很近。","pinyin":"Chāoshì lí zhèr hěn jìn.","vn":"Siêu thị cách đây rất gần."},{"cn":"学校离我家很近。","pinyin":"Xuéxiào lí wǒ jiā hěn jìn.","vn":"Trường cách nhà tôi rất gần."},{"cn":"医院很近,走路就到了。","pinyin":"Yīyuàn hěn jìn, zǒulù jiù dào le.","vn":"Bệnh viện rất gần, đi bộ là tới."}]},{"hanzi":"走路","pinyin":"zǒulù","pos":"dgt.","vn":"đi bộ","examples":[{"cn":"我每天走路上班。","pinyin":"Wǒ měitiān zǒulù shàngbān.","vn":"Tôi đi bộ đi làm mỗi ngày."},{"cn":"从这儿到学校走路要十分钟。","pinyin":"Cóng zhèr dào xuéxiào zǒulù yào shí fēnzhōng.","vn":"Từ đây đến trường đi bộ mất mười phút."},{"cn":"他走路走得很慢。","pinyin":"Tā zǒulù zǒu de hěn màn.","vn":"Anh ấy đi bộ rất chậm."}]},{"hanzi":"周","pinyin":"zhōu","pos":"dt.","vn":"tuần","examples":[{"cn":"这周我很忙。","pinyin":"Zhè zhōu wǒ hěn máng.","vn":"Tuần này tôi rất bận."},{"cn":"下周我们去旅游。","pinyin":"Xià zhōu wǒmen qù lǚyóu.","vn":"Tuần sau chúng tôi đi du lịch."},{"cn":"一周有七天。","pinyin":"Yì zhōu yǒu qī tiān.","vn":"Một tuần có bảy ngày."}]}],"grammar":[{"title":"比较句 (3) (Câu so sánh (3))","explanation_vn":"Bài này học cách dùng \"没有\" để biểu thị câu so sánh, mang ý nghĩa \"không bằng\", \"không kịp\". Cấu trúc cơ bản: A没有B + tính từ/cụm tính từ. Trước tính từ có thể thêm \"这么\" hoặc \"那么\" để chỉ mức độ cao hơn của B. Hình thức khẳng định của \"没有\" là \"有\", thường được dùng trong câu nghi vấn so sánh.","examples":[{"cn":"儿子的个子没有他那么高。","pinyin":"Érzi de gèzi méiyǒu tā nàme gāo.","vn":""},{"cn":"昨天没有今天这么冷。","pinyin":"Zuótiān méiyǒu jīntiān zhème lěng.","vn":""},{"cn":"这块手表没有那块好看。","pinyin":"Zhè kuài shǒubiǎo méiyǒu nà kuài hǎokàn.","vn":""},{"cn":"妹妹有姐姐高吗？","pinyin":"Mèimei yǒu jiějie gāo ma?","vn":""},{"cn":"那件衣服有这件好看吗？","pinyin":"Nà jiàn yīfu yǒu zhè jiàn hǎokàn ma?","vn":""}]},{"title":"动词 \"离\" (Động từ \"离\")","explanation_vn":"Động từ \"离\" được dùng để biểu thị khoảng cách về không gian hoặc thời gian. Cấu trúc cơ bản: A 离 B……","examples":[{"cn":"咖啡店离这儿有点儿远。","pinyin":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","vn":""},{"cn":"学校离医院不远。","pinyin":"Xuéxiào lí yīyuàn bù yuǎn.","vn":""},{"cn":"现在离我的生日还有三天。","pinyin":"Xiànzài lí wǒ de shēngrì hái yǒu sān tiān.","vn":""}]},{"title":"时量补语 (1) (Bổ ngữ thời lượng (1))","explanation_vn":"Từ ngữ biểu thị khoảng thời gian được đặt sau động từ làm bổ ngữ thời lượng để miêu tả thời gian mà hành động hoặc trạng thái diễn ra. Cấu trúc cơ bản: Chủ ngữ + động từ + bổ ngữ thời lượng. Khi sau động từ có tân ngữ, vị trí tân ngữ có hai trường hợp: nếu là danh từ chỉ sự vật, thường đặt sau bổ ngữ thời lượng; nếu là từ xưng hô hoặc đại từ, thường đặt trước bổ ngữ thời lượng. Khi động từ có tân ngữ cũng có thể lặp lại động từ rồi mới thêm bổ ngữ thời lượng; nếu động từ là từ li hợp, cần lặp lại từ tố mang tính động từ trước khi thêm bổ ngữ thời lượng. Khi sau động từ có \"了\" và cuối câu cũng có trợ từ ngữ khí \"了\", điều đó biểu thị hành động vẫn đang tiếp diễn.","examples":[{"cn":"我看了一个晚上电视。","pinyin":"Wǒ kànle yí gè wǎnshang diànshì.","vn":""},{"cn":"他们学了两年。","pinyin":"Tāmen xuéle liǎng nián.","vn":""},{"cn":"我找了陈天中二十多分钟。","pinyin":"Wǒ zhǎole Chén Tiānzhōng èrshí duō fēnzhōng.","vn":""},{"cn":"他们学中文学了两年。","pinyin":"Tāmen xué Zhōngwén xuéle liǎng nián.","vn":""},{"cn":"安妮游泳游了一个下午。","pinyin":"Ānnī yóuyǒng yóule yí gè xiàwǔ.","vn":""},{"cn":"他写了半个小时汉字了。（他现在还在写汉字。）","pinyin":"Tā xiěle bàn gè xiǎoshí Hànzì le. (Tā xiànzài hái zài xiě Hànzì.)","vn":""},{"cn":"陈天中跑步跑了两个小时了。（陈天中还在跑步。）","pinyin":"Chén Tiānzhōng pǎobù pǎole liǎng gè xiǎoshí le. (Chén Tiānzhōng hái zài pǎobù.)","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"Wáng Yīxuě (王一雪)","cn":"儿子的裤子坏了，我们给他买条新的吧。","pinyin":"Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba."},{"speaker":"Liú Míng (刘明)","cn":"好啊。","pinyin":"Hǎo a."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"你看这条黑色的怎么样？","pinyin":"Nǐ kàn zhè tiáo hēisè de zěnmeyàng?"},{"speaker":"Liú Míng (刘明)","cn":"没有你上次买的那条好看。","pinyin":"Méiyǒu nǐ shàng cì mǎi de nà tiáo hǎokàn."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","pinyin":"Pángbiān nàge nánháir jiù chuānle zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!"},{"speaker":"Liú Míng (刘明)","cn":"儿子的个子没有他那么高，穿上就不会太好看。","pinyin":"Érzi de gèzi méiyǒu tā nàme gāo, chuānshang jiù bú huì tài hǎokàn."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"好吧，我们再去那边看看。","pinyin":"Hǎo ba, wǒmen zài qù nàbian kànkan."}],"translation_vn":"Vương Nhất Tuyết: Quần của con trai bị rách rồi, chúng ta mua cho con một chiếc mới đi.\nLưu Minh: Nhất trí nhé.\nVương Nhất Tuyết: Anh xem chiếc màu đen này thế nào?\nLưu Minh: Không đẹp bằng chiếc mà em đã mua lần trước.\nVương Nhất Tuyết: Cậu bé bên cạnh đang mặc kiểu quần này đấy, em thấy rất đẹp mà!\nLưu Minh: Con trai chúng ta không cao bằng cậu bé đó, mặc vào có thể không đẹp được đâu.\nVương Nhất Tuyết: Vâng, chúng ta qua bên kia xem thêm nhé.","audio_dialogue":"9-1 @xitoytili_luoluodafang.mp3","audio_vocab":"9-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"Wáng Yīxuě (王一雪)","cn":"门口有家奶茶店。你想喝杯奶茶吗？","pinyin":"Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?"},{"speaker":"Liú Míng (刘明)","cn":"我想喝咖啡，还是去咖啡店吧。","pinyin":"Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"咖啡店离这儿有点儿远。","pinyin":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn."},{"speaker":"Liú Míng (刘明)","cn":"没关系，那家店的咖啡很好喝。","pinyin":"Méi guānxi, nà jiā diàn de kāfēi hěn hǎohē."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"那你等一下，我去买杯奶茶。","pinyin":"Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá."},{"speaker":"Liú Míng (刘明)","cn":"你不想喝咖啡吗？","pinyin":"Nǐ bù xiǎng hē kāfēi ma?"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"喝了咖啡，晚上就别想睡觉了。","pinyin":"Hēle kāfēi, wǎnshang jiù bié xiǎng shuìjiào le."}],"translation_vn":"Vương Nhất Tuyết: Trước cửa có quán trà sữa. Anh có muốn uống trà sữa không?\nLưu Minh: Anh muốn uống cà phê, hay đến quán cà phê đi.\nVương Nhất Tuyết: Quán cà phê cách chỗ này hơi xa.\nLưu Minh: Không sao đâu, cà phê ở quán đó rất ngon.\nVương Nhất Tuyết: Vậy anh đợi một lát, em đi mua một cốc trà sữa.\nLưu Minh: Em không muốn uống cà phê sao?\nVương Nhất Tuyết: Uống cà phê thì buổi tối khó ngủ mất.","audio_dialogue":"9-3 @xitoytili_luoluodafang.mp3","audio_vocab":"9-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"Liú Míng (刘明)","cn":"我们打车回去吧。","pinyin":"Wǒmen dǎchē huíqù ba."},{"speaker":"Wáng Yīxuě (王一雪)","cn":"这里离家很近，还是走路吧。","pinyin":"Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba."},{"speaker":"Liú Míng (刘明)","cn":"要走多长时间？","pinyin":"Yào zǒu duō cháng shíjiān?"},{"speaker":"Wáng Yīxuě (王一雪)","cn":"走半个多小时就到了。","pinyin":"Zǒu bàn gè duō xiǎoshí jiù dào le."},{"speaker":"Liú Míng (刘明)","cn":"好的。每天上下班都坐车，今天运动运动吧。","pinyin":"Hǎo de. Měitiān shàngxià bān dōu zuò chē, jīntiān yùndòng yùndòng ba."}],"translation_vn":"Lưu Minh: Chúng ta bắt taxi về nhé.\nVương Nhất Tuyết: Chỗ này cách nhà mình rất gần, hay là đi bộ về đi.\nLưu Minh: Đi bộ mất bao lâu vậy?\nVương Nhất Tuyết: Đi bộ hơn nửa tiếng thì sẽ tới.\nLưu Minh: Được rồi. Hàng ngày anh đi làm bằng ô tô, hôm nay vận động một chút vậy.","audio_dialogue":"9-5 @xitoytili_luoluodafang.mp3","audio_vocab":"9-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"这周刘明休息，我下班后跟他去了一家商店。商店里边的衣服没有大商场里的好看。我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。因为想运动运动，所以喝完东西，我们就走回家了。","pinyin":"Zhè zhōu Liú Míng xiūxi, wǒ xiàbān hòu gēn tā qùle yì jiā shāngdiàn. Shāngdiàn lǐbian de yīfu méiyǒu dà shāngchǎng lǐ de hǎokàn. Wǒmen méiyǒu mǎidào xǐhuan de yīfu, cóng shāngdiàn chūlái jiù dào kāfēidiàn zuòle zuò. Yīnwèi xiǎng yùndòng yùndòng, suǒyǐ hēwán dōngxi, wǒmen jiù zǒuhuí jiā le."}],"translation_vn":"Tuần này, Lưu Minh được nghỉ, sau giờ làm tôi đã đi cùng anh ấy đến một cửa hàng. Quần áo trong cửa hàng đó không đẹp bằng quần áo trong trung tâm thương mại. Chúng tôi không mua được quần áo nào mình thích, vì vậy sau khi rời cửa hàng, chúng tôi đến quán cà phê ngồi một lúc. Vì muốn vận động một chút, nên sau khi uống xong cà phê chúng tôi đã đi bộ về nhà.","audio_dialogue":"9-7 @xitoytili_luoluodafang.mp3","audio_vocab":"9-8 @xitoytili_luoluodafang.mp3"}]},{"id":10,"title_cn":"就要考试了","title_pinyin":"Jiù yào kǎoshì le","title_vn":"Sắp thi rồi","goals":["能听懂并使用主谓谓语句对人、事物或情况进行说明。Có thể nghe hiểu và sử dụng được câu có cụm chủ vị làm vị ngữ để miêu tả người, sự vật hoặc tình huống.","能听懂并使用选择问句表示疑问。Có thể nghe hiểu và sử dụng được câu hỏi lựa chọn để biểu thị nghi vấn.","掌握固定格式“要/快/快要/就要……了”的用法,能表达某事即将发生。Nắm vững cách dùng của cấu trúc cố định “要/快/快要/就要……了” để diễn đạt một việc nào đó sắp xảy ra."],"vocab":[{"hanzi":"开学","pinyin":"kāixué","pos":"dgt.","vn":"khai giảng","examples":[{"cn":"我们九月一号开学。","pinyin":"Wǒmen jiǔyuè yī hào kāixué.","vn":"Chúng tôi khai giảng vào ngày 1 tháng 9."},{"cn":"快开学了，你准备好了吗？","pinyin":"Kuài kāixué le, nǐ zhǔnbèi hǎo le ma?","vn":"Sắp khai giảng rồi, bạn chuẩn bị xong chưa?"},{"cn":"开学以后我每天都很忙。","pinyin":"Kāixué yǐhòu wǒ měitiān dōu hěn máng.","vn":"Sau khi khai giảng ngày nào tôi cũng rất bận."}]},{"hanzi":"门","pinyin":"mén","pos":"dt.","vn":"cửa","examples":[{"cn":"请把门关上。","pinyin":"Qǐng bǎ mén guānshàng.","vn":"Làm ơn đóng cửa lại."},{"cn":"门外有一个人。","pinyin":"Mén wài yǒu yí gè rén.","vn":"Bên ngoài cửa có một người."},{"cn":"他开门进来了。","pinyin":"Tā kāi mén jìnlái le.","vn":"Anh ấy mở cửa đi vào."}]},{"hanzi":"后面","pinyin":"hòumiàn","pos":"dt.","vn":"phía sau, đằng sau","examples":[{"cn":"我坐在他后面。","pinyin":"Wǒ zuò zài tā hòumiàn.","vn":"Tôi ngồi ở phía sau anh ấy."},{"cn":"后面有一只小猫。","pinyin":"Hòumiàn yǒu yì zhī xiǎo māo.","vn":"Phía sau có một con mèo con."},{"cn":"学校后面有一个公园。","pinyin":"Xuéxiào hòumiàn yǒu yí gè gōngyuán.","vn":"Phía sau trường học có một công viên."}]},{"hanzi":"笔","pinyin":"bǐ","pos":"dt.","vn":"bút, viết","examples":[{"cn":"这是我的笔。","pinyin":"Zhè shì wǒ de bǐ.","vn":"Đây là bút của tôi."},{"cn":"你能借我一支笔吗？","pinyin":"Nǐ néng jiè wǒ yì zhī bǐ ma?","vn":"Bạn có thể cho tôi mượn một cây bút không?"},{"cn":"我忘了带笔。","pinyin":"Wǒ wàng le dài bǐ.","vn":"Tôi quên mang bút rồi."}]},{"hanzi":"帮","pinyin":"bāng","pos":"dgt.","vn":"giúp, giúp đỡ","examples":[{"cn":"你能帮我一下吗？","pinyin":"Nǐ néng bāng wǒ yíxià ma?","vn":"Bạn có thể giúp tôi một chút không?"},{"cn":"我帮妈妈做饭。","pinyin":"Wǒ bāng māma zuò fàn.","vn":"Tôi giúp mẹ nấu cơm."},{"cn":"谢谢你帮我找到钥匙。","pinyin":"Xièxie nǐ bāng wǒ zhǎodào yàoshi.","vn":"Cảm ơn bạn đã giúp tôi tìm thấy chìa khóa."}]},{"hanzi":"考试","pinyin":"kǎoshì","pos":"dgt./dt.","vn":"thi, kiểm tra, kỳ thi","examples":[{"cn":"明天我们有考试。","pinyin":"Míngtiān wǒmen yǒu kǎoshì.","vn":"Ngày mai chúng tôi có thi."},{"cn":"这次考试很难。","pinyin":"Zhè cì kǎoshì hěn nán.","vn":"Kỳ thi lần này rất khó."},{"cn":"我正在准备考试。","pinyin":"Wǒ zhèngzài zhǔnbèi kǎoshì.","vn":"Tôi đang chuẩn bị cho kỳ thi."}]},{"hanzi":"词","pinyin":"cí","pos":"dt.","vn":"từ","examples":[{"cn":"这个词是什么意思？","pinyin":"Zhège cí shì shénme yìsi?","vn":"Từ này nghĩa là gì?"},{"cn":"我每天学十个新词。","pinyin":"Wǒ měitiān xué shí gè xīn cí.","vn":"Mỗi ngày tôi học mười từ mới."},{"cn":"这个词我不认识。","pinyin":"Zhège cí wǒ bú rènshi.","vn":"Từ này tôi không biết."}]},{"hanzi":"本子","pinyin":"běnzi","pos":"dt.","vn":"vở, tập ghi chép","examples":[{"cn":"我的本子在桌子上。","pinyin":"Wǒ de běnzi zài zhuōzi shàng.","vn":"Vở của tôi ở trên bàn."},{"cn":"请把本子拿出来。","pinyin":"Qǐng bǎ běnzi ná chūlái.","vn":"Hãy lấy vở ra."},{"cn":"他买了一个新本子。","pinyin":"Tā mǎi le yí gè xīn běnzi.","vn":"Anh ấy mua một quyển vở mới."}]},{"hanzi":"错","pinyin":"cuò","pos":"tt.","vn":"sai, nhầm","examples":[{"cn":"你写错了。","pinyin":"Nǐ xiě cuò le.","vn":"Bạn viết sai rồi."},{"cn":"这个答案是错的。","pinyin":"Zhège dá'àn shì cuò de.","vn":"Câu trả lời này sai rồi."},{"cn":"对不起，我说错了。","pinyin":"Duìbuqǐ, wǒ shuō cuò le.","vn":"Xin lỗi, tôi nói sai rồi."}]},{"hanzi":"题","pinyin":"tí","pos":"dt.","vn":"câu hỏi, bài tập, đề, tiêu đề","examples":[{"cn":"这道题很难。","pinyin":"Zhè dào tí hěn nán.","vn":"Bài tập này rất khó."},{"cn":"老师出了十道题。","pinyin":"Lǎoshī chū le shí dào tí.","vn":"Giáo viên ra mười câu hỏi."},{"cn":"我做完所有的题了。","pinyin":"Wǒ zuò wán suǒyǒu de tí le.","vn":"Tôi đã làm xong hết các bài tập."}]},{"hanzi":"还是","pinyin":"háishi","pos":"lh.","vn":"hay là (trong câu hỏi lựa chọn)","examples":[{"cn":"你喝茶还是喝咖啡？","pinyin":"Nǐ hē chá háishi hē kāfēi?","vn":"Bạn uống trà hay là cà phê?"},{"cn":"我们今天去还是明天去？","pinyin":"Wǒmen jīntiān qù háishi míngtiān qù?","vn":"Chúng ta đi hôm nay hay là mai?"},{"cn":"你喜欢红色还是白色？","pinyin":"Nǐ xǐhuan hóngsè háishi báisè?","vn":"Bạn thích màu đỏ hay là màu trắng?"}]},{"hanzi":"考","pinyin":"kǎo","pos":"dgt.","vn":"thi, kiểm tra","examples":[{"cn":"明天考汉语。","pinyin":"Míngtiān kǎo Hànyǔ.","vn":"Ngày mai thi tiếng Hán."},{"cn":"他考得很好。","pinyin":"Tā kǎo de hěn hǎo.","vn":"Anh ấy thi rất tốt."},{"cn":"我们这个星期考数学。","pinyin":"Wǒmen zhège xīngqī kǎo shùxué.","vn":"Tuần này chúng tôi thi Toán."}]},{"hanzi":"快要","pinyin":"kuàiyào","pos":"phó.","vn":"sắp, chuẩn bị","examples":[{"cn":"快要下雨了。","pinyin":"Kuàiyào xiàyǔ le.","vn":"Sắp mưa rồi."},{"cn":"快要到家了。","pinyin":"Kuàiyào dào jiā le.","vn":"Sắp về đến nhà rồi."},{"cn":"他快要毕业了。","pinyin":"Tā kuàiyào bìyè le.","vn":"Anh ấy sắp tốt nghiệp rồi."}]},{"hanzi":"笑","pinyin":"xiào","pos":"dgt.","vn":"cười","examples":[{"cn":"他笑得很开心。","pinyin":"Tā xiào de hěn kāixīn.","vn":"Anh ấy cười rất vui vẻ."},{"cn":"别笑我。","pinyin":"Bié xiào wǒ.","vn":"Đừng cười tôi."},{"cn":"她看着照片笑了。","pinyin":"Tā kànzhe zhàopiàn xiào le.","vn":"Cô ấy nhìn tấm ảnh và cười."}]}],"grammar":[{"title":"主谓谓语句 Câu có cụm chủ vị làm vị ngữ","explanation_vn":"主谓短语可以作谓语,对主语加以说明或描写,构成主谓谓语句。一般来说,主谓短语中的主语是全句主语的一部分或跟它相关。基本结构:主语+主谓短语。 Cụm chủ vị có thể làm vị ngữ để giải thích hoặc miêu tả chủ ngữ, từ đó tạo thành câu có cụm chủ vị làm vị ngữ. Thông thường, chủ ngữ trong cụm chủ vị hoặc là một phần của chủ ngữ của cả câu, hoặc có liên quan đến nó. Cấu trúc cơ bản: Chủ ngữ + cụm chủ vị.","examples":[{"cn":"我的书包你看见了吗?","pinyin":"","vn":""},{"cn":"弟弟手很小。","pinyin":"","vn":""},{"cn":"这件事他知道。","pinyin":"","vn":""}]},{"title":"选择问句 Câu hỏi lựa chọn","explanation_vn":"连词“还是”用在疑问句中,表示选择。基本结构:(是)A还是B。 Liên từ “还是” dùng trong câu nghi vấn, chỉ sự lựa chọn. Cấu trúc cơ bản: (是)A还是B.","examples":[{"cn":"妈妈,是您准备考试还是我准备考试?","pinyin":"","vn":""},{"cn":"你更喜欢打篮球,踢足球还是游泳?","pinyin":"","vn":""},{"cn":"我们什么时候去看电影?今天还是明天?","pinyin":"","vn":""}]},{"title":"固定格式“要/快/快要/就要……了”","explanation_vn":"固定格式“要/快/快要/就要……了”表示某事将要发生。如果句子中有时间语,一般用“就要……了”。 Cấu trúc cố định “要/快/快要/就要……了” dùng để biểu thị một việc sắp xảy ra. Nếu trong câu có thêm trạng ngữ chỉ thời gian thì hay dùng “就要……了”.","examples":[{"cn":"饭菜快要做好了。","pinyin":"","vn":""},{"cn":"火车快开了。","pinyin":"","vn":""},{"cn":"我们下星期就要考试了。","pinyin":"","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明 (Lưu Minh)","cn":"小明,你们明天开学,你准备好了吗?","pinyin":"Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?"},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"明天就开学吗?爸爸,我的书包你看见了吗?","pinyin":"Míngtiān jiù kāixué ma? Bàba, wǒ de shūbāo nǐ kànjiàn le ma?"},{"speaker":"刘明 (Lưu Minh)","cn":"书包在门后面。","pinyin":"Shūbāo zài mén hòumiàn."},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"书在哪儿呢?笔呢?","pinyin":"Shū zài nǎr ne? Bǐ ne?"},{"speaker":"刘明 (Lưu Minh)","cn":"书在床上,笔在桌子上。","pinyin":"Shū zài chuáng shang, bǐ zài zhuōzi shang."},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"太好了!现在都准备好了。","pinyin":"Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le."},{"speaker":"刘明 (Lưu Minh)","cn":"这次爸爸帮你,下次你自己准备,好不好?","pinyin":"Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?"},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"好!","pinyin":"Hǎo!"}],"translation_vn":"Lưu Minh: Tiểu Minh, ngày mai khai giảng rồi, con đã chuẩn bị xong chưa? Lưu Tiểu Minh: Ngày mai khai giảng à? Bố ơi, bố có thấy cặp sách của con không? Lưu Minh: Nó ở phía sau cửa. Lưu Tiểu Minh: Sách ở đâu ạ? Cả bút nữa? Lưu Minh: Sách ở trên giường, bút ở trên bàn. Lưu Tiểu Minh: May quá! Bây giờ đã chuẩn bị xong rồi. Lưu Minh: Lần này, bố đã giúp con. Lần sau con phải tự chuẩn bị, được không? Lưu Tiểu Minh: Vâng ạ!","audio_dialogue":"10-1 @xitoytili_luoluodafang.mp3","audio_vocab":"10-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"小雪,你在做什么呢?","pinyin":"Xiǎoxuě, nǐ zài zuò shénme ne?"},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"明天考试,我在看书呢。","pinyin":"Míngtiān kǎoshì, wǒ zài kàn shū ne."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"这些词要好好看看。","pinyin":"Zhèxiē cí yào hǎohāo kànkan."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"我看过了,意思也都懂了。","pinyin":"Wǒ kànguò le, yìsi yě dōu dǒng le."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"你的本子呢?本子上做错的题也要再看看。","pinyin":"Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào zài kànkan."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"妈妈,是您准备考试还是我准备考试呀?","pinyin":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì ya?"}],"translation_vn":"Vương Nhất Tuyết: Tiểu Tuyết, con đang làm gì vậy? Lưu Tiểu Tuyết: Ngày mai con thi, nên con đang học bài. Vương Nhất Tuyết: Con nên xem lại những từ này thật kỹ nhé. Lưu Tiểu Tuyết: Con xem rồi, cũng đã hiểu hết nghĩa của chúng rồi. Vương Nhất Tuyết: Thế còn vở của con đâu? Những câu làm sai trong vở cũng cần xem lại. Lưu Tiểu Tuyết: Mẹ ơi, là mẹ chuẩn bị thi hay là con chuẩn bị thi vậy?","audio_dialogue":"10-3 @xitoytili_luoluodafang.mp3","audio_vocab":"10-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"妈妈,我回来了!","pinyin":"Māma, wǒ huílai le!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"我买了奶茶,就在桌子上,自己去拿吧。","pinyin":"Wǒ mǎile nǎichá, jiù zài zhuōzi shang, zìjǐ qù ná ba."},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"谢谢妈妈!","pinyin":"Xièxie māma!"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"今天考试考得怎么样?","pinyin":"Jīntiān kǎoshì kǎo de zěnmeyàng?"},{"speaker":"刘小雪 (Lưu Tiểu Tuyết)","cn":"我觉得比上次好。","pinyin":"Wǒ juéde bǐ shàng cì hǎo."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"真不错!饭菜快要做好了,你叫弟弟一起去洗手吧。","pinyin":"Zhēn búcuò! Fàncài kuàiyào zuòhǎo le, nǐ jiào dìdi yìqǐ qù xǐshǒu ba."},{"speaker":"刘小明 (Lưu Tiểu Minh)","cn":"妈妈,我是第一名,姐姐还没洗完呢。","pinyin":"Māma, wǒ shì dì-yī míng, jiějie hái méi xǐwán ne."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"你洗得真快啊!","pinyin":"Nǐ xǐ de zhēn kuài a!"}],"translation_vn":"Lưu Tiểu Tuyết: Mẹ ơi, con về rồi! Vương Nhất Tuyết: Mẹ đã mua trà sữa, để ngay trên bàn, con tự đi lấy nhé. Lưu Tiểu Tuyết: Cảm ơn mẹ! Vương Nhất Tuyết: Hôm nay con thi thế nào? Lưu Tiểu Tuyết: Con thấy tốt hơn lần trước. Vương Nhất Tuyết: Thật tuyệt! Cơm sắp nấu xong rồi, con gọi em trai cùng đi rửa tay nhé. Lưu Tiểu Minh: Mẹ ơi, con xong nhanh nhất, chị vẫn chưa rửa tay xong. Vương Nhất Tuyết: Con rửa tay nhanh thật đấy!","audio_dialogue":"10-5 @xitoytili_luoluodafang.mp3","audio_vocab":"10-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"快要开学了,爸爸帮弟弟准备书包、本子和笔。我就要考试了,妈妈让我看书、看做错的题。我们上学,爸爸、妈妈比我们还忙。我问他们:“是我和弟弟上学还是你们上学?”我问完,他们都笑了。","pinyin":"Kuàiyào kāixué le, bàba bāng dìdi zhǔnbèi shūbāo, běnzi hé bǐ. Wǒ jiù yào kǎoshì le, māma ràng wǒ kàn shū, kàn zuòcuò de tí. Wǒmen shàngxué, bàba, māma bǐ wǒmen hái máng. Wǒ wèn tāmen: “Shì wǒ hé dìdi shàngxué háishi nǐmen shàngxué?” Wǒ wènwán, tāmen dōu xiào le."}],"translation_vn":"Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút. Tôi sắp thi, mẹ bảo tôi học bài và xem lại những câu làm sai. Chúng tôi đi học, nhưng bố mẹ còn bận hơn cả chúng tôi. Tôi hỏi bố mẹ rằng: “Là em trai và con đi học hay là bố mẹ đi học vậy?” Tôi hỏi xong, cả nhà đều bật cười.","audio_dialogue":"10-7 @xitoytili_luoluodafang.mp3","audio_vocab":"10-8 @xitoytili_luoluodafang.mp3"}]},{"id":11,"title_cn":"我最喜欢吃中国菜","title_pinyin":"Wǒ zuì xǐhuan chī Zhōngguó cài","title_vn":"Em thích ăn món Trung Quốc nhất","goals":["能听懂并描述身体状况和病情。Có thể nghe hiểu và miêu tả được tình trạng sức khoẻ.","能听懂并使用动态助词“着”表达动作或状态的持续。Có thể nghe hiểu và sử dụng được trợ từ động thái “着” để diễn đạt sự duy trì của động tác hoặc trạng thái.","掌握程度副词“最”的用法,能表达某种属性超过所有同类的人或事物。Nắm vững cách dùng của phó từ chỉ mức độ “最” để diễn đạt một thuộc tính nào đó vượt trội hơn tất cả mọi người hoặc sự vật cùng loại."],"vocab":[{"hanzi":"头","pinyin":"tóu","pos":"dt.","vn":"đầu","examples":[{"cn":"我头很疼。","pinyin":"Wǒ tóu hěn téng.","vn":"Đầu tôi rất đau."},{"cn":"他摸了摸头。","pinyin":"Tā mō le mō tóu.","vn":"Anh ấy sờ sờ đầu."},{"cn":"小狗的头很大。","pinyin":"Xiǎogǒu de tóu hěn dà.","vn":"Đầu con chó con rất to."}]},{"hanzi":"疼","pinyin":"téng","pos":"tt.","vn":"đau, nhức","examples":[{"cn":"我肚子疼。","pinyin":"Wǒ dùzi téng.","vn":"Bụng tôi đau."},{"cn":"牙疼真难受。","pinyin":"Yá téng zhēn nánshòu.","vn":"Đau răng thật khó chịu."},{"cn":"昨天脚疼，今天好多了。","pinyin":"Zuótiān jiǎo téng, jīntiān hǎo duō le.","vn":"Hôm qua chân đau, hôm nay đỡ nhiều rồi."}]},{"hanzi":"经常","pinyin":"jīngcháng","pos":"phó.","vn":"thường xuyên","examples":[{"cn":"我经常去那家饭馆。","pinyin":"Wǒ jīngcháng qù nà jiā fànguǎn.","vn":"Tôi thường xuyên đến quán ăn đó."},{"cn":"他经常迟到。","pinyin":"Tā jīngcháng chídào.","vn":"Anh ấy thường xuyên đến muộn."},{"cn":"我们经常一起学习。","pinyin":"Wǒmen jīngcháng yìqǐ xuéxí.","vn":"Chúng tôi thường xuyên học cùng nhau."}]},{"hanzi":"动","pinyin":"dòng","pos":"đgt.","vn":"di chuyển, cử động","examples":[{"cn":"别动！","pinyin":"Bié dòng!","vn":"Đừng động đậy!"},{"cn":"这把椅子动不了。","pinyin":"Zhè bǎ yǐzi dòng bu liǎo.","vn":"Cái ghế này không di chuyển được."},{"cn":"他一动也不动地坐着。","pinyin":"Tā yí dòng yě bú dòng de zuòzhe.","vn":"Anh ấy ngồi bất động không nhúc nhích."}]},{"hanzi":"着","pinyin":"zhe","pos":"trợ.","vn":"đặt sau động từ hoặc tính từ để chỉ sự duy trì của động tác hoặc trạng thái","examples":[{"cn":"门开着呢。","pinyin":"Mén kāizhe ne.","vn":"Cửa đang mở đấy."},{"cn":"她手里拿着一本书。","pinyin":"Tā shǒu lǐ názhe yì běn shū.","vn":"Tay cô ấy đang cầm một quyển sách."},{"cn":"他笑着跟我说话。","pinyin":"Tā xiàozhe gēn wǒ shuōhuà.","vn":"Anh ấy vừa cười vừa nói chuyện với tôi."}]},{"hanzi":"路上","pinyin":"lùshang","pos":"dt.","vn":"trên đường","examples":[{"cn":"路上小心。","pinyin":"Lùshang xiǎoxīn.","vn":"Trên đường cẩn thận nhé."},{"cn":"我在路上看见了他。","pinyin":"Wǒ zài lùshang kànjiàn le tā.","vn":"Tôi nhìn thấy anh ấy trên đường."},{"cn":"路上车很多。","pinyin":"Lùshang chē hěn duō.","vn":"Trên đường có rất nhiều xe."}]},{"hanzi":"慢","pinyin":"màn","pos":"tt.","vn":"chậm","examples":[{"cn":"你说慢一点儿。","pinyin":"Nǐ shuō màn yìdiǎnr.","vn":"Bạn nói chậm một chút."},{"cn":"这辆车开得很慢。","pinyin":"Zhè liàng chē kāi de hěn màn.","vn":"Chiếc xe này chạy rất chậm."},{"cn":"他走路很慢。","pinyin":"Tā zǒulù hěn màn.","vn":"Anh ấy đi bộ rất chậm."}]},{"hanzi":"进","pinyin":"jìn","pos":"đgt.","vn":"vào","examples":[{"cn":"请进。","pinyin":"Qǐng jìn.","vn":"Mời vào."},{"cn":"他走进了教室。","pinyin":"Tā zǒu jìn le jiàoshì.","vn":"Anh ấy bước vào lớp học."},{"cn":"外面冷，快进来吧。","pinyin":"Wàimiàn lěng, kuài jìnlái ba.","vn":"Bên ngoài lạnh, vào nhanh đi."}]},{"hanzi":"药","pinyin":"yào","pos":"dt.","vn":"thuốc","examples":[{"cn":"你吃药了吗？","pinyin":"Nǐ chī yào le ma?","vn":"Bạn uống thuốc chưa?"},{"cn":"医生给我开了药。","pinyin":"Yīshēng gěi wǒ kāi le yào.","vn":"Bác sĩ kê thuốc cho tôi."},{"cn":"这个药很苦。","pinyin":"Zhège yào hěn kǔ.","vn":"Thuốc này rất đắng."}]},{"hanzi":"身体","pinyin":"shēntǐ","pos":"dt.","vn":"cơ thể, sức khoẻ","examples":[{"cn":"你身体怎么样？","pinyin":"Nǐ shēntǐ zěnmeyàng?","vn":"Sức khỏe bạn thế nào?"},{"cn":"多运动对身体好。","pinyin":"Duō yùndòng duì shēntǐ hǎo.","vn":"Vận động nhiều tốt cho sức khỏe."},{"cn":"他身体很健康。","pinyin":"Tā shēntǐ hěn jiànkāng.","vn":"Sức khỏe anh ấy rất tốt."}]},{"hanzi":"时","pinyin":"shí","pos":"dt.","vn":"khi, lúc","examples":[{"cn":"吃饭时请别说话。","pinyin":"Chīfàn shí qǐng bié shuōhuà.","vn":"Lúc ăn cơm xin đừng nói chuyện."},{"cn":"上课时我们要认真听。","pinyin":"Shàngkè shí wǒmen yào rènzhēn tīng.","vn":"Lúc học bài chúng ta phải nghe nghiêm túc."},{"cn":"困难时朋友最重要。","pinyin":"Kùnnán shí péngyou zuì zhòngyào.","vn":"Lúc khó khăn bạn bè là quan trọng nhất."}]},{"hanzi":"最","pinyin":"zuì","pos":"phó.","vn":"nhất","examples":[{"cn":"他是我最好的朋友。","pinyin":"Tā shì wǒ zuì hǎo de péngyou.","vn":"Anh ấy là người bạn tốt nhất của tôi."},{"cn":"这是我最喜欢的歌。","pinyin":"Zhè shì wǒ zuì xǐhuan de gē.","vn":"Đây là bài hát tôi thích nhất."},{"cn":"今天是最冷的一天。","pinyin":"Jīntiān shì zuì lěng de yì tiān.","vn":"Hôm nay là ngày lạnh nhất."}]},{"hanzi":"药店","pinyin":"yàodiàn","pos":"dt.","vn":"hiệu thuốc, nhà thuốc","examples":[{"cn":"附近有药店吗？","pinyin":"Fùjìn yǒu yàodiàn ma?","vn":"Gần đây có hiệu thuốc không?"},{"cn":"我去药店买药。","pinyin":"Wǒ qù yàodiàn mǎi yào.","vn":"Tôi đi hiệu thuốc mua thuốc."},{"cn":"药店已经关门了。","pinyin":"Yàodiàn yǐjīng guānmén le.","vn":"Hiệu thuốc đã đóng cửa rồi."}]}],"grammar":[{"title":"动态助词“着”(1) Trợ từ động thái “着” (1)","explanation_vn":"动态助词“着”用在动词后面,表示动作或状态的持续。否定形式是在动词前面加“没(有)”。 Trợ từ động thái “着” đặt sau động từ, biểu thị sự duy trì của động tác hoặc trạng thái. Hình thức phủ định là thêm “没(有)” vào trước động từ.","examples":[{"cn":"那你在这儿坐着。","pinyin":"","vn":""},{"cn":"教室的门开着。","pinyin":"","vn":""},{"cn":"教室的门没开着。","pinyin":"","vn":""}]},{"title":"动态助词“着”(2) Trợ từ động thái “着” (2)","explanation_vn":"表示动作或状态持续的句子中,宾语要在动态助词“着”的后面。疑问形式有三种:(1)在句尾加“吗”;(2)在句尾加“没有”;(3)动词+没+动词+着。 Trong câu biểu thị sự duy trì của động tác hoặc trạng thái, tân ngữ phải đứng sau trợ từ động thái “着”. Hình thức nghi vấn có ba loại: (1) thêm “吗” vào cuối câu; (2) thêm “没有” vào cuối câu; (3) động từ + 没 + động từ + 着.","examples":[{"cn":"现在路上车多,还下着雪,我开慢一点儿。","pinyin":"","vn":""},{"cn":"她穿着白色的裤子。","pinyin":"","vn":""},{"cn":"陈天中没拿着咖啡。","pinyin":"","vn":""},{"cn":"教室的门开着吗?","pinyin":"","vn":""},{"cn":"白家月坐着没有?","pinyin":"","vn":""},{"cn":"她拿没拿着手机?","pinyin":"","vn":""}]},{"title":"程度副词“最” Phó từ chỉ mức độ “最”","explanation_vn":"程度副词“最”用在形容词或心理动词前面,表示某种属性超过所有同类的人或事物。 Phó từ chỉ mức độ “最” đặt trước tính từ hoặc động từ chỉ tâm lý, biểu thị một đặc tính nào đó vượt trội hơn tất cả mọi người hoặc sự vật cùng loại.","examples":[{"cn":"你最喜欢吃中国菜。","pinyin":"","vn":""},{"cn":"在我们家,爸爸最高。","pinyin":"","vn":""},{"cn":"你们班谁说中文说得最好?","pinyin":"","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一飞 (Vương Nhất Phi)","cn":"家月,都下课了,你怎么还不回家?","pinyin":"Jiāyuè, dōu xiàkè le, nǐ zěnme hái bù huí jiā?"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"我头疼,不太舒服。","pinyin":"Wǒ tóu téng, bú tài shūfu."},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"你这几天经常头疼,去医院看看吧。","pinyin":"Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"我想休息一下,现在不能动,一动就疼。","pinyin":"Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng."},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"那你在这儿坐着,我去开车,一会儿送你去医院。","pinyin":"Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yìhuǐr sòng nǐ qù yīyuàn."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"谢谢王老师。","pinyin":"Xièxie Wáng lǎoshī."}],"translation_vn":"Vương Nhất Phi: Gia Nguyệt, đã tan học rồi, sao em vẫn chưa về nhà? Bạch Gia Nguyệt: Em bị đau đầu, không được khỏe lắm. Vương Nhất Phi: Mấy ngày nay em thường xuyên đau đầu, hay là đi bệnh viện khám thử xem. Bạch Gia Nguyệt: Em muốn nghỉ ngơi một lát, bây giờ không cử động được, cứ di cử là đau. Vương Nhất Phi: Vậy em cứ ngồi ở đây nhé, cô đi lấy xe, lát nữa sẽ đưa em đến bệnh viện. Bạch Gia Nguyệt: Cảm ơn cô Vương ạ.","audio_dialogue":"11-1 @xitoytili_luoluodafang.mp3","audio_vocab":"11-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞 (Vương Nhất Phi)","cn":"现在路上车多,还下着雪,我开慢一点儿。","pinyin":"Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"没问题,现在头没那么疼了。","pinyin":"Méi wèntí, xiànzài tóu méi nàme téng le."},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"好。李文来电话了,你帮我接一下。","pinyin":"Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"喂,李文。王老师开着车呢。你找他有事吗?","pinyin":"Wéi, Lǐ Wén. Wáng lǎoshī kāizhe chē ne. Nǐ zhǎo tā yǒu shì ma?"},{"speaker":"李文 (Lý Văn)","cn":"没什么事。今天雪这么大,你们开车去哪儿啊?","pinyin":"Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"去医院。我头有点儿疼。","pinyin":"Qù yīyuàn. Wǒ tóu yǒudiǎnr téng."},{"speaker":"李文 (Lý Văn)","cn":"那我一会儿去看看你。","pinyin":"Nà wǒ yíhuìr qù kànkan nǐ."}],"translation_vn":"Vương Nhất Phi: Bây giờ rất nhiều xe cộ trên đường, lại còn đang có tuyết rơi nên cô lái chậm một chút. Bạch Gia Nguyệt: Không sao đâu ạ, bây giờ đầu em không còn đau như vừa nãy nữa rồi. Vương Nhất Phi: Được rồi. Lý Văn gọi điện thoại đến kìa, em nghe máy hộ cô một chút. Bạch Gia Nguyệt: A lô, Lý Văn à, cô Vương đang lái xe, bạn tìm cô có việc gì không? Lý Văn: Không có việc gì quan trọng. Hôm nay tuyết rơi dày thế này, hai người có đi đâu vậy? Bạch Gia Nguyệt: Đi bệnh viện, mình hơi đau đầu. Lý Văn: Vậy lát nữa mình sẽ đi thăm bạn.","audio_dialogue":"11-3 @xitoytili_luoluodafang.mp3","audio_vocab":"11-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"李文,快请进!","pinyin":"Lǐ Wén, kuài qǐng jìn!"},{"speaker":"李文 (Lý Văn)","cn":"家月,你怎么样了?头还疼吗?","pinyin":"Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"不那么疼了。医生开了一些药,吃完就好多了。","pinyin":"Bú nàme téng le. Yīshēng kāile yìxiē yào, chīwán jiù hǎoduō le."},{"speaker":"李文 (Lý Văn)","cn":"那就好!","pinyin":"Nà jiù hǎo!"},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"家月,你想不想吃点儿东西?","pinyin":"Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?"},{"speaker":"李文 (Lý Văn)","cn":"吃点儿吧,身体不舒服时更要好好吃饭。","pinyin":"Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎohāo chī fàn."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"吃点儿什么呢?","pinyin":"Chī diǎnr shénme ne?"},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"你最喜欢吃中国菜,我做几个中国菜吧。","pinyin":"Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ ge Zhōngguó cài ba."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"好的,谢谢王老师。","pinyin":"Hǎo de, xièxie Wáng lǎoshī."}],"translation_vn":"Bạch Gia Nguyệt: Lý Văn, mau vào đi! Lý Văn: Gia Nguyệt, bạn thế nào rồi? Còn đau đầu không? Bạch Gia Nguyệt: Không đau như trước nữa rồi. Bác sĩ đã kê một ít thuốc, uống xong thấy khoẻ hơn nhiều rồi. Lý Văn: Vậy thì tốt rồi! Vương Nhất Phi: Gia Nguyệt, em có muốn ăn chút gì không? Lý Văn: Ăn một chút đi, khi cơ thể không khoẻ thì càng phải ăn uống đầy đủ. Bạch Gia Nguyệt: Ăn chút gì bây giờ? Vương Nhất Phi: Em thích ăn món Trung Quốc nhất, cô sẽ nấu mấy món Trung Quốc nhé. Bạch Gia Nguyệt: Vâng ạ, cám ơn cô Vương.","audio_dialogue":"11-5 @xitoytili_luoluodafang.mp3","audio_vocab":"11-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我这几天经常头疼,从药店买了点儿药,没去医院。今天下课后,王老师看我不舒服,就送我去医院。从医院回来,李文也来看我了。现在他们都回去了,我也要睡觉了。","pinyin":"Wǒ zhè jǐ tiān jīngcháng tóuténg, cóng yàodiàn mǎile diǎnr yào, méi qù yīyuàn. Jīntiān xiàkè hòu, Wáng lǎoshī kàn wǒ bù shūfu, jiù sòng wǒ qù yīyuàn le. Cóng yīyuàn huílai, Lǐ Wén yě lái kàn wǒ le. Xiànzài tāmen dōu huíqù le, wǒ yě yào shuìjiào le."}],"translation_vn":"Mấy ngày nay tôi thường xuyên bị đau đầu, đã mua một ít thuốc từ hiệu thuốc về mà không đi bệnh viện. Hôm nay sau khi tan học, cô Vương thấy tôi không được khoẻ nên đã đưa tôi đến bệnh viện. Sau khi từ bệnh viện về, Lý Văn cũng đến thăm tôi. Bây giờ họ đều về cả rồi, tôi cũng phải đi ngủ đây.","audio_dialogue":"11-7 @xitoytili_luoluodafang.mp3","audio_vocab":"11-8 @xitoytili_luoluodafang.mp3"}]},{"id":12,"title_cn":"这里比北京冷多了","title_pinyin":"Zhèlǐ bǐ Běijīng lěng duō le","title_vn":"Ở đây lạnh hơn Bắc Kinh nhiều","goals":["能听懂并谈论天气情况。Có thể nghe hiểu và thảo luận được tình hình thời tiết.","能听懂并描述动作状态之间的差别。Có thể nghe hiểu và miêu tả được sự khác biệt giữa các trạng thái của động tác.","掌握比较句的用法,能说明事物之间的差别很大。Nắm vững cách dùng của câu so sánh để nói rõ sự khác biệt lớn giữa các sự vật."],"vocab":[{"hanzi":"事情","pinyin":"shìqing","pos":"dt.","vn":"sự việc, việc","examples":[{"cn":"今天我有很多事情要做。","pinyin":"Jīntiān wǒ yǒu hěn duō shìqing yào zuò.","vn":"Hôm nay tôi có nhiều việc phải làm."},{"cn":"发生了什么事情？","pinyin":"Fāshēng le shénme shìqing?","vn":"Đã xảy ra chuyện gì vậy?"},{"cn":"这件事情很重要。","pinyin":"Zhè jiàn shìqing hěn zhòngyào.","vn":"Việc này rất quan trọng."}]},{"hanzi":"晴","pinyin":"qíng","pos":"tt.","vn":"nắng, tạnh ráo, quang đãng","examples":[{"cn":"今天天气很晴。","pinyin":"Jīntiān tiānqì hěn qíng.","vn":"Hôm nay trời rất nắng."},{"cn":"明天是晴天。","pinyin":"Míngtiān shì qíngtiān.","vn":"Mai là ngày nắng."},{"cn":"雨后天晴了。","pinyin":"Yǔ hòu tiān qíng le.","vn":"Sau mưa trời đã tạnh."}]},{"hanzi":"正","pinyin":"zhèng","pos":"phó.","vn":"đang (chỉ hành động hoặc trạng thái đang diễn ra)","examples":[{"cn":"我正在吃饭。","pinyin":"Wǒ zhèng zài chīfàn.","vn":"Tôi đang ăn cơm."},{"cn":"他正写作业呢。","pinyin":"Tā zhèng xiě zuòyè ne.","vn":"Anh ấy đang viết bài tập."},{"cn":"我们正说你呢。","pinyin":"Wǒmen zhèng shuō nǐ ne.","vn":"Chúng tôi đang nói về bạn đấy."}]},{"hanzi":"外面","pinyin":"wàimiàn","pos":"dt.","vn":"bên ngoài","examples":[{"cn":"外面在下雨。","pinyin":"Wàimiàn zài xiàyǔ.","vn":"Bên ngoài đang mưa."},{"cn":"外面很冷，多穿衣服。","pinyin":"Wàimiàn hěn lěng, duō chuān yīfu.","vn":"Bên ngoài lạnh lắm, mặc thêm áo vào."},{"cn":"孩子们在外面玩儿。","pinyin":"Háizimen zài wàimiàn wánr.","vn":"Bọn trẻ đang chơi ở bên ngoài."}]},{"hanzi":"阴","pinyin":"yīn","pos":"tt.","vn":"âm u, có mây, râm","examples":[{"cn":"今天天阴，可能要下雨。","pinyin":"Jīntiān tiān yīn, kěnéng yào xiàyǔ.","vn":"Hôm nay trời âm u, có thể sẽ mưa."},{"cn":"天阴了，我们快回家吧。","pinyin":"Tiān yīn le, wǒmen kuài huí jiā ba.","vn":"Trời âm u rồi, chúng ta mau về nhà thôi."},{"cn":"这几天一直是阴天。","pinyin":"Zhè jǐ tiān yìzhí shì yīntiān.","vn":"Mấy ngày nay trời cứ âm u mãi."}]},{"hanzi":"从小","pinyin":"cóngxiǎo","pos":"phó.","vn":"từ nhỏ","examples":[{"cn":"我从小就喜欢唱歌。","pinyin":"Wǒ cóngxiǎo jiù xǐhuan chànggē.","vn":"Tôi thích hát từ nhỏ."},{"cn":"他从小在北京长大。","pinyin":"Tā cóngxiǎo zài Běijīng zhǎngdà.","vn":"Anh ấy lớn lên ở Bắc Kinh từ nhỏ."},{"cn":"从小她就很聪明。","pinyin":"Cóngxiǎo tā jiù hěn cōngming.","vn":"Từ nhỏ cô ấy đã rất thông minh."}]},{"hanzi":"地铁","pinyin":"dìtiě","pos":"dt.","vn":"tàu điện ngầm","examples":[{"cn":"我每天坐地铁上班。","pinyin":"Wǒ měitiān zuò dìtiě shàngbān.","vn":"Mỗi ngày tôi đi tàu điện ngầm đi làm."},{"cn":"地铁站离这儿很近。","pinyin":"Dìtiě zhàn lí zhèr hěn jìn.","vn":"Trạm tàu điện ngầm gần đây lắm."},{"cn":"坐地铁比开车快。","pinyin":"Zuò dìtiě bǐ kāichē kuài.","vn":"Đi tàu điện ngầm nhanh hơn lái xe."}]},{"hanzi":"楼","pinyin":"lóu","pos":"dt.","vn":"toà nhà, lầu, tầng","examples":[{"cn":"我家住在五楼。","pinyin":"Wǒ jiā zhù zài wǔ lóu.","vn":"Nhà tôi ở tầng năm."},{"cn":"这栋楼很高。","pinyin":"Zhè dòng lóu hěn gāo.","vn":"Tòa nhà này rất cao."},{"cn":"他上楼去了。","pinyin":"Tā shàng lóu qù le.","vn":"Anh ấy đã lên lầu rồi."}]},{"hanzi":"站","pinyin":"zhàn","pos":"dt.","vn":"trạm, bến","examples":[{"cn":"下一站是哪儿？","pinyin":"Xià yí zhàn shì nǎr?","vn":"Trạm tiếp theo là ở đâu?"},{"cn":"公交车站在前面。","pinyin":"Gōngjiāochē zhàn zài qiánmiàn.","vn":"Trạm xe buýt ở phía trước."},{"cn":"我在车站等你。","pinyin":"Wǒ zài chēzhàn děng nǐ.","vn":"Tôi đợi bạn ở bến xe."}]},{"hanzi":"小时候","pinyin":"xiǎoshíhou","pos":"dt.","vn":"lúc nhỏ, thời thơ ấu","examples":[{"cn":"小时候我住在农村。","pinyin":"Xiǎoshíhou wǒ zhù zài nóngcūn.","vn":"Lúc nhỏ tôi sống ở nông thôn."},{"cn":"小时候我很怕狗。","pinyin":"Xiǎoshíhou wǒ hěn pà gǒu.","vn":"Lúc nhỏ tôi rất sợ chó."},{"cn":"他小时候很调皮。","pinyin":"Tā xiǎoshíhou hěn tiáopí.","vn":"Lúc nhỏ anh ấy rất nghịch ngợm."}]},{"hanzi":"好","pinyin":"hǎo","pos":"phó.","vn":"rất, thật là","examples":[{"cn":"今天好热啊！","pinyin":"Jīntiān hǎo rè a!","vn":"Hôm nay nóng thật đấy!"},{"cn":"这件衣服好漂亮。","pinyin":"Zhè jiàn yīfu hǎo piàoliang.","vn":"Chiếc áo này đẹp thật."},{"cn":"我好久没见到你了。","pinyin":"Wǒ hǎo jiǔ méi jiàndào nǐ le.","vn":"Đã lâu lắm rồi tôi không gặp bạn."}]}],"grammar":[{"title":"比较句(4) Câu so sánh (4)","explanation_vn":"用“比”表示的比较句中,“多了”或“得多”用在形容词后面,表示差别很大。基本结构:A比B+形容词+多了/得多。 Trong câu so sánh dùng “比”, “多了” hoặc “得多” đặt sau tính từ để biểu thị sự khác biệt rất lớn. Cấu trúc cơ bản: A比B+tính từ+多了/得多.","examples":[{"cn":"我这里比北京冷多了。","pinyin":"","vn":""},{"cn":"坐飞机比坐火车快得多。","pinyin":"","vn":""},{"cn":"他觉得红茶比绿茶好喝得多。","pinyin":"","vn":""}]},{"title":"比较句(5) Câu so sánh (5)","explanation_vn":"用“比”表示的比较句中,如果动词带状态补语,“比”用在动词前后都可以。 Trong câu so sánh dùng “比”, nếu động từ có bổ ngữ trạng thái, “比” có thể đặt trước hoặc đặt sau động từ.","examples":[{"cn":"昨天比今天下得大。","pinyin":"","vn":""},{"cn":"妈妈比我睡得晚。","pinyin":"","vn":""},{"cn":"李文跑得比白家月快。","pinyin":"","vn":""}]},{"title":"比较句(6) Câu so sánh (6)","explanation_vn":"用“比”表示的比较句中,如果动词既带宾语,又带状态补语,可以把宾语提前,或者重复动词。如果动词是离合词,需要重复动词性语素。 Trong câu so sánh dùng “比”, nếu động từ vừa mang tân ngữ vừa mang bổ ngữ trạng thái thì có thể đưa tân ngữ lên trước hoặc lặp lại động từ. Nếu động từ là từ li hợp thì cần lặp lại từ tố mang tính chất động từ.","examples":[{"cn":"你跑步跑得比我快。","pinyin":"","vn":""},{"cn":"白家月汉字写得比陈天好。","pinyin":"","vn":""},{"cn":"他踢足球比我踢得好。","pinyin":"","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"喂,家月,是你啊!有什么事情吗?","pinyin":"Wéi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"没什么事,就想跟您说说话。","pinyin":"Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"好啊。你今天没课吗?","pinyin":"Hǎo a. Nǐ jīntiān méi kè ma?"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"下午有课。您那里天气怎么样?","pinyin":"Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?"},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"北京这几天虽然是晴天,但是有点儿冷。","pinyin":"Běijīng zhè jǐ tiān suīrán shì qíngtiān, dànshì yǒudiǎnr lěng."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"我这里比北京冷多了,外边还正下着雪呢!","pinyin":"Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!"}],"translation_vn":"Vương Nhất Tuyết: A lô, Gia Nguyệt, là em à! Có việc gì không? Bạch Gia Nguyệt: Không có việc gì ạ, chỉ là muốn trò chuyện với chị một chút thôi. Vương Nhất Tuyết: Được chứ. Hôm nay em không lên lớp à? Bạch Gia Nguyệt: Buổi chiều em mới có tiết. Thời tiết chỗ chị thế nào? Vương Nhất Tuyết: Mấy ngày hôm nay, Bắc Kinh tuy nắng nhưng vẫn hơi lạnh. Bạch Gia Nguyệt: Chỗ em lạnh hơn Bắc Kinh nhiều, bên ngoài tuyết vẫn đang rơi đấy!","audio_dialogue":"12-1 @xitoytili_luoluodafang.mp3","audio_vocab":"12-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"喂,一飞,听家月说你那边下雪了,下得大不大?","pinyin":"Wéi, Yīfēi, tīng Jiāyuè shuō nǐ nàbiān xià xuě le, xià de dà bu dà?"},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"今天不大,昨天比今天下得大。","pinyin":"Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"天气不好,你去外面的时候多穿点儿衣服。","pinyin":"Tiānqì bù hǎo, nǐ qù wàimiàn de shíhou duō chuān diǎnr yīfu."},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"这几天我在网上上课,没出去过。","pinyin":"Zhè jǐ tiān wǒ zài wǎngshang shàngkè, méi chūqù guo."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"那就好,有事记得给我打电话。","pinyin":"Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà."},{"speaker":"王一飞 (Vương Nhất Phi)","cn":"好的。现在不下雪了,我出去买点儿吃的。","pinyin":"Hǎo de. Xiànzài bú xià xuě le, wǒ chūqù mǎi diǎnr chī de."},{"speaker":"王一雪 (Vương Nhất Tuyết)","cn":"一次多买点儿,阴天下雪什么的就少出去吧。","pinyin":"Yí cì duō mǎi diǎnr, yīntiān xià xuě shénme de jiù shǎo chūqù ba."}],"translation_vn":"Vương Nhất Tuyết: A lô, Nhất Phi à, nghe Gia Nguyệt nói chỗ em tuyết rơi rồi, tuyết to không em? Vương Nhất Phi: Hôm nay không to, hôm qua tuyết to hơn hôm nay. Vương Nhất Tuyết: Thời tiết xấu, khi đi ra ngoài, em nhớ mặc thêm nhiều quần áo một chút nhé. Vương Nhất Phi: Mấy ngày nay em dạy online nên không đi ra ngoài. Vương Nhất Tuyết: Vậy thì tốt rồi, có việc gì nhớ gọi điện cho chị nhé. Vương Nhất Phi: Vâng ạ. Bây giờ tuyết ngừng rơi rồi, em ra ngoài mua chút đồ ăn. Vương Nhất Tuyết: Mỗi lần mua thì nên mua nhiều một chút, những lúc trời âm u hoặc có tuyết thì nên hạn chế ra ngoài.","audio_dialogue":"12-3 @xitoytili_luoluodafang.mp3","audio_vocab":"12-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"李文 (Lý Văn)","cn":"喂,家月,今天天气不错,我们去跑步吧!","pinyin":"Wèi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!"},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"你跑步跑得比我快,我们能一起跑吗?","pinyin":"Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?"},{"speaker":"李文 (Lý Văn)","cn":"可以的,我慢慢跑,等着你。","pinyin":"Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"好吧。你真爱跑步啊!","pinyin":"Hǎo ba. Nǐ zhēn ài pǎobù a!"},{"speaker":"李文 (Lý Văn)","cn":"我从小就经常跟爸爸跑步,跑步能让人快乐。","pinyin":"Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè."},{"speaker":"白家月 (Bạch Gia Nguyệt)","cn":"好,那我准备一下。","pinyin":"Hǎo, nà wǒ zhǔnbèi yíxià."},{"speaker":"李文 (Lý Văn)","cn":"我现在坐地铁去找你,一会儿楼下见。","pinyin":"Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóu xià jiàn."}],"translation_vn":"Lý Văn: A lô, Gia Nguyệt à, hôm nay thời tiết khá đẹp, chúng ta đi chạy bộ nhé? Bạch Gia Nguyệt: Bạn chạy nhanh hơn mình, chúng ta có thể chạy cùng nhau không? Lý Văn: Được mà, mình sẽ chạy chầm chậm đợi bạn. Bạch Gia Nguyệt: Được. Bạn đúng là mê chạy bộ thật đấy! Lý Văn: Từ nhỏ mình đã thường xuyên chạy bộ cùng bố rồi. Chạy bộ khiến con người ta thấy sảng khoái hẳn ra. Bạch Gia Nguyệt: Ừ, vậy để mình chuẩn bị một chút. Lý Văn: Bây giờ mình đi tàu điện ngầm qua chỗ bạn, lát nữa gặp nhau ở dưới tầng nhé.","audio_dialogue":"12-5 @xitoytili_luoluodafang.mp3","audio_vocab":"12-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"前几天天气不好,我没走路,每天坐两站地铁去学校。今天是个大晴天,李文让我跟他去外面跑步。他小时候经常跑步,跑得比我快,但是他会等我。跟李文一起跑步,我好高兴啊!","pinyin":"Qián jǐ tiān tiānqì bù hǎo, wǒ méi zǒulù, měi tiān zuò liǎng zhàn dìtiě qù xuéxiào. Jīntiān shì ge dà qíngtiān, Lǐ Wén ràng wǒ gēn tā qù wàimiàn pǎobù. Tā xiǎoshíhou jīngcháng pǎobù, pǎo de bǐ wǒ kuài, dànshì tā huì děng wǒ. Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!"}],"translation_vn":"Mấy hôm trước thời tiết xấu, tôi không đi bộ mà mỗi ngày đều đi hai trạm tàu điện ngầm để đến trường. Hôm nay trời quang đãng, Lý Văn bảo tôi cùng bạn ấy ra ngoài chạy bộ. Hồi nhỏ, bạn ấy thường xuyên chạy bộ, chạy nhanh hơn tôi, nhưng bạn ấy sẽ đợi tôi. Chạy bộ cùng Lý Văn tôi thấy rất vui!","audio_dialogue":"12-7 @xitoytili_luoluodafang.mp3","audio_vocab":"12-8 @xitoytili_luoluodafang.mp3"}]},{"id":13,"title_cn":"我们爱上中文课","title_pinyin":"Wǒmen ài shàng Zhōngwén kè","title_vn":"Chúng tôi yêu thích môn tiếng Trung Quốc","goals":["能听懂并使用比较句说明事物之间的具体差别。Có thể nghe hiểu và sử dụng được câu so sánh để nói rõ sự khác biệt cụ thể giữa các sự vật.","能听懂并使用比较句说明事物之间的差别很小。Có thể nghe hiểu và sử dụng được câu so sánh để nói rõ về sự khác biệt nhỏ giữa các sự vật.","掌握双宾语句的用法，能表达给予的意思。Nắm vững cách dùng của câu có hai tân ngữ để diễn đạt ý nghĩa cho, tặng."],"vocab":[{"hanzi":"新年","pinyin":"xīnnián","pos":"dt.","vn":"năm mới","examples":[{"cn":"新年快乐!","pinyin":"Xīnnián kuàilè!","vn":"Chúc mừng năm mới!"},{"cn":"新年的时候我们一起吃饺子。","pinyin":"Xīnnián de shíhou wǒmen yìqǐ chī jiǎozi.","vn":"Vào dịp năm mới chúng tôi cùng nhau ăn sủi cảo."},{"cn":"新年你有什么打算?","pinyin":"Xīnnián nǐ yǒu shénme dǎsuan?","vn":"Năm mới bạn có dự định gì?"}]},{"hanzi":"教","pinyin":"jiāo","pos":"đgt.","vn":"dạy","examples":[{"cn":"妈妈教我做饭。","pinyin":"Māma jiāo wǒ zuò fàn.","vn":"Mẹ dạy tôi nấu ăn."},{"cn":"他是教汉语的老师。","pinyin":"Tā shì jiāo Hànyǔ de lǎoshī.","vn":"Anh ấy là giáo viên dạy tiếng Hán."},{"cn":"你能教我跳舞吗?","pinyin":"Nǐ néng jiāo wǒ tiàowǔ ma?","vn":"Bạn có thể dạy tôi nhảy múa không?"}]},{"hanzi":"花","pinyin":"huā","pos":"dt.","vn":"hoa","examples":[{"cn":"这些花真漂亮。","pinyin":"Zhèxiē huā zhēn piàoliang.","vn":"Những bông hoa này thật đẹp."},{"cn":"我想买一束花送给她。","pinyin":"Wǒ xiǎng mǎi yí shù huā sòng gěi tā.","vn":"Tôi muốn mua một bó hoa tặng cô ấy."},{"cn":"春天到了,公园里开满了花。","pinyin":"Chūntiān dào le, gōngyuán lǐ kāi mǎn le huā.","vn":"Mùa xuân đến rồi, trong công viên hoa nở đầy."}]},{"hanzi":"希望","pinyin":"xīwàng","pos":"đgt.","vn":"hy vọng, mong muốn","examples":[{"cn":"我希望明天不下雨。","pinyin":"Wǒ xīwàng míngtiān bú xiàyǔ.","vn":"Tôi hy vọng ngày mai không mưa."},{"cn":"她希望能早点儿见到你。","pinyin":"Tā xīwàng néng zǎo diǎnr jiàndào nǐ.","vn":"Cô ấy hy vọng có thể sớm gặp bạn."},{"cn":"希望你一切都好。","pinyin":"Xīwàng nǐ yíqiè dōu hǎo.","vn":"Hy vọng mọi chuyện của bạn đều tốt."}]},{"hanzi":"上面","pinyin":"shàngmiàn","pos":"dt.","vn":"phía trên, bên trên","examples":[{"cn":"桌子上面有一本书。","pinyin":"Zhuōzi shàngmiàn yǒu yì běn shū.","vn":"Trên bàn có một quyển sách."},{"cn":"照片上面写着你的名字。","pinyin":"Zhàopiàn shàngmiàn xiězhe nǐ de míngzi.","vn":"Phía trên bức ảnh có viết tên bạn."},{"cn":"请把杯子放在上面。","pinyin":"Qǐng bǎ bēizi fàng zài shàngmiàn.","vn":"Làm ơn đặt cốc lên phía trên."}]},{"hanzi":"洗手间","pinyin":"xǐshǒujiān","pos":"dt.","vn":"nhà vệ sinh","examples":[{"cn":"请问洗手间在哪儿?","pinyin":"Qǐngwèn xǐshǒujiān zài nǎr?","vn":"Xin hỏi nhà vệ sinh ở đâu?"},{"cn":"我想去一下洗手间。","pinyin":"Wǒ xiǎng qù yíxià xǐshǒujiān.","vn":"Tôi muốn đi nhà vệ sinh một chút."},{"cn":"洗手间里没有纸了。","pinyin":"Xǐshǒujiān lǐ méiyǒu zhǐ le.","vn":"Trong nhà vệ sinh hết giấy rồi."}]},{"hanzi":"里面","pinyin":"lǐmiàn","pos":"dt.","vn":"bên trong","examples":[{"cn":"包里面有什么?","pinyin":"Bāo lǐmiàn yǒu shénme?","vn":"Bên trong túi có gì?"},{"cn":"房间里面很干净。","pinyin":"Fángjiān lǐmiàn hěn gānjìng.","vn":"Bên trong phòng rất sạch sẽ."},{"cn":"他走进房子里面。","pinyin":"Tā zǒu jìn fángzi lǐmiàn.","vn":"Anh ấy đi vào bên trong ngôi nhà."}]},{"hanzi":"笔","pinyin":"bǐ","pos":"lượng.","vn":"nét, nét bút","examples":[{"cn":"这个字一共有几笔?","pinyin":"Zhège zì yígòng yǒu jǐ bǐ?","vn":"Chữ này tổng cộng có bao nhiêu nét?"},{"cn":"第一笔要先写横。","pinyin":"Dì yī bǐ yào xiān xiě héng.","vn":"Nét đầu tiên phải viết nét ngang trước."},{"cn":"他的字每一笔都很好看。","pinyin":"Tā de zì měi yì bǐ dōu hěn hǎokàn.","vn":"Chữ của anh ấy nét nào cũng đẹp."}]},{"hanzi":"可能","pinyin":"kěnéng","pos":"đgt.","vn":"có thể, có lẽ","examples":[{"cn":"他可能不来了。","pinyin":"Tā kěnéng bù lái le.","vn":"Có lẽ anh ấy không đến nữa."},{"cn":"明天可能会下雨。","pinyin":"Míngtiān kěnéng huì xiàyǔ.","vn":"Ngày mai có thể sẽ mưa."},{"cn":"你说的有可能是对的。","pinyin":"Nǐ shuō de yǒu kěnéng shì duì de.","vn":"Điều bạn nói có thể là đúng."}]},{"hanzi":"上网","pinyin":"shàngwǎng","pos":"đgt.","vn":"lên mạng","examples":[{"cn":"我每天晚上都上网。","pinyin":"Wǒ měitiān wǎnshang dōu shàngwǎng.","vn":"Mỗi tối tôi đều lên mạng."},{"cn":"你在上网吗?","pinyin":"Nǐ zài shàngwǎng ma?","vn":"Bạn đang lên mạng à?"},{"cn":"他喜欢上网看新闻。","pinyin":"Tā xǐhuan shàngwǎng kàn xīnwén.","vn":"Anh ấy thích lên mạng xem tin tức."}]},{"hanzi":"那样","pinyin":"nàyàng","pos":"dt.","vn":"như vậy, thế kia","examples":[{"cn":"别那样说话。","pinyin":"Bié nàyàng shuōhuà.","vn":"Đừng nói chuyện như vậy."},{"cn":"我从来没见过那样的事。","pinyin":"Wǒ cónglái méi jiànguò nàyàng de shì.","vn":"Tôi chưa từng thấy chuyện như thế bao giờ."},{"cn":"你为什么那样看着我?","pinyin":"Nǐ wèishénme nàyàng kànzhe wǒ?","vn":"Sao bạn lại nhìn tôi như vậy?"}]},{"hanzi":"告诉","pinyin":"gàosu","pos":"đgt.","vn":"nói cho biết, kể","examples":[{"cn":"请告诉我你的名字。","pinyin":"Qǐng gàosu wǒ nǐ de míngzi.","vn":"Làm ơn cho tôi biết tên bạn."},{"cn":"我告诉她明天的计划了。","pinyin":"Wǒ gàosu tā míngtiān de jìhuà le.","vn":"Tôi đã nói cho cô ấy biết kế hoạch ngày mai."},{"cn":"别告诉别人这件事。","pinyin":"Bié gàosu biérén zhè jiàn shì.","vn":"Đừng nói cho người khác biết chuyện này."}]},{"hanzi":"班","pinyin":"bān","pos":"dt.","vn":"lớp","examples":[{"cn":"我在三班上课。","pinyin":"Wǒ zài sān bān shàngkè.","vn":"Tôi học ở lớp ba."},{"cn":"他是我们班的班长。","pinyin":"Tā shì wǒmen bān de bānzhǎng.","vn":"Anh ấy là lớp trưởng của lớp chúng tôi."},{"cn":"这个班有二十个学生。","pinyin":"Zhège bān yǒu èrshí gè xuésheng.","vn":"Lớp này có hai mươi học sinh."}]}],"grammar":[{"title":"双宾语句 (2) Câu có hai tân ngữ (2)","explanation_vn":"Câu có hai tân ngữ là câu mà động từ mang hai tân ngữ, thông thường tân ngữ thứ nhất chỉ người, tân ngữ thứ hai chỉ sự vật. Trong bài này, câu hai tân ngữ được tạo bởi các động từ \"拿\", \"送\", \"卖\" với \"给\".","examples":[{"cn":"王老师喜欢花，就送给她花吧。","pinyin":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","vn":""},{"cn":"她拿给我一杯水。","pinyin":"Tā ná gěi wǒ yì bēi shuǐ.","vn":""},{"cn":"他卖给我一本中文书。","pinyin":"Tā mài gěi wǒ yì běn Zhōngwén shū.","vn":""}]},{"title":"比较句 (7) Câu so sánh (7)","explanation_vn":"Trong câu so sánh sử dụng \"比\", cụm từ chỉ số lượng được đặt sau tính từ để biểu thị sự khác biệt cụ thể. Cấu trúc cơ bản: A bỉ B + tính từ + cụm từ chỉ số lượng.","examples":[{"cn":"今天的词比昨天多了十个。","pinyin":"Jīntiān de cí bǐ zuótiān duō le shí ge.","vn":""},{"cn":"姐姐比我大三岁。","pinyin":"Jiějie bǐ wǒ dà sān suì.","vn":""},{"cn":"坐飞机比坐火车快五个多小时。","pinyin":"Zuò fēijī bǐ zuò huǒchē kuài wǔ ge duō xiǎoshí.","vn":""}]},{"title":"比较句 (8) Câu so sánh (8)","explanation_vn":"Trong câu so sánh dùng \"比\", \"一点儿\" hoặc \"一些\" được đặt sau tính từ để biểu thị sự khác biệt không lớn. Cấu trúc cơ bản: A bỉ B + tính từ + 一点儿/一些.","examples":[{"cn":"比我们一起买的那个本子贵一点儿。","pinyin":"Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr.","vn":""},{"cn":"姐姐比我高一点儿。","pinyin":"Jiějie bǐ wǒ gāo yìdiǎnr.","vn":""},{"cn":"那间教室比这间大一些。","pinyin":"Nà jiān jiàoshì bǐ zhè jiān dà yìxiē.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"Bạch Gia Nguyệt","cn":"时间过得真快啊！新年就要到了。","pinyin":"Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le."},{"speaker":"Trần Thiên Trung","cn":"这一年王老师教我们中文，每天工作都很累。","pinyin":"Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měitiān gōngzuò dōu hěn lèi."},{"speaker":"Bạch Gia Nguyệt","cn":"是啊，她教得很好。因为她，我们都非常爱上中文课。","pinyin":"Shì a, tā jiāo de hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè."},{"speaker":"Trần Thiên Trung","cn":"我们给她准备个新年礼物吧。你觉得送给她什么好呢？","pinyin":"Wǒmen gěi tā zhǔnbèi ge xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?"},{"speaker":"Bạch Gia Nguyệt","cn":"王老师喜欢花，就送给她花吧。","pinyin":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba."},{"speaker":"Trần Thiên Trung","cn":"那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。","pinyin":"Nà wǒmen qù huādiàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huādiàn hái yǒu piàoliang de huā."}],"translation_vn":"Bạch Gia Nguyệt: Thời gian trôi nhanh thật đấy! Sắp đến năm mới rồi. Trần Thiên Trung: Một năm nay, cô Vương dạy chúng ta tiếng Trung Quốc, ngày nào làm việc cũng đều rất mệt. Bạch Gia Nguyệt: Đúng vậy, cô dạy rất hay. Nhờ có cô mà chúng ta ai cũng yêu thích môn tiếng Trung Quốc. Trần Thiên Trung: Chúng ta hãy chuẩn bị một món quà năm mới tặng cô nhé. Bạn thấy tặng cô quà gì thì hợp nhỉ? Bạch Gia Nguyệt: Cô Vương thích hoa đấy, cứ tặng hoa cho cô đi. Trần Thiên Trung: Vậy chúng ta ra cửa hàng hoa xem thử. Bây giờ người mua hoa rất đông, hy vọng ở đó vẫn còn hoa đẹp.","audio_dialogue":"13-1 @xitoytili_luoluodafang.mp3","audio_vocab":"13-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"Bạch Gia Nguyệt","cn":"王老师，今天的词语比昨天多了十个。","pinyin":"Wáng lǎoshī, jīntiān de cíyǔ bǐ zuótiān duō le shí ge."},{"speaker":"Vương Nhất Phi","cn":"是啊！你们都学会了吗？","pinyin":"Shì a! Nǐmen dōu xuéhuì le ma?"},{"speaker":"Annie","cn":"学会了，没有问题。","pinyin":"Xuéhuì le, méiyǒu wèntí."},{"speaker":"Vương Nhất Phi","cn":"好。现在我来说，你们在本子上面写。","pinyin":"Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmiàn xiě."},{"speaker":"Vương Nhất Phi","cn":"同学们，\"洗手间\"的\"间\"字写错了，它的里面是\"日\"，不是\"口\"。","pinyin":"Tóngxuémen, \"xǐshǒujiān\" de \"jiān\" zì xiěcuò le, tā de lǐmiàn shì \"rì\", bú shì \"kǒu\"."},{"speaker":"Bạch Gia Nguyệt","cn":"\"日\"比\"口\"多一笔，写\"口\"就是\"问题\"的\"问\"了。","pinyin":"\"Rì\" bǐ \"kǒu\" duō yì bǐ, xiě \"kǒu\" jiù shì \"wèntí\" de \"wèn\" le."},{"speaker":"Vương Nhất Phi","cn":"没错，你说得很对。","pinyin":"Méi cuò, nǐ shuō de hěn duì."}],"translation_vn":"Bạch Gia Nguyệt: Cô Vương ơi, từ mới của ngày hôm nay nhiều hơn hôm qua mười từ ạ. Vương Nhất Phi: Đúng vậy! Các em đã nắm được hết chưa? Annie: Dạ, chúng em đã nắm được rồi ạ, không có vấn đề gì đâu ạ. Vương Nhất Phi: Tốt. Bây giờ cô sẽ đọc, các em viết vào vở nhé. Vương Nhất Phi: Các em ơi, chữ \"间\" trong từ \"洗手间\" viết sai rồi, bên trong nó là chữ \"日\" (nhật) chứ không phải chữ \"口\" (khẩu) đâu nhé. Bạch Gia Nguyệt: Chữ \"日\" nhiều hơn chữ \"口\" một nét, nếu viết thành \"口\" thì sẽ thành chữ \"问\" trong từ \"问题\" rồi ạ. Vương Nhất Phi: Đúng rồi, em nói rất chính xác.","audio_dialogue":"13-3 @xitoytili_luoluodafang.mp3","audio_vocab":"13-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"Annie","cn":"家月，你觉得这个本子怎么样？","pinyin":"Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?"},{"speaker":"Bạch Gia Nguyệt","cn":"很漂亮，多少钱一个？","pinyin":"Hěn piàoliang, duōshao qián yí ge?"},{"speaker":"Annie","cn":"比我们一起买的那个本子贵一点儿。","pinyin":"Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr."},{"speaker":"Bạch Gia Nguyệt","cn":"这么漂亮的本子，不可能贵一点儿吧？","pinyin":"Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?"},{"speaker":"Annie","cn":"我是上网买的，真没那么贵。我买了两个，送你一个。","pinyin":"Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎile liǎng ge, sòng nǐ yí ge."},{"speaker":"Bạch Gia Nguyệt","cn":"谢谢！那我送给你什么呢？","pinyin":"Xièxie! Nà wǒ sòng gěi nǐ shénme ne?"},{"speaker":"Annie","cn":"咖啡杯吧。我最喜欢喝咖啡了。","pinyin":"Kāfēibēi ba. Wǒ zuì xǐhuan hē kāfēi le."},{"speaker":"Bạch Gia Nguyệt","cn":"好，那样我们就都有新年礼物了！","pinyin":"Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!"}],"translation_vn":"Annie: Gia Nguyệt, bạn thấy cuốn vở này thế nào? Bạch Gia Nguyệt: Rất đẹp. Bao nhiêu tiền một cuốn vậy? Annie: Đắt hơn hôm trước mà chúng ta cùng đi mua một chút. Bạch Gia Nguyệt: Cuốn vở đẹp thế này, không thể chỉ đắt hơn một chút nhỉ? Annie: Mình mua trên mạng đấy, thật sự không đắt đến thế đâu. Mình mua hai cuốn, tặng bạn một cuốn này. Bạch Gia Nguyệt: Cảm ơn nhé! Vậy mình nên tặng lại bạn cái gì đây? Annie: Tặng cốc uống cà phê đi, mình thích uống cà phê nhất. Bạch Gia Nguyệt: Được, như vậy là chúng ta ai cũng đều có quà năm mới rồi!","audio_dialogue":"13-5 @xitoytili_luoluodafang.mp3","audio_vocab":"13-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"新年就要到了，安妮送给我一个新本子。她告诉我是在网上买的，比我的本子贵一点儿。我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。","pinyin":"Xīnnián jiù yào dào le, Ānnī sòng gěi wǒ yí ge xīn běnzi. Tā gàosu wǒ shì zài wǎngshàng mǎi de, bǐ wǒ de běnzi guì yìdiǎnr. Wǒmen bān tóngxué yě sòngle Wáng lǎoshī piàoliang de huā, xīwàng tā gāogāoxìngxìng de guò ge xīnnián."}],"translation_vn":"Sắp năm mới rồi, Annie tặng tôi một cuốn vở mới. Bạn ấy kể với tôi là mua trên mạng, đắt hơn cuốn của tôi một chút. Các bạn trong lớp cũng tặng cô Vương những bông hoa đẹp, hy vọng cô vui vẻ đón một năm mới thật vui.","audio_dialogue":"13-7 @xitoytili_luoluodafang.mp3","audio_vocab":"13-8 @xitoytili_luoluodafang.mp3"}]},{"id":14,"title_cn":"一个人过年多没意思啊","title_pinyin":"Yí gè rén guònián duō méi yìsi a","title_vn":"Một mình đón năm mới thì thật vô vị","goals":["能听懂并描述某处存在某人或某物。Có thể nghe hiểu và miêu tả một ai đó hoặc vật gì đó đang tồn tại ở nơi nào đó.","能听懂并使用复合趋向补语表达动作的方向。Có thể nghe hiểu và sử dụng được bổ ngữ xu hướng kép để diễn đạt phương hướng của động tác.","掌握程度副词\"多\"的用法，能表达程度很高的意思。Nắm vững cách dùng của phó từ chỉ mức độ \"多\" để diễn đạt ý nghĩa mức độ rất cao."],"vocab":[{"hanzi":"站","pinyin":"zhàn","pos":"đgt.","vn":"đứng","examples":[{"cn":"请站起来。","pinyin":"Qǐng zhàn qǐlai.","vn":"Mời đứng lên."},{"cn":"他站在门口等我。","pinyin":"Tā zhàn zài ménkǒu děng wǒ.","vn":"Anh ấy đứng ở cửa đợi tôi."},{"cn":"别站着,坐下休息吧。","pinyin":"Bié zhànzhe, zuòxià xiūxi ba.","vn":"Đừng đứng nữa, ngồi xuống nghỉ đi."}]},{"hanzi":"包","pinyin":"bāo","pos":"dt./đgt./lượng.","vn":"túi, gói, bao","examples":[{"cn":"我买了一个包。","pinyin":"Wǒ mǎile yí gè bāo.","vn":"Tôi đã mua một cái túi."},{"cn":"妈妈在包饺子。","pinyin":"Māma zài bāo jiǎozi.","vn":"Mẹ đang gói sủi cảo."},{"cn":"我要一包糖。","pinyin":"Wǒ yào yì bāo táng.","vn":"Tôi muốn một gói kẹo."}]},{"hanzi":"过年","pinyin":"guònián","pos":"đgt.","vn":"đón Tết, ăn Tết","examples":[{"cn":"我们回家过年。","pinyin":"Wǒmen huí jiā guònián.","vn":"Chúng tôi về nhà đón Tết."},{"cn":"过年的时候很热闹。","pinyin":"Guònián de shíhou hěn rènao.","vn":"Lúc đón Tết rất nhộn nhịp."},{"cn":"你今年在哪儿过年?","pinyin":"Nǐ jīnnián zài nǎr guònián?","vn":"Năm nay bạn đón Tết ở đâu?"}]},{"hanzi":"没意思","pinyin":"méi yìsi","pos":"","vn":"vô vị, chán","examples":[{"cn":"这个电影真没意思。","pinyin":"Zhège diànyǐng zhēn méi yìsi.","vn":"Bộ phim này thật chán."},{"cn":"一个人在家没意思。","pinyin":"Yí gè rén zài jiā méi yìsi.","vn":"Ở nhà một mình thật buồn chán."},{"cn":"他觉得这本书没意思。","pinyin":"Tā juéde zhè běn shū méi yìsi.","vn":"Anh ấy thấy quyển sách này vô vị."}]},{"hanzi":"位","pinyin":"wèi","pos":"lượng.","vn":"người (cách gọi lịch sự)","examples":[{"cn":"这位是我的老师。","pinyin":"Zhè wèi shì wǒ de lǎoshī.","vn":"Vị này là thầy giáo của tôi."},{"cn":"请问几位?","pinyin":"Qǐngwèn jǐ wèi?","vn":"Xin hỏi mấy vị ạ?"},{"cn":"那位先生是谁?","pinyin":"Nà wèi xiānsheng shì shéi?","vn":"Vị tiên sinh đó là ai?"}]},{"hanzi":"前面","pinyin":"qiánmiàn","pos":"dt.","vn":"phía trước","examples":[{"cn":"前面有一个公园。","pinyin":"Qiánmiàn yǒu yí gè gōngyuán.","vn":"Phía trước có một công viên."},{"cn":"他走在我前面。","pinyin":"Tā zǒu zài wǒ qiánmiàn.","vn":"Anh ấy đi ở phía trước tôi."},{"cn":"请往前面走。","pinyin":"Qǐng wǎng qiánmiàn zǒu.","vn":"Mời đi về phía trước."}]},{"hanzi":"房子","pinyin":"fángzi","pos":"dt.","vn":"nhà, ngôi nhà, căn hộ","examples":[{"cn":"这是我们的新房子。","pinyin":"Zhè shì wǒmen de xīn fángzi.","vn":"Đây là ngôi nhà mới của chúng tôi."},{"cn":"他们买了一套房子。","pinyin":"Tāmen mǎile yí tào fángzi.","vn":"Họ đã mua một căn nhà."},{"cn":"这个房子很大。","pinyin":"Zhège fángzi hěn dà.","vn":"Ngôi nhà này rất to."}]},{"hanzi":"小孩儿","pinyin":"xiǎoháir","pos":"dt.","vn":"đứa trẻ, trẻ con","examples":[{"cn":"那个小孩儿在哭。","pinyin":"Nàge xiǎoháir zài kū.","vn":"Đứa trẻ đó đang khóc."},{"cn":"小孩儿都喜欢吃糖。","pinyin":"Xiǎoháir dōu xǐhuan chī táng.","vn":"Trẻ con đều thích ăn kẹo."},{"cn":"公园里有很多小孩儿在玩儿。","pinyin":"Gōngyuán lǐ yǒu hěn duō xiǎoháir zài wánr.","vn":"Trong công viên có nhiều trẻ con đang chơi."}]},{"hanzi":"女孩儿","pinyin":"nǚháir","pos":"dt.","vn":"bé gái, cô bé","examples":[{"cn":"那个女孩儿很漂亮。","pinyin":"Nàge nǚháir hěn piàoliang.","vn":"Cô bé đó rất xinh."},{"cn":"这个女孩儿是我妹妹。","pinyin":"Zhège nǚháir shì wǒ mèimei.","vn":"Cô bé này là em gái tôi."},{"cn":"女孩儿们在跳舞。","pinyin":"Nǚháirmen zài tiàowǔ.","vn":"Các cô bé đang nhảy múa."}]},{"hanzi":"姓","pinyin":"xìng","pos":"đgt.","vn":"họ","examples":[{"cn":"我姓王。","pinyin":"Wǒ xìng Wáng.","vn":"Tôi họ Vương."},{"cn":"您贵姓?","pinyin":"Nín guìxìng?","vn":"Xin hỏi quý danh ngài họ gì?"},{"cn":"他姓什么?","pinyin":"Tā xìng shénme?","vn":"Anh ấy họ gì?"}]},{"hanzi":"眼睛","pinyin":"yǎnjing","pos":"dt.","vn":"mắt","examples":[{"cn":"她的眼睛很漂亮。","pinyin":"Tā de yǎnjing hěn piàoliang.","vn":"Mắt cô ấy rất đẹp."},{"cn":"我的眼睛有点儿疼。","pinyin":"Wǒ de yǎnjing yǒudiǎnr téng.","vn":"Mắt tôi hơi đau."},{"cn":"闭上眼睛休息一下。","pinyin":"Bì shàng yǎnjing xiūxi yíxià.","vn":"Nhắm mắt lại nghỉ một chút."}]},{"hanzi":"跳舞","pinyin":"tiàowǔ","pos":"đgt.","vn":"nhảy múa, khiêu vũ","examples":[{"cn":"她跳舞跳得很好。","pinyin":"Tā tiàowǔ tiào de hěn hǎo.","vn":"Cô ấy nhảy múa rất giỏi."},{"cn":"我们周末去跳舞吧。","pinyin":"Wǒmen zhōumò qù tiàowǔ ba.","vn":"Cuối tuần chúng ta đi nhảy múa đi."},{"cn":"他不会跳舞。","pinyin":"Tā bú huì tiàowǔ.","vn":"Anh ấy không biết nhảy múa."}]}],"grammar":[{"title":"存现句 (2) Câu tồn hiện (2)","explanation_vn":"Trợ từ động thái \"着\" đặt sau động từ có thể tạo thành câu tồn hiện, phía trước động từ là cụm từ chỉ nơi chốn, phía sau thường là người hoặc sự vật không xác định. Cấu trúc cơ bản: Từ/cụm từ chỉ nơi chốn + động từ + 着 + người/sự vật.","examples":[{"cn":"你家楼下站着一个人。","pinyin":"Nǐ jiā lóu xià zhànzhe yí ge rén.","vn":""},{"cn":"爸爸手里拿着一杯咖啡。","pinyin":"Bàba shǒu lǐ názhe yì bēi kāfēi.","vn":""},{"cn":"我们教室里坐着不少学生。","pinyin":"Wǒmen jiàoshì lǐ zuòzhe bùshǎo xuésheng.","vn":""}]},{"title":"程度副词\"多\" Phó từ chỉ mức độ \"多\"","explanation_vn":"\"多\" dùng trong câu cảm thán để biểu thị mức độ rất cao.","examples":[{"cn":"你一个人在这儿多没意思啊！","pinyin":"Nǐ yí gè rén zài zhèr duō méi yìsi a!","vn":""},{"cn":"我们一起去多好啊！","pinyin":"Wǒmen yìqǐ qù duō hǎo a!","vn":""},{"cn":"多好看啊！买这件吧。","pinyin":"Duō hǎokàn a! Mǎi zhè jiàn ba.","vn":""}]},{"title":"复合趋向补语 Bổ ngữ xu hướng kép","explanation_vn":"\"上\", \"下\", \"进\", \"出\", \"回\", \"过\" kết hợp với \"来/去\" và cụm từ \"起来\" đều đặt sau động từ để tạo thành bổ ngữ xu hướng kép, biểu thị phương hướng của động tác. Khi động từ mang tân ngữ, có hai trường hợp: (1) tân ngữ là danh từ chỉ địa điểm, đặt trước \"来/去\"; (2) tân ngữ là danh từ chỉ sự vật, đặt trước hoặc sau \"来/去\" đều được.","examples":[{"cn":"她经常跑上来找我玩。","pinyin":"Tā jīngcháng pǎo shànglái zhǎo wǒ wán.","vn":""},{"cn":"楼不高，我们走上去吧。","pinyin":"Lóu bù gāo, wǒmen zǒu shàngqù ba.","vn":""},{"cn":"一听到老师叫他的名字，他就站起来了。","pinyin":"Yì tīngdào lǎoshī jiào tā de míngzi, tā jiù zhàn qǐlái le.","vn":""},{"cn":"同学们都走进教室去了。","pinyin":"Tóngxuémen dōu zǒujìn jiàoshì qù le.","vn":""},{"cn":"妈妈让我买回一些菜来。","pinyin":"Māma ràng wǒ mǎihuí yìxiē cài lái.","vn":""},{"cn":"白家月从书包里拿出来一个漂亮的本子。","pinyin":"Bái Jiāyuè cóng shūbāo lǐ náchūlái yí ge piàoliang de běnzi.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"Lý Văn","cn":"王老师，你家楼下站着一个人。","pinyin":"Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí ge rén."},{"speaker":"Vương Nhất Phi","cn":"我家楼下？我看看。","pinyin":"Wǒ jiā lóu xià? Wǒ kànkan."},{"speaker":"Lý Văn","cn":"那个人穿着黑色的裤子，手里还拿着一个黑色的包。","pinyin":"Nàge rén chuānzhe hēisè de kùzi, shǒu lǐ hái názhe yí ge hēisè de bāo."},{"speaker":"Vương Nhất Phi","cn":"我看见那个人了，他是我男朋友。","pinyin":"Wǒ kànjiàn nàge rén le, tā shì wǒ nánpéngyou."},{"speaker":"Lý Văn","cn":"那我们快过去吧。","pinyin":"Nà wǒmen kuài guòqù ba."}],"translation_vn":"Lý Văn: Cô Vương ơi, ở dưới tầng nhà cô có một người đang đứng kia. Vương Nhất Phi: Dưới tầng nhà cô á? Để cô xem nào. Lý Văn: Người đó mặc chiếc quần màu đen, trên tay còn đang cầm một chiếc túi màu đen nữa. Vương Nhất Phi: Cô nhìn thấy người đó rồi, anh ấy là bạn trai của cô. Lý Văn: Vậy chúng ta mau qua đó đi.","audio_dialogue":"14-1 @xitoytili_luoluodafang.mp3","audio_vocab":"14-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"Vương Nhất Phi","cn":"同乐，真是你啊！上次打电话，你说有时间过来看我，没想到这么快就来了。","pinyin":"Tóngyuè, zhēn shì nǐ a! Shàng cì dǎ diànhuà, nǐ shuō yǒu shíjiān guòlái kàn wǒ, méi xiǎngdào zhème kuài jiù lái le."},{"speaker":"Dương Đồng Lạc","cn":"就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。","pinyin":"Jiù yào guònián le, nǐ yí gè rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎozǎo guòlái le."},{"speaker":"Vương Nhất Phi","cn":"你能来，我太高兴了！","pinyin":"Nǐ néng lái, wǒ tài gāoxìng le!"},{"speaker":"Dương Đồng Lạc","cn":"一飞，你旁边这位是？","pinyin":"Yīfēi, nǐ pángbiān zhè wèi shì?"},{"speaker":"Vương Nhất Phi","cn":"同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。","pinyin":"Tóngyuè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tóngyuè."},{"speaker":"Dương Đồng Lạc","cn":"李文，很高兴认识你！","pinyin":"Lǐ Wén, hěn gāoxìng rènshi nǐ!"},{"speaker":"Lý Văn","cn":"认识你我也很高兴！我家就在前面那个楼，有时间来玩。","pinyin":"Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmiàn nàge lóu, yǒu shíjiān lái wán."}],"translation_vn":"Vương Nhất Phi: Đồng Lạc, đúng là anh rồi! Lần trước gọi điện, anh nói lúc nào rảnh sẽ đến thăm em, không ngờ anh lại đến nhanh thế này! Dương Đồng Lạc: Sắp đến Tết rồi, em ở đây một mình thì thật vô vị, nên anh đến sớm một chút. Vương Nhất Phi: Anh đến được em vui quá! Dương Đồng Lạc: Nhất Phi, bạn bên cạnh em là ai vậy? Vương Nhất Phi: Đồng Lạc ơi, đây là Lý Văn, em ấy học ngành y ở trường em. Lý Văn, đây là bạn trai của em, anh Dương Đồng Lạc. Dương Đồng Lạc: Chào Lý Văn, rất vui được làm quen với em! Lý Văn: Em cũng rất vui được quen biết anh! Nhà em ở ngay toà nhà phía trước kia, lúc nào rảnh anh qua chơi nhé.","audio_dialogue":"14-3 @xitoytili_luoluodafang.mp3","audio_vocab":"14-4 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"Dương Đồng Lạc","cn":"一飞，你住的房子真不错，很大，离学校也不远。","pinyin":"Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn."},{"speaker":"Vương Nhất Phi","cn":"是啊！我楼下还住着一家中国人，他们人很好。","pinyin":"Shì a! Wǒ lóu xià hái zhùzhe yì jiā Zhōngguórén, tāmen rén hěn hǎo."},{"speaker":"Dương Đồng Lạc","cn":"这样你有事情就可以找他们帮忙。","pinyin":"Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng."},{"speaker":"Vương Nhất Phi","cn":"对，我也帮他们家的小孩儿学中文。","pinyin":"Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén."},{"speaker":"Dương Đồng Lạc","cn":"我记得你跟我说过，是个女孩儿，学得也很好。","pinyin":"Wǒ jìde nǐ gēn wǒ shuōguo, shì ge nǚháir, xué de yě hěn hǎo."},{"speaker":"Vương Nhất Phi","cn":"没错，她经常跑上来我这儿玩。","pinyin":"Méi cuò, tā jīngcháng pǎo shànglái wǒ zhèr wán."},{"speaker":"Dương Đồng Lạc","cn":"你问问他们什么时候有时间，我请他们吃个饭。","pinyin":"Nǐ wènwen tāmen shénme shíhou yǒu shíjiān, wǒ qǐng tāmen chī ge fàn."}],"translation_vn":"Dương Đồng Lạc: Nhất Phi, căn hộ em ở thật đẹp, rộng rãi, lại không xa trường học. Vương Nhất Phi: Vâng ạ! Dưới tầng nhà em còn có một gia đình người Trung Quốc sinh sống, họ rất tốt bụng. Dương Đồng Lạc: Như vậy thì khi em có việc gì có thể nhờ họ giúp đỡ. Vương Nhất Phi: Đúng vậy, em cũng đang giúp con họ học tiếng Trung Quốc. Dương Đồng Lạc: Anh nhớ em đã từng kể với anh rồi, là một bé gái, học cũng rất giỏi. Vương Nhất Phi: Vâng, con bé thường xuyên lên đây chơi với em. Dương Đồng Lạc: Em hỏi xem khi nào họ rảnh, anh muốn mời họ ăn một bữa cơm.","audio_dialogue":"14-5.mp3","audio_vocab":"14-6 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我男朋友姓杨，叫杨同乐。他高个子、大眼睛、唱歌唱得很好，跳舞跳得也不错。他和我姐姐一起工作，是姐姐介绍我们认识的。他告诉我，从见到我的第一天开始，他就喜欢上我了。","pinyin":"Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè. Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo, tiàowǔ tiào de yě búcuò. Tā hé wǒ jiějie yìqǐ gōngzuò, shì jiějie jièshào wǒmen rènshi de. Tā gàosu wǒ, cóng jiàndào wǒ de dì-yī tiān kāishǐ, tā jiù xǐhuanshàng wǒ le."}],"translation_vn":"Bạn trai tôi họ Dương, tên là Dương Đồng Lạc. Anh ấy có dáng người cao, mắt to, hát rất hay và nhảy cũng rất đẹp. Anh ấy làm việc cùng với chị gái tôi, chị chính là người đã giới thiệu chúng tôi quen nhau. Anh ấy kể với tôi rằng, ngay từ ngày đầu tiên gặp tôi, anh ấy đã đem lòng yêu mến tôi rồi.","audio_dialogue":"14-7 @xitoytili_luoluodafang.mp3","audio_vocab":"14-8 @xitoytili_luoluodafang.mp3"}]},{"id":15,"title_cn":"我想再去一次中国","title_pinyin":"Wǒ xiǎng zài qù yí cì Zhōngguó","title_vn":"Em muốn đi Trung Quốc một lần nữa","goals":["能听懂并谈论旅游的计划。Có thể nghe hiểu và thảo luận được kế hoạch du lịch.","能听懂并使用动量补语表达动作或事情发生的次数。Có thể nghe hiểu và sử dụng được bổ ngữ động lượng để diễn đạt số lần phát sinh của động tác hoặc sự việc.","掌握\"有\"字句(2)的用法，能说明达到了一定的数量。Nắm vững cách dùng của câu chữ \"有\"(2) để nói rõ về việc đạt tới một số lượng nhất định."],"vocab":[{"hanzi":"姓名","pinyin":"xìngmíng","pos":"dt.","vn":"họ tên","examples":[{"cn":"请写上你的姓名。","pinyin":"Qǐng xiěshàng nǐ de xìngmíng.","vn":"Xin hãy viết họ tên của bạn."},{"cn":"这是我的姓名和电话号码。","pinyin":"Zhè shì wǒ de xìngmíng hé diànhuà hàomǎ.","vn":"Đây là họ tên và số điện thoại của tôi."},{"cn":"表格上要填姓名。","pinyin":"Biǎogé shàng yào tián xìngmíng.","vn":"Trên biểu mẫu cần điền họ tên."}]},{"hanzi":"出国","pinyin":"chūguó","pos":"đgt.","vn":"ra nước ngoài, xuất ngoại","examples":[{"cn":"我明年打算出国留学。","pinyin":"Wǒ míngnián dǎsuan chūguó liúxué.","vn":"Năm sau tôi định ra nước ngoài du học."},{"cn":"他出国已经三年了。","pinyin":"Tā chūguó yǐjīng sān nián le.","vn":"Anh ấy ra nước ngoài đã ba năm rồi."},{"cn":"你出过国吗?","pinyin":"Nǐ chūguò guó ma?","vn":"Bạn đã từng ra nước ngoài chưa?"}]},{"hanzi":"门票","pinyin":"ménpiào","pos":"dt.","vn":"vé vào cửa","examples":[{"cn":"这儿的门票多少钱?","pinyin":"Zhèr de ménpiào duōshao qián?","vn":"Vé vào cửa ở đây bao nhiêu tiền?"},{"cn":"我买了两张门票。","pinyin":"Wǒ mǎile liǎng zhāng ménpiào.","vn":"Tôi đã mua hai vé vào cửa."},{"cn":"学生门票有优惠吗?","pinyin":"Xuésheng ménpiào yǒu yōuhuì ma?","vn":"Vé vào cửa cho học sinh có giảm giá không?"}]},{"hanzi":"高中","pinyin":"gāozhōng","pos":"dt.","vn":"cấp ba, trung học phổ thông","examples":[{"cn":"我弟弟上高中了。","pinyin":"Wǒ dìdi shàng gāozhōng le.","vn":"Em trai tôi đã học cấp ba rồi."},{"cn":"她是高中老师。","pinyin":"Tā shì gāozhōng lǎoshī.","vn":"Cô ấy là giáo viên cấp ba."},{"cn":"高中的生活很忙。","pinyin":"Gāozhōng de shēnghuó hěn máng.","vn":"Cuộc sống cấp ba rất bận rộn."}]},{"hanzi":"出门","pinyin":"chūmén","pos":"đgt.","vn":"ra ngoài, rời nhà","examples":[{"cn":"今天我不想出门。","pinyin":"Jīntiān wǒ bù xiǎng chūmén.","vn":"Hôm nay tôi không muốn ra ngoài."},{"cn":"外面下雨了,别出门。","pinyin":"Wàimiàn xiàyǔ le, bié chūmén.","vn":"Bên ngoài mưa rồi, đừng ra ngoài."},{"cn":"他每天早上七点出门。","pinyin":"Tā měitiān zǎoshang qī diǎn chūmén.","vn":"Mỗi sáng anh ấy ra khỏi nhà lúc 7 giờ."}]},{"hanzi":"路","pinyin":"lù","pos":"dt.","vn":"con đường","examples":[{"cn":"这条路很长。","pinyin":"Zhè tiáo lù hěn cháng.","vn":"Con đường này rất dài."},{"cn":"过马路的时候要小心。","pinyin":"Guò mǎlù de shíhou yào xiǎoxīn.","vn":"Khi qua đường phải cẩn thận."},{"cn":"我不认识去那儿的路。","pinyin":"Wǒ bú rènshi qù nàr de lù.","vn":"Tôi không biết đường đến đó."}]},{"hanzi":"颐和园","pinyin":"Yíhéyuán","pos":"danh từ riêng","vn":"Di Hoà Viên (ở Bắc Kinh)","examples":[{"cn":"我们周末去颐和园玩儿吧。","pinyin":"Wǒmen zhōumò qù Yíhéyuán wánr ba.","vn":"Cuối tuần chúng ta đi Di Hòa Viên chơi đi."},{"cn":"颐和园是北京有名的公园。","pinyin":"Yíhéyuán shì Běijīng yǒumíng de gōngyuán.","vn":"Di Hòa Viên là công viên nổi tiếng ở Bắc Kinh."},{"cn":"你去过颐和园吗?","pinyin":"Nǐ qùguò Yíhéyuán ma?","vn":"Bạn đã từng đi Di Hòa Viên chưa?"}]},{"hanzi":"机场","pinyin":"jīchǎng","pos":"dt.","vn":"sân bay","examples":[{"cn":"我们去机场接他。","pinyin":"Wǒmen qù jīchǎng jiē tā.","vn":"Chúng tôi đi sân bay đón anh ấy."},{"cn":"从这儿到机场要多长时间?","pinyin":"Cóng zhèr dào jīchǎng yào duō cháng shíjiān?","vn":"Từ đây đến sân bay mất bao lâu?"},{"cn":"机场里人很多。","pinyin":"Jīchǎng lǐ rén hěn duō.","vn":"Trong sân bay có rất nhiều người."}]},{"hanzi":"机票","pinyin":"jīpiào","pos":"dt.","vn":"vé máy bay","examples":[{"cn":"我订了一张机票。","pinyin":"Wǒ dìngle yì zhāng jīpiào.","vn":"Tôi đã đặt một vé máy bay."},{"cn":"机票多少钱一张?","pinyin":"Jīpiào duōshao qián yì zhāng?","vn":"Vé máy bay bao nhiêu tiền một vé?"},{"cn":"机票已经买好了。","pinyin":"Jīpiào yǐjīng mǎihǎo le.","vn":"Vé máy bay đã mua xong rồi."}]},{"hanzi":"飞","pinyin":"fēi","pos":"đgt.","vn":"bay","examples":[{"cn":"鸟在天上飞。","pinyin":"Niǎo zài tiānshàng fēi.","vn":"Chim bay trên trời."},{"cn":"飞机飞得很高。","pinyin":"Fēijī fēi de hěn gāo.","vn":"Máy bay bay rất cao."},{"cn":"小鸟从窗户飞进来了。","pinyin":"Xiǎo niǎo cóng chuānghu fēi jìnlai le.","vn":"Con chim nhỏ bay vào từ cửa sổ."}]},{"hanzi":"好像","pinyin":"hǎoxiàng","pos":"đgt.","vn":"dường như, giống như, hình như","examples":[{"cn":"她好像不太高兴。","pinyin":"Tā hǎoxiàng bú tài gāoxìng.","vn":"Cô ấy có vẻ không vui lắm."},{"cn":"外面好像下雨了。","pinyin":"Wàimiàn hǎoxiàng xiàyǔ le.","vn":"Bên ngoài hình như đang mưa."},{"cn":"这个人好像是我的老同学。","pinyin":"Zhège rén hǎoxiàng shì wǒ de lǎo tóngxué.","vn":"Người này hình như là bạn học cũ của tôi."}]},{"hanzi":"鸟","pinyin":"niǎo","pos":"dt.","vn":"con chim","examples":[{"cn":"树上有很多鸟。","pinyin":"Shù shàng yǒu hěn duō niǎo.","vn":"Trên cây có rất nhiều chim."},{"cn":"这只鸟会唱歌。","pinyin":"Zhè zhǐ niǎo huì chànggē.","vn":"Con chim này biết hót."},{"cn":"小鸟飞走了。","pinyin":"Xiǎo niǎo fēi zǒu le.","vn":"Con chim nhỏ bay đi rồi."}]}],"grammar":[{"title":"动量补语 (1) Bổ ngữ động lượng (1)","explanation_vn":"\"Số từ + 次\" đặt sau động từ để tạo thành bổ ngữ động lượng, biểu thị số lần xảy ra của động tác. Khi tân ngữ của động từ là tên người hoặc địa danh thì có thể đặt trước hoặc sau bổ ngữ động lượng.","examples":[{"cn":"我想去中国，虽然去过一次，但是很想再去一次。","pinyin":"Wǒ xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì.","vn":""},{"cn":"安妮去过一次北京。","pinyin":"Ānnī qùguo yí cì Běijīng.","vn":""},{"cn":"李文见了杨同乐两次。","pinyin":"Lǐ Wén jiànle Yáng Tóngyuè liǎng cì.","vn":""}]},{"title":"动量补语 (2) Bổ ngữ động lượng (2)","explanation_vn":"Khi động từ vừa mang bổ ngữ động lượng vừa mang tân ngữ, nếu tân ngữ là danh từ chỉ sự vật thì thường đặt sau bổ ngữ động lượng; nếu tân ngữ là đại từ thì đặt trước bổ ngữ động lượng.","examples":[{"cn":"因为我想再吃一次烤鸭，再喝一次奶茶。","pinyin":"Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá.","vn":""},{"cn":"我想找他一次。","pinyin":"Wǒ xiǎng zhǎo tā yí cì.","vn":""},{"cn":"安妮来过这儿两次。","pinyin":"Ānnī láiguo zhèr liǎng cì.","vn":""}]},{"title":"\"有\"字句 (2) Câu chữ \"有\" (2)","explanation_vn":"\"有 + cụm từ chỉ số lượng\" biểu thị sự việc đạt đến một số lượng nhất định.","examples":[{"cn":"你有一年没回国了吧？","pinyin":"Nǐ yǒu yì nián méi huí guó le ba?","vn":""},{"cn":"你女儿今年有10岁了吗？","pinyin":"Nǐ nǚ'ér jīnnián yǒu shí suì le ma?","vn":""},{"cn":"我有一个月没给家里打电话了。","pinyin":"Wǒ yǒu yí ge yuè méi gěi jiā lǐ dǎ diànhuà le.","vn":""}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"Vương Nhất Phi","cn":"考试就要开始了，请大家写上姓名，写好后就可以做题了。","pinyin":"Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiěshàng xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le."},{"speaker":"Bạch Gia Nguyệt","cn":"老师，我做完了。","pinyin":"Lǎoshī, wǒ zuòwán le."},{"speaker":"Trần Thiên Trung","cn":"老师，我也做完了。","pinyin":"Lǎoshī, wǒ yě zuòwán le."},{"speaker":"Vương Nhất Phi","cn":"……对了，你们考完试想做什么？","pinyin":"Duìle, nǐmen kǎowán shì xiǎng zuò shénme?"},{"speaker":"Bạch Gia Nguyệt","cn":"我很想去中国，虽然去过一次，但是很想再去一次。","pinyin":"Wǒ hěn xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì."},{"speaker":"Vương Nhất Phi","cn":"不错，到中国后你就可以经常说中文了。","pinyin":"Búcuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le."}],"translation_vn":"Vương Nhất Phi: Sắp bắt đầu vào giờ thi rồi, mời các em viết họ tên mình vào, viết xong là có thể làm bài. Bạch Gia Nguyệt: Thưa cô, em làm xong rồi ạ. Trần Thiên Trung: Thưa cô, em cũng làm xong rồi ạ. Vương Nhất Phi: Đúng rồi, thi xong các em muốn làm gì? Bạch Gia Nguyệt: Em rất muốn đi Trung Quốc, tuy đã từng đi một lần rồi nhưng em rất muốn đi thêm một lần nữa. Vương Nhất Phi: Tốt lắm, sau khi đến Trung Quốc em có thể thường xuyên nói tiếng Trung Quốc rồi.","audio_dialogue":"15-1 @xitoytili_luoluodafang.mp3","audio_vocab":"15-2 @xitoytili_luoluodafang.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"Bạch Gia Nguyệt","cn":"考完试了，我现在可以出国旅游了。","pinyin":"Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le."},{"speaker":"Lý Văn","cn":"你要去哪儿？","pinyin":"Nǐ yào qù nǎr?"},{"speaker":"Bạch Gia Nguyệt","cn":"我要再去一次北京。","pinyin":"Wǒ yào zài qù yí cì Běijīng."},{"speaker":"Lý Văn","cn":"为什么还去北京？","pinyin":"Wèi shénme hái qù Běijīng?"},{"speaker":"Bạch Gia Nguyệt","cn":"因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……","pinyin":"Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng……"},{"speaker":"Lý Văn","cn":"你想做的事情很多啊！","pinyin":"Nǐ xiǎng zuò de shìqing hěn duō a!"},{"speaker":"Bạch Gia Nguyệt","cn":"是啊，你看，我还在网上买好颐和园的门票了呢。","pinyin":"Shì a, nǐ kàn, wǒ hái zài wǎngshàng mǎihǎo Yíhéyuán de ménpiào le ne."},{"speaker":"Lý Văn","cn":"我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。","pinyin":"Wǒ de gāozhōng tóngxué jiù zài Yíhéyuán shàngbān, kěyǐ ràng tā gěi nǐ hǎohǎo jièshào jièshào."}],"translation_vn":"Bạch Gia Nguyệt: Thi xong rồi, bây giờ mình có thể đi du lịch nước ngoài được rồi. Lý Văn: Bạn định đi đâu? Bạch Gia Nguyệt: Mình muốn đi Bắc Kinh một lần nữa. Lý Văn: Tại sao vẫn đi Bắc Kinh? Bạch Gia Nguyệt: Vì mình muốn ăn vịt quay một lần nữa, uống trà sữa một lần nữa, đến Đại học Bắc Kinh xem phim một lần nữa. Lý Văn: Những việc bạn muốn làm nhiều thật đấy! Bạch Gia Nguyệt: Đúng vậy, bạn xem này, mình còn mua sẵn vé vào cổng Di Hoà Viên trên mạng rồi đấy nhé. Lý Văn: Bạn học thời phổ thông của mình đang làm việc ngay tại Di Hoà Viên, có thể bảo cậu ấy giới thiệu thật kĩ cho bạn.","audio_dialogue":"15-3.mp3","audio_vocab":"15-4.mp3"},{"label":"Bài khóa 3","type":"dialogue","lines":[{"speaker":"Bạch Gia Nguyệt","cn":"李文，你有一年没回国了吧？","pinyin":"Lǐ Wén, nǐ yǒu yì nián méi huí guó le ba?"},{"speaker":"Lý Văn","cn":"不到一年。我六月的时候回去了一次。","pinyin":"Bú dào yì nián. Wǒ Liùyuè de shíhou huíqù le yí cì."},{"speaker":"Bạch Gia Nguyệt","cn":"我怎么忘了？还是我送你去的机场呢。","pinyin":"Wǒ zěnme wàng le? Hái shì wǒ sòng nǐ qù de jīchǎng ne."},{"speaker":"Lý Văn","cn":"是啊。","pinyin":"Shì a."},{"speaker":"Bạch Gia Nguyệt","cn":"我记得你那次的机票很便宜。","pinyin":"Wǒ jìde nǐ nà cì de jīpiào hěn piányi."},{"speaker":"Lý Văn","cn":"没错，可能因为那个时候去北京的人不多吧。","pinyin":"Méi cuò, kěnéng yīnwèi nàge shíhou qù Běijīng de rén bù duō ba."},{"speaker":"Bạch Gia Nguyệt","cn":"这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","pinyin":"Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de."}],"translation_vn":"Bạch Gia Nguyệt: Lý Văn, bạn cũng cả năm rồi chưa về nước lần nào nhỉ? Lý Văn: Chưa đến một năm đâu. Hồi tháng Sáu mình có về một lần. Bạch Gia Nguyệt: Sao mình lại quên mất nhỉ? Chính là mình tiễn bạn ra sân bay mà. Lý Văn: Đúng rồi. Bạch Gia Nguyệt: Mình nhớ lần đó vé máy bay của bạn rẻ lắm. Lý Văn: Đúng vậy, chắc do dạo đó không có nhiều người đi Bắc Kinh chăng. Bạch Gia Nguyệt: Vé máy bay lần này tuy hơi đắt một chút, nhưng cứ nghĩ đến việc sắp được bay đến Bắc Kinh là mình vẫn thấy rất háo hức.","audio_dialogue":"15-5.mp3","audio_vocab":"15-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"我六月的时候回过一次北京，现在有半年多没回去了，我有点儿想家。就要过年了，我要回国过年。家月这次也要去北京，我们都是星期五的飞机。家月说我们好像小鸟，一起飞到北京，再一起飞回这里。","pinyin":"Wǒ Liùyuè de shíhou huíguo yí cì Běijīng, xiànzài yǒu bàn nián duō méi huíqù le, wǒ yǒudiǎnr xiǎng jiā. Jiù yào guònián le, wǒ yào huí guó guònián. Jiāyuè zhè cì yě yào qù Běijīng, wǒmen dōu shì Xīngqīwǔ de fēijī. Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēidào Běijīng, zài yìqǐ fēihuí zhèlǐ."}],"translation_vn":"Hồi tháng Sáu tôi từng về Bắc Kinh một lần, đến nay đã hơn nửa năm chưa về rồi, tôi thấy hơi nhớ nhà. Năm mới sắp đến rồi, tôi phải về nhà đón Tết thôi. Lần này Gia Nguyệt cũng đi về Bắc Kinh, chúng tôi đều đi chuyến bay ngày thứ Sáu. Gia Nguyệt nói chúng tôi giống như đôi chim nhỏ vậy, cùng nhau bay đến Bắc Kinh rồi lại cùng nhau bay trở về đây.","audio_dialogue":"15-7.mp3","audio_vocab":"15-8.mp3"}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};